        { env: { ...env, CODING_WF_PROVIDER: 'codex', CODING_WF_CODEX_BIN: bin, CODING_WF_CODEX_HOME: temp, CODING_WF_EVALUATE_TIMEOUT_MS: '15000' }, stdio: ['pipe', 'pipe', 'pipe'], timeout: 20000 });
