      description: '验收：①X ②Y ③Z',
      payload: { acceptance: ['A', 'B'] },
    });
    expect(items).toEqual(['A', 'B']);
  });

  it.each([
    ['圈号', '背景说明\n验收：①A ②B'],
    ['编号列表', '背景说明\n验收\n1. A\n2. B'],
    ['复选框列表', '背景说明\n验收\n- [ ] A\n- [ ] B'],
