  it('开发采纳后关闭 → 第 2 轮通过；留下 02-response-r1.md，规格已改且 spec_sha256 为新哈希', async () => {
    const r = await run({ reviews: [
      { scores: 6, issues: [blocker('R-1')] },
      { scores: 8, prior: [{ id: 'R-1', status: '关闭' }] },
    ] });
