    worktree = fs.mkdtempSync(path.join(os.tmpdir(), 'spec-test-'));
    pidDir = fs.mkdtempSync(path.join(os.tmpdir(), 'spec-pids-')); // 不放进 worktree，免得被当成越界写
    gitPlain('init', '-q', worktree);
  });
  afterEach(() => {
    fs.rmSync(worktree, { recursive: true, force: true });
