// 真实runJudge→prompt→Codex适配器→本地CLI stdin；仅来源事实供应接缝可控。
// 本文件不证明来源事实本身真实，不访问模型、网络、数据库或运行仓。
import { describe, it, expect, vi, afterEach } from 'vitest';
