const TITLE = 'docs(sprint): 11111111 md 链 01-intent → 02-spec';

describe('publish 活动（临时裸仓 + 假 gh）', () => {
  let root;
  let origin;
  let worktree;
  let ghLog;
  let activityEntry;

  beforeAll(() => {
    fs.chmodSync(FAKE_GH, 0o755);
  });
  beforeEach(() => {
    root = fs.mkdtempSync(path.join(os.tmpdir(), 'publish-test-'));
    origin = path.join(root, 'origin.git');
    worktree = path.join(root, 'wt');
    ghLog = path.join(root, 'gh.log');
    activityEntry = ENTRY;
    gitPlain('init', '--bare', '-b', 'main', origin);
    gitPlain('clone', origin, worktree);
    git(worktree, 'config', 'user.name', 'Test');
    git(worktree, 'config', 'user.email', 'test@example.com');
    fs.writeFileSync(path.join(worktree, 'README.md'), 'hi\n');
    git(worktree, 'add', '--', 'README.md');
    git(worktree, 'commit', '-m', 'init');
    git(worktree, 'push', '-u', 'origin', 'main');
    git(worktree, 'checkout', '-b', 'cp-1007000000-test');
    fs.mkdirSync(path.join(worktree, 'sprints/s1'), { recursive: true });
    fs.writeFileSync(path.join(worktree, 'sprints/s1/01-intent.md'), '# intent\n');
    fs.writeFileSync(path.join(worktree, 'sprints/s1/02-spec.md'), '# spec\n');
  });
  afterEach(() => {
    fs.rmSync(root, { recursive: true, force: true });
  });

  const input = (patch = {}) => ({
    run_tag: 'rt-1',
    task_id: TASK_ID,
    worktree,
    sprint_dir: 'sprints/s1',
    chain_files: ['01-intent.md', '02-spec.md'],
    ...patch,
  });
  const run = (mode, patch, extraEnv = {}) =>
    runActivityProcess(activityEntry, input(patch), {
      CODING_WF_GH_BIN: FAKE_GH,
      FAKE_GH_MODE: mode,
      FAKE_GH_LOG: ghLog,
      ...extraEnv,
    });
  const ghCalls = () =>
    fs.existsSync(ghLog)
      ? fs.readFileSync(ghLog, 'utf8').trim().split('\n').filter(Boolean).map((l) => JSON.parse(l))
      : [];

  it('new：提交并推送分支，开草稿 PR，输出新 URL 与分支', async () => {
    const r = await run('new');
    expect(r.exitCode).toBe(0);
    expect(r.result.failure_class).toBeNull();
    expect(r.result.outputs).toEqual({ pr_url: 'https://github.com/example/repo/pull/2', branch: 'cp-1007000000-test' });
    expect(r.stdout.trim().split('\n')).toHaveLength(1);

    const files = git(origin, 'ls-tree', '-r', '--name-only', 'cp-1007000000-test').trim().split('\n');
    expect(files).toContain('sprints/s1/01-intent.md');
    expect(files).toContain('sprints/s1/02-spec.md');
    expect(git(origin, 'log', '-1', '--format=%s', 'cp-1007000000-test').trim()).toBe(TITLE);

    const create = ghCalls().find((a) => a[0] === 'pr' && a[1] === 'create');
    expect(create).toBeDefined();
    expect(create).toContain('--draft');
    expect(create[create.indexOf('--head') + 1]).toBe('cp-1007000000-test');
    expect(create[create.indexOf('--title') + 1]).toBe(TITLE);
    const body = create[create.indexOf('--body') + 1];
    expect(body).toContain('- sprints/s1/01-intent.md');
    expect(body).toContain('- sprints/s1/02-spec.md');
  });

  it('Cecelia 发布将当前任务 Markdown 与精确来源关系同提交，重复发布不重复登记', async () => {
    const branch = 'cp-10152110-cw-11111111', sprint = 'sprints/10152110-cw-11111111';
    const owner = 'packages/brain/scripts/coding-workflow/runner/run-once.mjs';
    git(worktree, 'checkout', '-b', branch);
    git(worktree, 'remote', 'set-url', '--push', 'origin', origin);
    git(worktree, 'remote', 'set-url', 'origin', 'https://github.com/perfectuser21/cecelia.git');
    fs.mkdirSync(path.join(worktree, path.dirname(owner)), { recursive: true });
    fs.writeFileSync(path.join(worktree, owner), '// fixture runner\n');
    const original = '{"schema_version":1,"repo":"perfectuser21/cecelia","relations":[\n  {"owner_path":"'+owner+'","path":"README.md","role":"documentation"}\n]}\n';
    fs.writeFileSync(path.join(worktree, '.implementation-source-relations.json'), original);
    git(worktree, 'add', '--', owner, '.implementation-source-relations.json'); git(worktree, 'commit', '-m', 'fixture source');git(worktree, 'update-ref', 'refs/remotes/origin/main', 'HEAD');
    fs.mkdirSync(path.join(worktree, sprint));
    fs.writeFileSync(path.join(worktree, sprint, '01-intent.md'), `---\ntask_id: ${TASK_ID}\nstep: intent\nupstream: []\n---\n# fixture\n`);
    const names = ['01-intent.md','01-invariants.md','02-spec.md','02-review.md','02-review-r1.md','02-review-r2.md','02-review-r3.md','02-response-r1.md','02-response-r2.md','03-build.md','04-evidence.md'];
    const context = { root: path.join(root, 'protected'), worktree, taskId: TASK_ID, sprintDir: sprint,
      controller: controllerIdentity(pathToFileURL(ENTRY)) };
    for (const name of names) {
      const stage = name.startsWith('01-') ? 'intent' : name === '02-spec.md' ? 'spec'
        : name.startsWith('02-') ? 'spec_review' : name.startsWith('03-') ? 'build' : 'verify';
      const round = Number(/-r(\d+)/.exec(name)?.[1] ?? 0);
      if (name !== '01-intent.md') fs.writeFileSync(path.join(worktree, sprint, name),
        name === '01-invariants.md' || name.startsWith('02-response-') ? `# fixture ${name}\n`
          : `---\ntask_id: ${TASK_ID}\nstep: ${stage}\nupstream: []\n---\n# fixture ${name}\n`);
      withRecordProvenance({ ...context, stage, round }, () => {
        if (stage !== 'intent') captureNativeExecution({ provider: 'codex', code: 0, stdout:
          '{"type":"thread.started","thread_id":"fixture"}\n{"type":"turn.completed"}\n' });
        sealStageEvidence({ files: [`${sprint}/${name}`], producer: stage === 'intent' ? 'controller' : 'model', result: { status: 'completed' } });
      });
    }
    // 仅测试启动器注入显式隔离根；生产活动不接受任务 JSON / 环境变量覆盖。
    activityEntry = path.join(root, 'publish-with-fixture-root.mjs');
    fs.writeFileSync(activityEntry, `import { withRecordProvenance } from ${JSON.stringify(new URL('../lib/record-provenance.mjs', import.meta.url).href)};\nawait withRecordProvenance(${JSON.stringify({ ...context, stage: 'publish' })}, () => import(${JSON.stringify(pathToFileURL(ENTRY).href)}));\n`);
    const r = await run('new', { sprint_dir: sprint });
    expect(r.exitCode, r.stderr).toBe(0);
    const manifest = JSON.parse(git(origin, 'show', `${branch}:.implementation-source-relations.json`));
    for (const name of names) expect(manifest.relations).toContainEqual({ owner_path: owner, path: `${sprint}/${name}`, role: 'documentation' });
    expect(manifest.relations).toHaveLength(names.length + 1);
    expect(git(origin, 'show', '--name-only', '--format=', branch).trim().split('\n')).toEqual(['.implementation-source-relations.json', ...names.map(name => `${sprint}/${name}`)].sort());
    const head = git(worktree, 'rev-parse', 'HEAD');
    expect((await run('existing', { sprint_dir: sprint })).exitCode).toBe(0);
    expect(git(worktree, 'rev-parse', 'HEAD')).toBe(head);
  });

  // 原始 ZJ L1 脚本验真 publish 的 GH 正文，不重写 lint 正则。
  const lintBody = (body) => spawnSync(
    fs.existsSync('/opt/homebrew/bin/bash') ? '/opt/homebrew/bin/bash' : 'bash',
    [path.join(HERE, 'fixtures/zenithjoy-gp-anchor/.github/workflows/scripts/lint-gp-anchor.sh')],
    { env: { ...process.env, PR_BODY: body }, encoding: 'utf8' },
  );
  it.each(['none(infra)', 'none(docs)', 'none(config)',
    'line02/benchmark_link_acquisition#step1', 'line02/benchmark_link_acquisition keep-green'])(
    'gp_anchor=%s 原值进入唯一声明，真实 ZJ lint 通过', async (gp_anchor) => {
      const r = await run('new', { gp_anchor });
      expect(r.exitCode, r.stderr).toBe(0);
      expect(prBody().split('\n').filter((line) => line.startsWith('GP-Anchor:'))).toEqual([`GP-Anchor: ${gp_anchor}`]);
      const lint = lintBody(prBody());
      expect(lint.status, lint.stdout + lint.stderr).toBe(0);
      const duplicate = lintBody(`${prBody()}\nGP-Anchor: none(infra)`);
      expect(duplicate.status).toBe(1);
      expect(duplicate.stdout).toContain('GP-ANCHOR-MULTIPLE');
    },
  );
  it('缺失锚点保留既有不声明行为；不从 .dev-mode 缺省伪造豁免，ZJ lint 仍拒绝', async () => {
    fs.writeFileSync(path.join(worktree, '.dev-mode.cp-1007000000-test'), 'gp_anchor: none(infra)\n');
    expect((await run('new')).exitCode).toBe(0);
    expect(prBody()).not.toContain('GP-Anchor:');
    const lint = lintBody(prBody());
    expect(lint.status).toBe(1);
    expect(lint.stdout).toContain('GP-ANCHOR-MISSING');
  });
  it('未知业务锚原值转呈，由 ZJ 原规则拒绝，不能改为 infra', async () => {
    expect((await run('new', { gp_anchor: 'line02/no_such_gp#step1' })).exitCode).toBe(0);
    expect(prBody()).toContain('GP-Anchor: line02/no_such_gp#step1');
    const lint = lintBody(prBody());
    expect(lint.status).toBe(1);
    expect(lint.stdout).toContain('GP-ANCHOR-ID-NOTFOUND');
  });
  it.each(['none(infra)\nGP-Anchor: none(docs)', 'none(infra)\rhidden', 'none(infra)\u0000', '', '   ', 42, {}, null])(
    '非法 gp_anchor=%j 在 git/gh 副作用之前拒绝', async (gp_anchor) => {
      const r = await run('new', { gp_anchor });
      expect(r.result.reason_code).toBe('gp_anchor_invalid');
      expect(r.result.failure_class).toBe('fatal');
      expect(ghCalls()).toEqual([]);
      expect(git(worktree, 'log', '--oneline').trim().split('\n')).toHaveLength(1);
      expect(() => git(origin, 'rev-parse', '--verify', 'refs/heads/cp-1007000000-test')).toThrow();
    },
  );

  it('四文件链 + verified_ids：含代码提交时标题为 feat(workflow): <01-intent 标题>，PR 正文追加每条 I-n 的验收摘要', async () => {
    fs.writeFileSync(path.join(worktree, 'sprints/s1/01-intent.md'), '---\ntask_id: x\nstep: intent\nupstream: []\n---\n# 登录功能  \n\n### I-1\n能登录\n');
    fs.writeFileSync(path.join(worktree, 'sprints/s1/03-build.md'), '# build\n');
    fs.writeFileSync(path.join(worktree, 'sprints/s1/04-evidence.md'), '# evidence\n');
    const r = await run('new', {
      chain_files: ['01-intent.md', '02-spec.md', '03-build.md', '04-evidence.md'],
      evidence_file: '04-evidence.md',
      verified_ids: ['I-1', 'I-2'],
    });
    expect(r.exitCode, r.stderr).toBe(0);
    const title = 'feat(workflow): 登录功能';
    expect(git(origin, 'log', '-1', '--format=%s', 'cp-1007000000-test').trim()).toBe(title);
    const create = ghCalls().find((a) => a[0] === 'pr' && a[1] === 'create');
    expect(create[create.indexOf('--title') + 1]).toBe(title);
    const body = create[create.indexOf('--body') + 1];
    expect(body).toContain('- sprints/s1/04-evidence.md');
    expect(body).toContain('## 验收摘要（sprints/s1/04-evidence.md）');
    expect(body).toContain('- I-1：PASS');
    expect(body).toContain('- I-2：PASS');
  });

  it.each(['修复登录超时', 'fix crash on start', 'Bug: 退出按钮无效', 'FIX 空指针'])(
    '含代码提交且 01-intent 标题以 bug/修复/fix 开头（%s）-> fix(workflow):',
    async (heading) => {
      fs.writeFileSync(path.join(worktree, 'sprints/s1/01-intent.md'), `# ${heading}\n\n### I-1\nx\n`);
      fs.writeFileSync(path.join(worktree, 'sprints/s1/03-build.md'), '# build\n');
      const r = await run('new', { chain_files: ['01-intent.md', '02-spec.md', '03-build.md'] });
      expect(r.exitCode, r.stderr).toBe(0);
      const create = ghCalls().find((a) => a[0] === 'pr' && a[1] === 'create');
      expect(create[create.indexOf('--title') + 1]).toBe(`fix(workflow): ${heading}`);
    },
  );

  it('含代码提交但 01-intent 没有 # 标题 -> feat(workflow): coding workflow <task_id 前 8 位>', async () => {
    fs.writeFileSync(path.join(worktree, 'sprints/s1/01-intent.md'), '### I-1\nx\n');
    fs.writeFileSync(path.join(worktree, 'sprints/s1/03-build.md'), '# build\n');
    const r = await run('new', { chain_files: ['01-intent.md', '02-spec.md', '03-build.md'] });
    expect(r.exitCode, r.stderr).toBe(0);
    expect(git(origin, 'log', '-1', '--format=%s', 'cp-1007000000-test').trim()).toBe('feat(workflow): coding workflow 11111111');
  });

  it('上下文没有 verified_ids：PR 正文不带验收摘要', async () => {
    const r = await run('new', { verified_ids: 'I-1' });
    expect(r.exitCode).toBe(0);
    const create = ghCalls().find((a) => a[0] === 'pr' && a[1] === 'create');
    expect(create[create.indexOf('--body') + 1]).not.toContain('验收摘要');
  });

  const REVIEW_V2 = [
    '---', 'task_id: x', 'step: spec_review', 'upstream: ["02-spec.md#S-1"]', '---', '# 规格评审', '',
    '## 评分', '意图对齐: 8', '可验证: 7', '场景覆盖: 9', '回归风险: 7', '可执行: 8', '',
    '### R-3', '针对: S-1', '严重度: 建议', 'R-3 第一行说明', 'R-3 第二行细节', '',
    '### R-4', '针对: I-1, S-2', '严重度: 重要', '场景: 用户重复提交', '依据: x.mjs', 'R-4 唯一一行', '',
  ].join('\n');
  const reviewCtx = (gan) => ({
    chain_files: ['01-intent.md', '02-spec.md', '02-review.md'],
    review_file: '02-review.md',
    review_rounds: gan.rounds,
    gan,
  });
  const prBody = () => {
    const create = ghCalls().find((a) => a[0] === 'pr' && a[1] === 'create');
    return create[create.indexOf('--body') + 1];
  };

  it('有 review_file：PR 正文含合同对抗小节（轮数、结论与走势、最终评分、末轮每条问题的严重度与首行）', async () => {
    fs.writeFileSync(path.join(worktree, 'sprints/s1/02-review.md'), REVIEW_V2);
    const r = await run('new', reviewCtx({ verdict: 'APPROVED', rounds: 2, trend: 'insufficient_data', open_issues: [], cost_usd: 1.2 }));
    expect(r.exitCode, r.stderr).toBe(0);
    const body = prBody();
    expect(body).toContain('## 合同对抗（sprints/s1/02-review.md）');
    expect(body).toContain('- 轮数：2');
    expect(body).toContain('- 结论：APPROVED（走势 insufficient_data，花费 $1.2）');
    expect(body).toContain('- 最终评分：意图对齐 8 / 可验证 7 / 场景覆盖 9 / 回归风险 7 / 可执行 8');
    expect(body).toContain('- R-3［建议］（针对 S-1）：R-3 第一行说明');
    expect(body).not.toContain('R-3 第二行细节');
    expect(body).toContain('- R-4［重要］（针对 I-1、S-2）：R-4 唯一一行');
    expect(body).not.toContain('强制通过');
  });

  it('强制通过（FORCED）：PR 正文醒目标出仍开着的问题', async () => {
    fs.writeFileSync(path.join(worktree, 'sprints/s1/02-review.md'), REVIEW_V2);
    const r = await run('new', reviewCtx({ verdict: 'FORCED', rounds: 3, trend: 'oscillating', open_issues: [{ id: 'R-1', severity: '阻断', targets: ['S-1'] }], cost_usd: 3 }));
    expect(r.exitCode, r.stderr).toBe(0);
    expect(prBody()).toContain('- ⚠️ 强制通过（走势 oscillating），仍开着：R-1［阻断］');
  });

  // 审计 #10：02 的「未覆盖真实链路」原样转呈 PR 正文，主理人一眼看到哪些没真验
  it('02 有「## 未覆盖真实链路」→ PR 正文原样转呈；没有这一段 → 不出现', async () => {
    fs.writeFileSync(path.join(worktree, 'sprints/s1/02-spec.md'), '# spec\n\n## 未覆盖真实链路\n\n- 飞书推送：预览环境无凭据，只验到落库\n');
    let r = await run('new');
    expect(r.exitCode, r.stderr).toBe(0);
    expect(prBody()).toContain('## 未覆盖真实链路（sprints/s1/02-spec.md）\n- 飞书推送：预览环境无凭据，只验到落库');
  });

  it('无 review_file：PR 正文不带规格评审小节', async () => {
    const r = await run('new');
    expect(r.exitCode).toBe(0);
    const create = ghCalls().find((a) => a[0] === 'pr' && a[1] === 'create');
    expect(create[create.indexOf('--body') + 1]).not.toContain('规格评审');
  });

  it('existing：复用已有 PR，不再 pr create', async () => {
    const r = await run('existing');
    expect(r.exitCode).toBe(0);
    expect(r.result.outputs).toEqual({ pr_url: 'https://github.com/example/repo/pull/1', branch: 'cp-1007000000-test' });
    expect(ghCalls().some((a) => a[1] === 'create')).toBe(false);
  });

  it('无改动再跑一次：不新增 commit，仍 completed', async () => {
    const first = await run('new');
    expect(first.exitCode).toBe(0);
    const before = git(worktree, 'rev-parse', 'HEAD').trim();
    const second = await run('existing');
    expect(second.exitCode).toBe(0);
    expect(second.result.failure_class).toBeNull();
    expect(git(worktree, 'rev-parse', 'HEAD').trim()).toBe(before);
  });

  it('gh 鉴权失败 -> needs_human gh_auth', async () => {
    const r = await run('auth');
    expect(r.exitCode).toBe(2);
    expect(r.result.failure_class).toBe('needs_human');
    expect(r.result.reason_code).toBe('gh_auth');
    expect(r.stdout.trim().split('\n')).toHaveLength(1);
  });

  it('push 失败（origin 不可用）-> retryable push_failed', async () => {
    git(worktree, 'remote', 'set-url', 'origin', path.join(root, 'no-such.git'));
    const r = await run('new');
    expect(r.exitCode).toBe(2);
    expect(r.result.failure_class).toBe('retryable');
    expect(r.result.reason_code).toBe('push_failed');
  });

  it('分支为 main -> fatal branch_invalid，且未暂存任何文件', async () => {
    git(worktree, 'checkout', 'main');
    const r = await run('new');
    expect(r.exitCode).toBe(2);
    expect(r.result.failure_class).toBe('fatal');
    expect(r.result.reason_code).toBe('branch_invalid');
    expect(git(worktree, 'status', '--porcelain')).toContain('?? sprints/');
    expect(() => git(origin, 'rev-parse', '--verify', 'refs/heads/main')).not.toThrow();
    expect(() => git(origin, 'rev-parse', '--verify', 'refs/heads/cp-1007000000-test')).toThrow();
    expect(ghCalls()).toHaveLength(0);
  });

  it('gh 非鉴权类失败（网络超时）-> retryable gh_failed', async () => {
    const r = await run('branchfail');
    expect(r.exitCode).toBe(2);
    expect(r.result.failure_class).toBe('retryable');
    expect(r.result.reason_code).toBe('gh_failed');
  });

  it('只提交 sprint_dir：目录外的未跟踪文件与已暂存文件不进 origin 分支', async () => {
    fs.writeFileSync(path.join(worktree, 'extra.txt'), 'untracked\n');
    fs.writeFileSync(path.join(worktree, 'staged.txt'), 'staged\n');
    git(worktree, 'add', '--', 'staged.txt');
    const r = await run('new');
    expect(r.exitCode).toBe(0);
    const files = git(origin, 'ls-tree', '-r', '--name-only', 'cp-1007000000-test').trim().split('\n');
    expect(files).toContain('sprints/s1/01-intent.md');
    expect(files).not.toContain('extra.txt');
    expect(files).not.toContain('staged.txt');
  });

  it.each(['.', './', ':/', ':(top)'])('sprint_dir=%s 不能扩大提交范围', async (bad) => {
    fs.writeFileSync(path.join(worktree, 'extra.txt'), 'untracked\n');
    const r = await run('new', { sprint_dir: bad });
    expect(r.exitCode).toBe(2);
    expect(r.result.failure_class).toBe('fatal');
    expect(() => git(origin, 'rev-parse', '--verify', 'refs/heads/cp-1007000000-test')).toThrow();
    expect(git(worktree, 'log', '--oneline').trim().split('\n')).toHaveLength(1);
  });

  it('sprint_dir 非法 -> fatal sprint_dir_invalid，不碰 git/gh', async () => {
    const r = await run('new', { sprint_dir: 'a/../../b' });
    expect(r.exitCode).toBe(2);
    expect(r.result.failure_class).toBe('fatal');
    expect(r.result.reason_code).toBe('sprint_dir_invalid');
    expect(git(worktree, 'log', '--oneline').trim().split('\n')).toHaveLength(1);
    expect(ghCalls()).toHaveLength(0);
  });

  it('task_id 与 sprint_dir 同时非法 -> 先报 task_id_missing', async () => {
    const r = await run('new', { task_id: '', sprint_dir: 'a/../../b' });
    expect(r.result.reason_code).toBe('task_id_missing');
    expect(ghCalls()).toHaveLength(0);
  });

  it('继承的 GIT_DIR/GIT_WORK_TREE/GIT_INDEX_FILE 不影响提交（子进程已剥离）', async () => {
    const r = await run('new', {}, {
      GIT_DIR: path.join(root, 'bogus.git'),
      GIT_WORK_TREE: path.join(root, 'bogus-wt'),
      GIT_INDEX_FILE: path.join(root, 'bogus-index'),
    });
    expect(r.exitCode).toBe(0);
    const files = git(origin, 'ls-tree', '-r', '--name-only', 'cp-1007000000-test').trim().split('\n');
    expect(files).toContain('sprints/s1/01-intent.md');
  });

  it.each(['cp-test', 'cp-123-x', 'cp-1007000000-', 'cp-1007000000-Upper', 'feature/x', 'cp-12345678901-x'])(
    '分支名 %s 与全局 pre-commit 钩子正则不一致 -> fatal branch_invalid',
    async (name) => {
      git(worktree, 'checkout', '-b', name);
      const r = await run('new');
      expect(r.exitCode).toBe(2);
      expect(r.result.failure_class).toBe('fatal');
      expect(r.result.reason_code).toBe('branch_invalid');
      expect(ghCalls()).toHaveLength(0);
    },
  );

  it('分支名 cp-<8位时间戳>-name 合规 -> 通过', async () => {
    git(worktree, 'checkout', '-b', 'cp-10071451-fix_x-1');
    const r = await run('new');
    expect(r.exitCode).toBe(0);
    expect(r.result.outputs.branch).toBe('cp-10071451-fix_x-1');
  });

  it('commit 失败 -> fatal git_commit_failed，evidence 带 stderr 尾部（最多 20 行）', async () => {
    const hooks = path.join(worktree, '.git/hooks');
    fs.mkdirSync(hooks, { recursive: true });
    fs.writeFileSync(
      path.join(hooks, 'pre-commit'),
      '#!/bin/sh\ni=1\nwhile [ $i -le 30 ]; do echo "hook line $i" >&2; i=$((i+1)); done\nexit 1\n',
    );
    fs.chmodSync(path.join(hooks, 'pre-commit'), 0o755);
    git(worktree, 'config', 'core.hooksPath', hooks);
    const r = await run('new');
    expect(r.exitCode).toBe(2);
    expect(r.result.failure_class).toBe('fatal');
    expect(r.result.reason_code).toBe('git_commit_failed');
    const tail = r.result.evidence[0].stderr_tail;
    expect(tail).toHaveLength(20);
    expect(tail[tail.length - 1]).toBe('hook line 30');
    expect(tail[0]).toBe('hook line 11');
  });

  // 改了 packages/brain/src 的 PR 必须带 changes/<分支>.md 版本碎片（scripts/ci/check-brain-version-bump.sh，
  // 约定见 changes/README.md：PR 不碰版本五件套），否则 brain-version-bump-gate 必红（4ac5fa39 首跑实证）
  const BUILD_CHAIN = { chain_files: ['01-intent.md', '02-spec.md', '03-build.md'] };
  const FRAG = 'changes/cp-1007000000-test.md';
  const branchFiles = () => git(origin, 'ls-tree', '-r', '--name-only', 'cp-1007000000-test').trim().split('\n');
  const commitSrc = () => {
    fs.mkdirSync(path.join(worktree, 'packages/brain/src/routes'), { recursive: true });
    fs.writeFileSync(path.join(worktree, 'packages/brain/src/routes/x.js'), 'export const x = 1;\n');
    git(worktree, 'add', '--', 'packages');
    git(worktree, 'commit', '-m', 'fix(brain): x');
    fs.writeFileSync(path.join(worktree, 'sprints/s1/01-intent.md'), '# 修复 Brain 非法 id 返回 500\n\n### I-1\n非法 id 返回 400\n');
    fs.writeFileSync(path.join(worktree, 'sprints/s1/03-build.md'), '# build\n');
  };

  it('改了 packages/brain/src 且没有碎片 → 自动写 changes/<分支>.md（{VERSION} 占位 + 需求标题），随 sprint 一起提交', async () => {
    commitSrc();
    const r = await run('new', BUILD_CHAIN);
    expect(r.exitCode, r.stderr).toBe(0);
    expect(branchFiles()).toContain(FRAG);
    const frag = git(origin, 'show', `cp-1007000000-test:${FRAG}`);
    expect(frag).toMatch(/^## Brain \{VERSION\} — 修复 Brain 非法 id 返回 500\n/);
    expect(frag).toContain(TASK_ID.slice(0, 8));
    expect(frag).toContain('sprints/s1');
    expect(git(origin, 'show', '--name-only', '--format=', 'cp-1007000000-test').trim().split('\n')).toContain(FRAG);
  });

  it('分支上已带碎片 → 不再写', async () => {
    commitSrc();
    fs.mkdirSync(path.join(worktree, 'changes'), { recursive: true });
    fs.writeFileSync(path.join(worktree, 'changes/own.md'), '## Brain {VERSION} — own\n');
    git(worktree, 'add', '--', 'changes');
    git(worktree, 'commit', '-m', 'docs: frag');
    const r = await run('new', BUILD_CHAIN);
    expect(r.exitCode, r.stderr).toBe(0);
    expect(branchFiles()).not.toContain(FRAG);
    expect(branchFiles()).toContain('changes/own.md');
  });

  // C6：版本碎片规则按仓库（repos.json version_fragment）。zenithjoy 没有 changes/，auto-version 按提交标题 bump，规则为 null
  it('repo_profile 的 version_fragment 为 null（zenithjoy）→ 即使改了 packages/brain/src 也不写 changes/', async () => {
    commitSrc();
    const zj = JSON.parse(fs.readFileSync(path.join(HERE, '../repos.json'), 'utf8')).repos.find((x) => x.key === 'zenithjoy-workspace');
    const r = await run('new', { ...BUILD_CHAIN, repo_profile: zj });
    expect(r.exitCode, r.stderr).toBe(0);
    expect(branchFiles().some((f) => f.startsWith('changes/'))).toBe(false);
    expect(fs.existsSync(path.join(worktree, 'changes'))).toBe(false);
  });

  it('repo_profile 带别的碎片规则（src_re / dir）→ 按它写', async () => {
    fs.mkdirSync(path.join(worktree, 'apps/api/src'), { recursive: true });
    fs.writeFileSync(path.join(worktree, 'apps/api/src/y.ts'), 'export const y = 1;\n');
    git(worktree, 'add', '--', 'apps');
    git(worktree, 'commit', '-m', 'fix(api): y');
    fs.writeFileSync(path.join(worktree, 'sprints/s1/03-build.md'), '# build\n');
    const profile = { key: 'x', version_fragment: { src_re: '^apps/api/src/', dir: 'frags' } };
    const r = await run('new', { ...BUILD_CHAIN, repo_profile: profile });
    expect(r.exitCode, r.stderr).toBe(0);
    expect(branchFiles()).toContain('frags/cp-1007000000-test.md');
    expect(branchFiles()).not.toContain(FRAG);
  });

  it('没改 packages/brain/src → 不写碎片', async () => {
    const r = await run('new');
    expect(r.exitCode, r.stderr).toBe(0);
    expect(branchFiles()).not.toContain(FRAG);
  });
});

// spec_review 活动 v2（合同对抗）：QA 立场评审 ⇄ 开发逐条采纳/驳回并改规格，代码判分，不限轮数按走势收敛。
import { describe, it, expect, beforeAll, beforeEach, afterEach } from 'vitest';
import crypto from 'node:crypto';
import fs from 'node:fs';
import http from 'node:http';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { runActivityProcess } from './helpers/run-activity.mjs';
import { gitPlain } from './helpers/git.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ENTRY = path.join(HERE, '../activities/spec-review.mjs');
const FAKE = path.join(HERE, 'fixtures/fake-claude-gan.mjs');
const TASK_ID = '11111111-2222-3333-4444-555555555555';

const INTENT_MD = `---\ntask_id: ${TASK_ID}\nstep: intent\nupstream: []\n---\n# 验收条目\n\n### I-1\n能评审。\n\n### I-2\n能改写。\n`;
const SPEC_MD = `---\ntask_id: ${TASK_ID}\nstep: spec\nupstream: ["01-intent.md#I-1", "01-intent.md#I-2"]\n---\n# spec\n\n### S-1\n对应 I-1：改 foo.js\n\n### S-2\n对应 I-2：改 bar.js\n\n## QA 场景\n\n### Q-1\n对应: I-1\n操作: 用户发起评审\n期望: 看到评审结论\n\n### Q-2\n对应: I-2\n操作: 用户发起改写\n期望: 看到新规格\n\n## 未覆盖真实链路\n\n无：只改本仓库内代码，没有外部调用方与第三方\n`;
const sha256 = (text) => crypto.createHash('sha256').update(text).digest('hex');
const blocker = (id, extra = {}) => ({ id, severity: '阻断', ...extra });

describe('spec_review 活动 v2（合同对抗）', () => {
  let worktree;
  let tmp;
  const sprint = () => path.join(worktree, 'sprints/s1');
  const read = (name) => fs.readFileSync(path.join(sprint(), name), 'utf8');

  beforeAll(() => fs.chmodSync(FAKE, 0o755));
  beforeEach(() => {
    worktree = fs.mkdtempSync(path.join(os.tmpdir(), 'spec-review-v2-'));
    tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'spec-review-v2-state-'));
    gitPlain('init', '-q', worktree);
    fs.mkdirSync(sprint(), { recursive: true });
    fs.writeFileSync(path.join(sprint(), '01-intent.md'), INTENT_MD);
    fs.writeFileSync(path.join(sprint(), '02-spec.md'), SPEC_MD);
  });
  afterEach(() => {
    fs.rmSync(worktree, { recursive: true, force: true });
    fs.rmSync(tmp, { recursive: true, force: true });
  });

  const run = (script, env = {}, extraInput = {}) => {
    fs.writeFileSync(path.join(tmp, 'script.json'), JSON.stringify(script));
    return runActivityProcess(ENTRY, {
      run_tag: 'rt-1', task_id: TASK_ID, worktree, sprint_dir: 'sprints/s1',
      intent_ids: ['I-1', 'I-2'], intent_sha256: sha256(INTENT_MD), ...extraInput,
    }, {
      CODING_WF_CLAUDE_BIN: FAKE,
      FAKE_GAN_SCRIPT: path.join(tmp, 'script.json'),
      FAKE_GAN_STATE: path.join(tmp, 'state.json'),
      FAKE_GAN_SEEN: path.join(tmp, 'seen.log'),
      ...env,
    });
  };
  const seen = () => fs.readFileSync(path.join(tmp, 'seen.log'), 'utf8');

  it('Codex 多轮 GAN 不把未知美元费用累加成0，输出明确未知', async () => {
    const r = await run({ reviews: [{ scores: 6, issues: [blocker('R-1')] }, { scores: 8, prior: [{ id: 'R-1', status: '关闭' }] }] }, { FAKE_GAN_NATIVE: 'codex' });
    expect(r.result.status, r.stderr).toBe('completed');
    expect(r.result.outputs.gan.cost_usd).toBeNull();
    expect(r.result.metrics.cost_usd).toBeNull();
    expect(r.result.evidence.join(' ')).toContain('花费 未知');
  });

  it('首轮评分全部 ≥7、无阻断/重要问题 → completed：02-review-r1.md 与 02-review.md 相同，outputs 带 gan 摘要', async () => {
    const r = await run({ reviews: [{ scores: 8, issues: [{ id: 'R-1', severity: '建议', scene: '', basis: '' }], cost: 0.3 }] });
    expect(r.result.status).toBe('completed');
    expect(read('02-review.md')).toBe(read('02-review-r1.md'));
    expect(r.result.outputs).toMatchObject({
      review_file: '02-review.md', review_rounds: 1, spec_sha256: sha256(SPEC_MD),
      gan: { verdict: 'APPROVED', rounds: 1, trend: 'insufficient_data', open_issues: [], cost_usd: 0.3 },
    });
  });

  it('QA 问题可以针对 QA 场景 Q-n（evaluator 的测试计划）', async () => {
    const r = await run({ reviews: [{ scores: 6, issues: [blocker('R-1', { targets: 'Q-1' })] }, { scores: 8, prior: [{ id: 'R-1', status: '关闭' }] }] });
    expect(r.result.status).toBe('completed');
    expect(r.result.outputs.review_rounds).toBe(2);
  });

  it('开发采纳后关闭 → 第 2 轮通过；留下 02-response-r1.md，规格已改且 spec_sha256 为新哈希', async () => {
    const r = await run({ reviews: [
      { scores: 6, issues: [blocker('R-1')] },
      { scores: 8, prior: [{ id: 'R-1', status: '关闭' }] },
    ] });
    expect(r.result.status).toBe('completed');
    expect(r.result.outputs.review_rounds).toBe(2);
    expect(read('02-response-r1.md')).toContain('处理: 采纳');
    const spec = read('02-spec.md');
    expect(spec).not.toBe(SPEC_MD);
    expect(r.result.outputs.spec_sha256).toBe(sha256(spec));
  });

  // 审计 P1 #3：有铁律清单时，开发方改写后的合同照样要过铁律对照自检；评审 prompt 拿到清单路径
  it('有铁律清单：改写时删掉了 `## 铁律对照` → retryable spec_invalid（invariants_section_missing）', async () => {
    fs.writeFileSync(path.join(sprint(), '01-invariants.md'), '# 铁律清单\n\n### INV-02d8e749\n不得缩减已拍板设计\n');
    fs.appendFileSync(path.join(sprint(), '02-spec.md'), '\n## 铁律对照\n\n- INV-02d8e749：不适用：本改动只动评审文案\n');
    const r = await run({ reviews: [{ scores: 6, issues: [blocker('R-1')] }], revise: { dropInvariants: true } });
    expect(r.result.reason_code).toBe('spec_invalid');
    expect(JSON.stringify(r.result.evidence)).toContain('invariants_section_missing');
    const prompt = fs.readFileSync(path.join(path.dirname(ENTRY), '../prompts/spec-review.md'), 'utf8');
    expect(prompt).toContain('INVARIANTS_PATH: {{INVARIANTS_PATH}}');
    expect(prompt).toContain('违反铁律');
  });

  it('QA 坚持的问题仍算开着：评分再高也不通过，下一轮把仍开着的编号告诉 QA', async () => {
    const r = await run({ reviews: [
      { scores: 6, issues: [blocker('R-1')] },
      { scores: 9, prior: [{ id: 'R-1', status: '坚持', reason: '驳回不成立' }] },
      { scores: 9, prior: [{ id: 'R-1', status: '关闭' }] },
    ], revise: { response: '驳回' } });
    expect(r.result.status).toBe('completed');
    expect(r.result.outputs.review_rounds).toBe(3);
    expect(seen()).toContain('spec_review PRIOR_OPEN=R-1');
  });

  it('不设轮数上限：分数稳步上升、每轮都有新阻断问题，跑到第 6 轮才通过', async () => {
    const reviews = [3, 4, 5, 6, 6].map((sc, i) => ({ scores: sc, prior: i ? [{ id: `R-${i}`, status: '关闭' }] : [], issues: [blocker(`R-${i + 1}`)] }));
    // 第 4、5 轮同分（6→6）= 打转，第 6 轮评审必须写换思路（审计 #27）
    reviews.push({ scores: 8, prior: [{ id: 'R-5', status: '关闭' }], pivot: true });
    const r = await run({ reviews });
    expect(r.result.status).toBe('completed');
    expect(r.result.outputs.gan).toMatchObject({ verdict: 'APPROVED', rounds: 6 });
  });

  it('评分震荡 → 第 3 轮后强制通过（FORCED）+ P1 + 升级给 coding commander', async () => {
    const sc = (v) => ({ 意图对齐: v, 可验证: 6, 场景覆盖: 6, 回归风险: 6, 可执行: 6 });
    const r = await run({ reviews: [
      { scores: sc(8), issues: [blocker('R-1')] },
      { scores: sc(5), prior: [{ id: 'R-1', status: '坚持' }], issues: [blocker('R-2')] },
      // 第 2 轮总分下降 → 第 3 轮评审处于打转，要写换思路（审计 #27）
      { scores: sc(8), prior: [{ id: 'R-1', status: '坚持' }, { id: 'R-2', status: '坚持' }], pivot: true },
    ] });
    expect(r.result.status).toBe('completed');
    expect(r.result.outputs.gan).toMatchObject({ verdict: 'FORCED', rounds: 3, trend: 'oscillating' });
    expect(r.result.outputs.gan.open_issues.map((i) => i.id)).toEqual(['R-1', 'R-2']);
    expect(r.result.outputs.escalations).toEqual([expect.objectContaining({ type: 'gan_forced', trend: 'oscillating' })]);
    expect(r.stderr).toContain('[coding-gan][P1]');
  });

  it('规格越改越长（评分不动）→ diverging 强制通过', async () => {
    const r = await run({ reviews: [{ scores: 6, issues: [blocker('R-1')] }, { scores: 6, prior: [{ id: 'R-1', status: '坚持' }], pivot: true }], revise: { grow: 30 } });
    expect(r.result.outputs.gan).toMatchObject({ verdict: 'FORCED', trend: 'diverging' });
  });

  it('评审格式坏一次 → 重评不计轮；连续 3 次坏 → fatal review_invalid', async () => {
    let r = await run({ reviews: [{ raw: '只有散文' }, { scores: 8 }] });
    expect(r.result.status).toBe('completed');
    expect(r.result.outputs.review_rounds).toBe(1);
    fs.rmSync(path.join(tmp, 'state.json'), { force: true });
    r = await run({ reviews: [{ raw: '只有散文' }] });
    expect(r.result.failure_class).toBe('fatal');
    expect(r.result.reason_code).toBe('review_invalid');
  });

  // 审计 #33：重评时告诉评审上次格式哪里坏了
  it('评审格式坏了 → 重评的 prompt 带 PREV_REVIEW_ERRORS；首评写「无」', async () => {
    const r = await run({ reviews: [{ raw: '只有散文' }, { scores: 8 }] });
    expect(r.result.status).toBe('completed');
    const lines = seen().trim().split('\n').filter((l) => l.startsWith('spec_review'));
    expect(lines[0]).toContain('PREV_REVIEW_ERRORS=无');
    expect(lines[1]).toMatch(/PREV_REVIEW_ERRORS=.*scores_missing|PREV_REVIEW_ERRORS=.*score/);
  });

  // 审计 #33：活动被重试时（上次改写把规格改坏了），评审与改写都拿到当前 02 的程序校验问题
  it('当前 02 程序校验不过 → 评审与改写 prompt 的 SPEC_ERRORS 列出问题；合格时写「无」', async () => {
    let r = await run({ reviews: [{ scores: 8 }] });
    expect(seen()).toContain('SPEC_ERRORS=无');
    fs.rmSync(path.join(tmp, 'seen.log'));
    fs.rmSync(path.join(tmp, 'state.json'));
    fs.writeFileSync(path.join(sprint(), '02-spec.md'), SPEC_MD.replace(/\n## QA 场景[\s\S]*$/, '\n'));
    r = await run({ reviews: [{ scores: 6, issues: [blocker('R-1')] }] });
    expect(seen()).toMatch(/spec_review .*SPEC_ERRORS=.*qa_missing/);
    expect(seen()).toMatch(/spec_revise .*SPEC_ERRORS=.*qa_missing/);
  });

  // 审计 #27：总分连续两轮不涨 = 原地打转，要求评审写 `## 换思路`，改写方必须回应
  it('总分不涨 → 下一轮 STUCK=是，评审必须写 `## 换思路`（没写算格式不合格）', async () => {
    let r = await run({ reviews: [
      { scores: 6, issues: [blocker('R-1')] },
      { scores: 6, prior: [{ id: 'R-1', status: '坚持' }] },
      { scores: 8, prior: [{ id: 'R-1', status: '关闭' }], pivot: true },
    ] });
    expect(r.result.status, r.stderr).toBe('completed');
    const lines = seen().trim().split('\n');
    expect(lines.filter((l) => l.startsWith('spec_review')).map((l) => /STUCK=(\S+)/.exec(l)[1])).toEqual(['否', '否', '是']);
    expect(lines.filter((l) => l.startsWith('spec_revise')).at(-1)).toContain('STUCK=是');
    fs.rmSync(path.join(tmp, 'state.json'));
    fs.writeFileSync(path.join(sprint(), '02-spec.md'), SPEC_MD);
    r = await run({ reviews: [
      { scores: 6, issues: [blocker('R-1')] },
      { scores: 6, prior: [{ id: 'R-1', status: '坚持' }] },
      { scores: 8, prior: [{ id: 'R-1', status: '关闭' }] },
    ] });
    expect(r.result).toMatchObject({ failure_class: 'fatal', reason_code: 'review_invalid' });
    expect(JSON.stringify(r.result.evidence)).toContain('pivot_missing');
    for (const name of ['spec-review', 'spec-revise']) {
      const p = fs.readFileSync(path.join(path.dirname(ENTRY), `../prompts/${name}.md`), 'utf8');
      expect(p).toContain('STUCK: {{STUCK}}');
      expect(p).toContain('## 换思路');
    }
  });

  // 审计 #14（旧 reviewer 9.4/9.6）：合同对抗结束时判定点写进 Brain decisions（category=judgment）并回读计数；重跑不重复写
  describe('判定点写库', () => {
    let server;
    let decisions;
    let brainUrl;
    beforeEach(async () => {
      decisions = [];
      server = http.createServer((req, res) => {
        let raw = '';
        req.on('data', (c) => { raw += c; });
        req.on('end', () => {
          res.setHeader('content-type', 'application/json');
          if (req.method === 'POST' && req.url === '/api/brain/strategic-decisions') {
            const body = JSON.parse(raw);
            // 同生产约束 decisions_made_by_check（迁移 193）：made_by 只允许 user/cecelia/system，否则 500（金丝雀 4 暴露 ai 写不进）
            if (body.made_by && !['user', 'cecelia', 'system'].includes(body.made_by)) {
              res.statusCode = 500;
              return res.end(JSON.stringify({ success: false, error: 'violates check constraint "decisions_made_by_check"' }));
            }
            const row = { id: `d-${decisions.length + 1}`, ...body };
            decisions.push(row);
            res.statusCode = 201;
            return res.end(JSON.stringify({ success: true, data: row }));
          }
          if (req.method === 'GET' && req.url.startsWith('/api/brain/strategic-decisions?')) {
            return res.end(JSON.stringify({ success: true, data: decisions.filter((d) => d.category === 'judgment') }));
          }
          res.statusCode = 404;
          return res.end('{}');
        });
      });
      await new Promise((r) => server.listen(0, '127.0.0.1', r));
      brainUrl = `http://127.0.0.1:${server.address().port}`;
      fs.appendFileSync(path.join(sprint(), '02-spec.md'), '\n## 判定点\n\n- 部署成功判定｜候选: 看 HTTP 200、看 git_sha｜所选: 看 git_sha｜依据: 200 只说明活着｜误判后果: 旧版本被当新版本验收\n');
    });
    afterEach(() => new Promise((r) => server.close(r)));

    it('APPROVED → 判定点 POST 到 Brain（category judgment），回读计数写进 outputs.gan.judgments_written；重跑不重复写', async () => {
      let r = await run({ reviews: [{ scores: 8 }] }, {}, { brain_url: brainUrl });
      expect(r.result.status, r.stderr).toBe('completed');
      expect(decisions).toEqual([expect.objectContaining({
        category: 'judgment', topic: '判定点[11111111#1]: 部署成功判定',
        decision: '所选方法: 看 git_sha｜候选: 看 HTTP 200、看 git_sha', reason: '依据: 200 只说明活着｜误判后果: 旧版本被当新版本验收｜来源: coding workflow 合同对抗',
      })]);
      expect(r.result.outputs.gan.judgments_written).toBe(1);
      fs.rmSync(path.join(tmp, 'state.json'));
