/** git 查询本身失败：不能当成"没问题"，交给重试。 */
const gitCheckFailed = (check) => fail('retryable', 'git_check_failed', { evidence: [{ check }] });

/** 运行后检查：远端、历史/分支、md 链。有问题返回 fail，否则 null。 */
