  if (ancestor === null) return gitCheckFailed('merge-base --is-ancestor');
  if (branchAfter !== before.branch || !ancestor) {
    const evidence = { head_before: before.head, head_after: headAfter, branch_before: before.branch, branch_after: branchAfter };
    return fail('fatal', 'build_history_rewritten', { evidence: [evidence] });
  }
  const tampered = chainTamperFailure(dir, input);
  if (tampered) return tampered;
  const committed = await changedFilesSince(worktree, before.head, sprintDir);
  if (committed === null) return gitCheckFailed('diff --name-only');
  if (committed.length > 0) return fail('fatal', 'chain_tampered', { evidence: [{ committed_sprint_files: committed }] });
  return null;
}

/** 会话结束后的工作区检查：无未提交改动、sprint 目录只动 03、不碰 agent 配置。有问题返回 fail，否则 null。 */
async function postFailure({ worktree, sprintDir, before }) {
  const uncommitted = await outOfScopeChanges(worktree, sprintDir, before.changes, 'build');
  if (uncommitted.length > 0) return fail('fatal', 'build_uncommitted', { evidence: [{ uncommitted_changes: uncommitted }] });
  // sprint 目录只允许新增/修改 03（CLAUDE.md、.claude/ 等放进 sprint 目录同样会影响后续会话）
  const polluted = await sprintChangesExcept(worktree, sprintDir, before.changes, BUILD_FILE, 'build');
  if (polluted.length > 0) return fail('fatal', 'build_sprint_polluted', { evidence: [{ files: polluted }] });
  const changed = await changedFilesSince(worktree, before.head);
  if (changed === null) return gitCheckFailed('diff --name-only');
  if (changed.includes('.implementation-source-relations.json')) return fail('fatal', 'build_touched_controlled_metadata', { evidence: [{ files: ['.implementation-source-relations.json'] }] });
  const agentFiles = agentConfigFiles(changed);
  if (agentFiles.length > 0) return fail('fatal', 'build_touched_agent_config', { evidence: [{ files: agentFiles }] });
  return null;
}

const failedNames = (results) => results.filter((r) => !r.ok).map((r) => r.name);

/**
 * CI 门禁本地预检（审计 P1 #4）：跑门禁 → 有红则起修复会话（至多 PRECHECK_FIX_ROUNDS 轮，每轮修完重新过全部后置检查）→ 重跑。
 * 修复会话越界（改合同/历史/agent 配置等）→ { failure }；修不好或会话失败 → 不卡链路，summary 标明未过的门禁交给 CI 与 CI 修复环。
 */
async function precheckLoop({ worktree, dir, sprintDir, input, before }) {
  const feature = prKindOf(intentHeading(dir)) === 'feat';
  // 预检清单按仓库（repos.json prechecks，C6）
  const checks = process.env.CODING_WF_PRECHECKS ? JSON.parse(process.env.CODING_WF_PRECHECKS) : checksFor(input.repo_profile, { branch: before.branch, feature });
  const env = { PR_LABELS: feature ? 'feature' : '' };
  let results = await runPrechecks(worktree, { checks, env });
  let rounds = 0;
  while (failedNames(results).length > 0 && rounds < PRECHECK_FIX_ROUNDS) {
    rounds += 1;
    const failures = results.filter((r) => !r.ok).map((r) => `### ${r.name}\n\`\`\`\n${r.output_tail}\n\`\`\``).join('\n\n');
    const prompt = loadPrompt('ci-precheck-fix', {
      BRANCH: before.branch, SPRINT_DIR: dir, INTENT_PATH: path.join(dir, '01-intent.md'), SPEC_PATH: path.join(dir, SPEC_FILE), FAILURES: failures,
      REPO_RULES: repoRules(input.repo_profile),
    });
    const timeoutMs = posInt(process.env.CODING_WF_PRECHECK_FIX_TIMEOUT_MS, PRECHECK_FIX_TIMEOUT_MS);
    const run = await runClaude({ args: ['-p', prompt, '--permission-mode', 'acceptEdits', ...CLAUDE_TOOLS], cwd: worktree, timeoutMs, tag: 'ci-precheck-fix', isolateRemote: true });
    spend.usd = sumCostUsd(spend.usd, run.cost_usd);
    const violation = (await guardFailure({ worktree, dir, sprintDir, input, before })) ?? (await postFailure({ worktree, sprintDir, before }));
    if (violation) return { failure: violation };
    if (claudeFailure(run)) break;
    results = await runPrechecks(worktree, { checks, env });
  }
  const failures = failedNames(results);
  return { summary: { passed: failures.length === 0, rounds, failures } };
}

async function main(input) {
  const { worktree, sprint_dir: sprintDir } = input;
  const { dir } = validateBase(input);

  const specPath = path.join(dir, SPEC_FILE);
  const ids = specIds(specPath);
  if (ids === null) return fail('fatal', 'spec_missing');
  if (ids.length === 0) return fail('fatal', 'spec_ids_missing');
  const headBefore = await headSha(worktree);
  if (!headBefore) return fail('fatal', 'git_head_unavailable');

  const buildPath = path.join(dir, BUILD_FILE);
  const prompt = loadPrompt('build', {
    TASK_ID: input.task_id,
    INTENT_PATH: path.join(dir, INTENT_FILE),
    SPEC_PATH: specPath,
    BUILD_PATH: buildPath,
    SPEC_IDS: ids.join(','),
    SPRINT_DIR: dir,
    REPO_RULES: repoRules(input.repo_profile),
  });

  // 旧产物会被当成新产物，先删
  fs.rmSync(buildPath, { force: true });
  const before = {
    head: headBefore,
    branch: await currentBranch(worktree),
    remote: await remoteSnapshot(worktree),
    changes: await snapshotChanges(worktree),
  };
  // 运行前就查不到远端，事后无从比对：不启动 claude
  if (before.remote === null) return fail('retryable', 'remote_check_failed', { evidence: [{ remote_before: null }] });

  const args = ['-p', prompt, '--permission-mode', 'acceptEdits', ...CLAUDE_TOOLS];
  const timeoutMs = claudeTimeoutMs(input.budget, TIMEOUT);
  const run = await runClaude({ args, cwd: worktree, timeoutMs, tag: 'build', isolateRemote: true });
  spend.usd = sumCostUsd(spend.usd, run.cost_usd);
  const failure = claudeFailure(run) ?? (await guardFailure({ worktree, dir, sprintDir, input, before }));
  if (failure) return failure;

  if (!fs.existsSync(buildPath)) return fail('fatal', 'build_report_missing');
  const errors = reportErrors(fs.readFileSync(buildPath, 'utf8'), { taskId: input.task_id, step: 'build', coversFile: SPEC_FILE, ids });
  if (errors.length > 0) return fail('fatal', 'build_report_invalid', { evidence: [{ errors }] });
  const headAfterBuild = await headSha(worktree);
  if (headAfterBuild === headBefore) return fail('fatal', 'build_no_commit');
  const post = await postFailure({ worktree, sprintDir, before });
  if (post) return post;

  const precheck = await precheckLoop({ worktree, dir, sprintDir, input, before });
  if (precheck.failure) return precheck.failure;
  const commits = (await gitOut(worktree, ['rev-list', '--reverse', `${headBefore}..HEAD`]) ?? '').split('\n').filter(Boolean);

  return {
    status: 'completed',
    outputs: { build_file: BUILD_FILE, build_commits: commits, ci_precheck: precheck.summary },
    evidence: [`${BUILD_FILE} 已生成，${commits.length} 个提交；CI 门禁预检${precheck.summary.passed ? '通过' : `未过：${precheck.summary.failures.join('、')}`}`],
  };
}

// 会话花费进 metrics（审计 #35）：本活动所有 claude 会话累加，成功失败都计
await runActivity(async (input) => {
  const result = await main(input);
  return { ...result, metrics: { ...(result?.metrics ?? {}), cost_usd: spend.usd } };
}, { stage: 'build', entry: import.meta.url });

// evaluate 活动（evaluator 真人 QA）：CI 绿后、合并前的门（决策 02d8e749）。
// 在 PR 预览环境（lib/preview.mjs）里，全新 claude 会话只拿 01 需求与 02 的 QA 场景，像真人 QA 一样黑盒验收：
// （QA 模式按仓库，C6：local 仓库如 zenithjoy 第一阶段不起预览，在 PR worktree 里黑盒验 CLI / 脚本 / node 进程，提示词 evaluate-local）
// 按 Q-n 逐条操作 + 探索式测试，写 <sprint_dir>/05-qa-report-r<round>.md。运行期间 03/04（开发自述与自测）藏起，结束放回。
// 程序判：报告格式与 Q-n 覆盖 → 证据须在执行记录里 → 禁单元测试当证据 → 禁碰生产 Brain → PASS/FAIL。
// 产品不合格（qa.verdict FAIL）是正常结果：completed + outputs.qa，交给 runner 的修复环；报告/会话本身不合格才是活动失败。
import fs from 'node:fs';
import path from 'node:path';
import { runActivity, validateBase, fail, log } from '../lib/protocol.mjs';
import { provenanceRequired, beginEvaluateIsolation } from '../lib/record-provenance.mjs';
import { sourceFacts } from '../runner/lib/source-provenance.mjs';
import { intentIdsError } from '../lib/intent.mjs';
import { qaScenarios, SPEC_FILE, INTENT_FILE } from '../lib/spec-check.mjs';
import { parseQaReport, judgeQa, unitTestEvidence, productionTouches, trivialAssertions, screenshotProblems } from '../lib/qa-report.mjs';
import { bashExecutions, unverifiedItems, sessionCostUsd } from '../lib/transcript.mjs';
import { waitPreview, DEFAULT_PREVIEW_API } from '../lib/preview.mjs';
import { createPreviewBridge } from '../lib/preview-bridge.mjs';
import {
  loadPrompt, claudeTimeoutMs, runClaude, claudeFailure, headSha, snapshotChanges, outOfScopeChanges,
} from '../lib/claude.mjs';
import { chainTamperFailure, hideFile, recoverHidden } from '../lib/guards.mjs';
import { qaMode, productionPatterns } from '../lib/repo-profile.mjs';

const HIDDEN_FILES = ['03-build.md', '04-evidence.md'];
const TIMEOUT = { envVar: 'CODING_WF_EVALUATE_TIMEOUT_MS', defaultMs: 2400000, reserveMs: 60000 };
const SESSION_FLAGS = ['--output-format', 'stream-json', '--verbose', '--setting-sources', 'user'];
// 允许 Bash 真实操作；不许提交、改历史、切分支、推送、开 PR
const DENIED = [
  'Bash(git push:*)', 'Bash(git commit:*)', 'Bash(git reset:*)', 'Bash(git checkout:*)', 'Bash(git rebase:*)', 'Bash(gh:*)',
];

const posInt = (v, d) => (Number.isInteger(Number(v)) && Number(v) > 0 ? Number(v) : d);

/** 上一轮独立裁判判 QA 没真验到时 runner 传来的裁决（相对 worktree）：必须是 sprint 目录里存在的文件。→ 绝对路径 / '无' / null（非法）。 */
function judgeFeedbackPath(worktree, dir, rel) {
  if (rel === undefined || rel === null || rel === '') return '无';
  const abs = path.resolve(worktree, String(rel));
  return path.dirname(abs) === path.resolve(dir) && fs.existsSync(abs) ? abs : null;
}
const brief = (items) => items.map(({ id, covers, severity, scene, command, output }) => ({
  id, covers, ...(severity ? { severity, scene } : {}), command, output_tail: String(output ?? '').slice(-1000),
}));

/** 会话结束后：HEAD 不许动、sprint 目录外不许写、01/02 不许改。 */
async function guardFailure({ worktree, dir, sprintDir, input, before }) {
  const headAfter = await headSha(worktree);
  if (before.head && headAfter !== before.head) return fail('fatal', 'evaluate_head_moved', { evidence: [{ head_before: before.head, head_after: headAfter }] });
  const tampered = chainTamperFailure(dir, input);
  if (tampered) return tampered;
  const stray = await outOfScopeChanges(worktree, sprintDir, before.changes, 'evaluate');
  if (stray.length > 0) return fail('fatal', 'evaluate_out_of_scope_write', { evidence: [{ out_of_scope_changes: stray }] });
  return null;
}

/** 报告判分；产品 PASS/FAIL 都返回 completed。 */
function judge({ reportPath, reportFile, qaIds, stdout, worktree, dir, shotsDir, round, env, cost, production, provider, model }) {
  const executions = bashExecutions(stdout);
  const prod = productionTouches(executions, production);
  if (prod.length > 0) return fail('fatal', 'evaluate_touched_production', { evidence: [{ commands: prod }] });
  if (!fs.existsSync(reportPath)) return fail('retryable', 'qa_report_missing');
  const reportText = fs.readFileSync(reportPath, 'utf8');
  const report = parseQaReport(reportText);
  const judged = judgeQa(report, qaIds);
  if (judged.reason) return fail('retryable', judged.reason, { evidence: [{ errors: judged.errors, missing: judged.missing }] });
  const items = [...report.tests, ...report.findings];
  const unit = unitTestEvidence(items);
  if (unit.length > 0) return fail('retryable', 'qa_unit_test_evidence', { evidence: [{ items: unit }] });
  const unverified = unverifiedItems(items, executions, { worktree: [worktree, fs.realpathSync(worktree)] });
  if (unverified.length > 0) return fail('retryable', 'qa_evidence_unverified', { evidence: [{ unverified }] });
  // 恒真断言（审计 #36）：判 PASS 的命令吞掉失败 / 只回显结论
  const trivial = trivialAssertions(items);
  if (trivial.length > 0) return fail('retryable', 'qa_trivial_assertion', { evidence: [{ items: trivial }] });
  // 截图（审计 #37）：引用的截图要真存在，用了浏览器的条目要真留下截图
  const shots = screenshotProblems({ reportText, items, executions, sprintDir: dir, shotsDir });
  if (shots.length > 0) return fail('retryable', 'qa_screenshot_missing', { evidence: [{ problems: shots }] });
  const qa = {
    verdict: judged.verdict, round, env, provider, model: model ?? null, failed: brief(judged.failed), blocking: brief(judged.blocking),
    cannot_verify: judged.cannot_verify.map(({ id, covers, reason }) => ({ id, covers, reason })), cost_usd: cost,
  };
  log(`[evaluate] 第 ${round} 轮真人 QA ${judged.verdict}：失败场景 ${qa.failed.map((i) => i.id).join(',') || '无'}，阻断发现 ${qa.blocking.map((i) => i.id).join(',') || '无'}，验不了 ${qa.cannot_verify.map((i) => i.id).join(',') || '无'}`);
  return { status: 'completed', outputs: { qa_report_file: reportFile, qa }, evidence: [`${reportFile}：${judged.verdict}`] };
}

await runActivity(async (input) => {
  const { worktree, sprint_dir: sprintDir, intent_ids: intentIds } = input;
  const { dir } = validateBase(input);
  const idsError = intentIdsError(intentIds);
  if (idsError) return fail('fatal', idsError);
  const tamperedBefore = chainTamperFailure(dir, input);
  if (tamperedBefore) return tamperedBefore;
  const specPath = path.join(dir, SPEC_FILE);
  const qaIds = fs.existsSync(specPath) ? qaScenarios(fs.readFileSync(specPath, 'utf8')).map((q) => q.id) : [];
  if (qaIds.length === 0) return fail('fatal', 'qa_missing');
  const judgeFeedback = judgeFeedbackPath(worktree, dir, input.judge_feedback);
  if (!judgeFeedback) return fail('fatal', 'judge_feedback_invalid', { evidence: [{ judge_feedback: input.judge_feedback }] });

  const local = qaMode(input.repo_profile) === 'local';
  const production = productionPatterns(input.repo_profile);
  let preview = null;
  if (!local) {
    preview = await waitPreview(input.pr_number, {
      api: process.env.CODING_WF_PREVIEW_API || DEFAULT_PREVIEW_API,
      timeoutMs: posInt(process.env.CODING_WF_PREVIEW_WAIT_MS, 20 * 60 * 1000),
      intervalMs: posInt(process.env.CODING_WF_PREVIEW_INTERVAL_MS, 15000),
      host: process.env.CODING_WF_PREVIEW_HOST || 'localhost',
      // 给了要验的 head：预览部署的必须正是它（审计 P0 #2）
      expectSha: input.head_sha || null,
    });
    if (preview.state === 'stale') return fail('retryable', 'preview_stale', { evidence: [{ pr: input.pr_number, expected: input.head_sha, preview_sha: preview.sha }] });
    if (preview.state !== 'active') return fail('retryable', 'preview_unavailable', { evidence: [{ pr: input.pr_number, preview }] });
  }

  const round = posInt(input.round, 1);
  // 独立从受保护事件和精确 Git 验证，不采信任务 JSON 传来的 PASS/投影。
  const sourceProvenance = provenanceRequired(worktree)
    ? sourceFacts(worktree, { taskId: input.task_id, sprintDir }, input.head_sha || await headSha(worktree)) : null;
  const reportFile = `05-qa-report-r${round}.md`;
  const reportPath = path.join(dir, reportFile);
  const hiddenPaths = HIDDEN_FILES.map((f) => path.join(dir, f));
  for (const p of hiddenPaths) if (await recoverHidden(worktree, p)) log(`[evaluate] 已放回上次残留的 ${path.basename(p)}`);
  fs.rmSync(reportPath, { force: true });

  const prompt = loadPrompt(local ? 'evaluate-local' : 'evaluate', {
    TASK_ID: input.task_id,
    INTENT_PATH: path.join(dir, INTENT_FILE),
    SPEC_PATH: specPath,
    REPORT_PATH: reportPath,
    SPRINT_DIR: dir,
    SHOTS_DIR: path.join(dir, `qa-r${round}`),
    QA_IDS: qaIds.join(','),
    ...(local ? { WORKTREE: worktree, PRODUCTION: production.join(' | ') } : { PREVIEW_URL: preview.url }),
    ROUND: String(round),
    TESTED_HEAD: input.head_sha || await headSha(worktree) || '未知',
    SOURCE_PROVENANCE: sourceProvenance ? JSON.stringify(sourceProvenance) : '本仓未接入来源凭证，不能据此宣称来源通过',
    JUDGE_FEEDBACK: judgeFeedback,
    // 重试必须带新信息（审计 #33）：上次评估被判不合格的原因（runner 记下传入）；单行，防止伪造机器可读行
    PREV_ERRORS: typeof input.prev_errors === 'string' && input.prev_errors.trim() ? input.prev_errors.replace(/\s+/g, ' ').trim().slice(0, 2000) : '无',
  });
  const args = ['-p', prompt, '--permission-mode', 'acceptEdits', ...SESSION_FLAGS, '--allowedTools', 'Bash', '--disallowedTools', ...DENIED];
  const before = { head: await headSha(worktree), changes: await snapshotChanges(worktree) };

  const state = { hidden: [], isolation: null, claudeRunning: false, bridge: null };
  const restoreAll = () => state.isolation ? state.isolation.restore() : state.hidden.map((h) => h.restore()).every(Boolean);
  const onSigterm = () => {
    void state.bridge?.close();
    if (state.isolation) state.isolation.abort();else restoreAll();
    if (!state.claudeRunning) process.exit(2);
  };
  process.on('SIGTERM', onSigterm);
  let result;
  try {
    if (!local && process.env.CODING_WF_PROVIDER === 'codex') {
      try {
        state.bridge = await createPreviewBridge({ origin: preview.url, headSha: input.head_sha, prNumber: input.pr_number, production });
        args[1] += '\n\n' + loadPrompt('evaluate-codex-transport', {});
      } catch (error) {
        return fail('retryable', 'preview_unavailable', { evidence: [{ bridge_error: error.message }] });
      }
    }
    state.isolation = beginEvaluateIsolation();
    if (sourceProvenance && !state.isolation) throw Error('record_provenance_isolation_missing');
    if (state.isolation) args[1] += '\n\nCONTROLLER_WORKSPACE_ISOLATION: ' + JSON.stringify(state.isolation.hiddenFacts())
      + '\n以上仅说明可信控制器在本轮会话前暂移03/04，尚未声明恢复；不豁免产品范围、其他文件或原生命令验收。不得自行读取或改写持有副本。';
    else for (const p of hiddenPaths) state.hidden.push(await hideFile(worktree, p));
    state.claudeRunning = true;
    const run = await runClaude({ args, cwd: worktree, timeoutMs: claudeTimeoutMs(input.budget, TIMEOUT), tag: 'evaluate', isolateRemote: true,
      ...(state.bridge ? { nativeOptions: { previewCapability: state.bridge.capability } } : {}),
    });
    state.claudeRunning = false;
    // 会话执行记录落盘留证（runner 传 transcript_path；判越界/证据不实时可复核）
    if (input.transcript_path) {
      try {
        fs.mkdirSync(path.dirname(input.transcript_path), { recursive: true });
        fs.writeFileSync(input.transcript_path, run.stdout ?? '');
      } catch (error) {
        log(`[evaluate] 执行记录落盘失败：${error?.message || error}`);
      }
    }
    // A model report cannot override controller-observed head drift, even if it claims PASS.
    if (state.bridge) {
      try { await state.bridge.verify(); } catch (error) {
        result = fail('retryable', error.message === 'preview_sha_mismatch' ? 'preview_stale' : 'preview_unavailable',
          { evidence: [{ bridge_error: error.message, expected: input.head_sha }] });
      }
    }
    result ??= claudeFailure(run, { streamJson: true }) ?? (await guardFailure({ worktree, dir, sprintDir, input, before }));
    result ??= judge({
      reportPath, reportFile, qaIds, stdout: run.stdout, worktree, dir, shotsDir: path.join(dir, `qa-r${round}`), round,
      env: local ? { kind: 'local', worktree } : { kind: 'preview', url: preview.url, ...(preview.sha ? { sha: preview.sha } : {}),
        ...(state.bridge ? { transport: 'unix_http_browser' } : {}) },
      cost: run.cost_usd === undefined ? sessionCostUsd(run.stdout) : run.cost_usd, production,
      provider: run.provider, model: run.model,
    });
  } finally {
    await state.bridge?.close();
    process.off('SIGTERM', onSigterm);
    if (!restoreAll()) result = fail('fatal', 'hidden_restore_failed', { evidence: [{ hidden: state.hidden.map((h) => h.hiddenPath) }] });
  }
  return result;
}, { stage: 'evaluate', entry: import.meta.url });

// intent 活动：GET Brain 任务 → 提取验收条目 → 写 <sprint_dir>/01-intent.md；
// 另拉全部 active 铁律写 01-invariants.md，供合同逐条对照（审计 P1 #3）。
import fs from 'node:fs';
import path from 'node:path';
import { runActivity, validateBase, fail, log } from '../lib/protocol.mjs';
import { extractAcceptance, renderIntent } from '../lib/intent.mjs';
import { sha256File } from '../lib/guards.mjs';
import { renderInvariants, INVARIANTS_FILE } from '../lib/invariants.mjs';

const INTENT_FILE = '01-intent.md';
const INVARIANT_LIMIT = 1000;
const DEFAULT_BRAIN_URL = 'http://localhost:5221';
const FETCH_TIMEOUT_MS = 30000;

await runActivity(async (input) => {
  // 先校验输入，再做任何网络请求或写文件
  const { dir } = validateBase(input);
  const taskId = input.task_id;

  const base = String(input.brain_url || DEFAULT_BRAIN_URL).replace(/\/+$/, '');
  const url = `${base}/api/brain/tasks/${encodeURIComponent(taskId)}`;

  let task;
  try {
    const res = await fetch(url, { signal: AbortSignal.timeout(FETCH_TIMEOUT_MS) });
    if (res.status === 404 || res.status === 400) return fail('fatal', 'task_not_found');
    if (res.status >= 500 || res.status === 429 || res.status === 408) return fail('retryable', 'brain_unavailable');
    if (!res.ok) return fail('fatal', `brain_http_${res.status}`);
    task = await res.json();
  } catch (error) {
    log(`[intent] GET ${url} 失败: ${error?.message || error}`);
    return fail('retryable', 'brain_unavailable');
  }

  const items = extractAcceptance(task);
  if (items.length === 0) return fail('needs_human', 'acceptance_missing');

  // 全部 active 铁律（审计 P1 #3）：拉不到不能当作没有铁律
  let invariants;
  try {
    const res = await fetch(`${base}/api/brain/decisions?category=invariant&status=active&limit=${INVARIANT_LIMIT}`, { signal: AbortSignal.timeout(FETCH_TIMEOUT_MS) });
    if (!res.ok) return fail('retryable', 'invariants_unavailable', { evidence: [{ http_status: res.status }] });
    const body = await res.json();
    invariants = (Array.isArray(body) ? body : body?.data ?? []).filter((r) => r?.id && (r.status ?? 'active') === 'active');
  } catch (error) {
    log(`[intent] 拉铁律清单失败: ${error?.message || error}`);
    return fail('retryable', 'invariants_unavailable');
  }

  fs.mkdirSync(dir, { recursive: true });
  const intentPath = path.join(dir, INTENT_FILE);
  fs.writeFileSync(intentPath, renderIntent({ taskId, title: task?.title, items, description: task?.description }));
  fs.writeFileSync(path.join(dir, INVARIANTS_FILE), renderInvariants(invariants));

  return {
    status: 'completed',
    // 验收标准的指纹：后续活动比对，发现被改即 chain_tampered
    outputs: { intent_file: INTENT_FILE, intent_ids: items.map((_, i) => `I-${i + 1}`), intent_sha256: sha256File(intentPath) },
    metrics: { intent_count: items.length },
    evidence: [`${INTENT_FILE}: ${items.length} 条验收`],
  };
}, { stage: 'intent', entry: import.meta.url });

// publish 活动：把 sprint 目录的 md 链提交、推送，并开草稿 PR（该分支已有 PR 则复用）。
import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { runActivity, validateBase, fail, childEnv, log } from '../lib/protocol.mjs';
import { intentHeading, prKindOf } from '../lib/pr-kind.mjs';
import { parseReview } from '../lib/review.mjs';
import { RUBRIC_DIMS } from '../lib/gan.mjs';
import { SPEC_FILE, uncoveredSection } from '../lib/spec-check.mjs';
import { registerRecordSources } from '../lib/record-sources.mjs';
import { provenanceRequired, controllerIdentity, beginRecordRegistration, observeRecordRegistration, finalizeRecordRegistration } from '../lib/record-provenance.mjs';
import { profileOf } from '../lib/repo-profile.mjs';

const GH_AUTH_RE = /\bHTTP 401\b|authentication|auth login|missing required scope|bad credentials/i;
// 凭据提示会让无 tty 的子进程挂住；--literal-pathspecs 禁用 :/ 等 pathspec 魔法
const CHILD_ENV = { ...childEnv(), GIT_TERMINAL_PROMPT: '0' };
const GIT_PATHSPEC = ['--literal-pathspecs'];
// 与本机全局 pre-commit 钩子（~/.git-hooks/pre-commit）的分支名正则保持一致，否则 commit 会被钩子拒绝
const BRANCH_RE = /^cp-[0-9]{8,10}-[a-z0-9][a-z0-9_-]*$/;
const STDERR_TAIL_LINES = 20;
const BUILD_FILE = '03-build.md';
const BASE_REF = process.env.CODING_WF_BASE_REF || 'origin/main';

/** 运行子进程（不经 shell），输出转写到本进程 stderr；返回 { code, stdout, stderr, output }。 */
function runCmd(bin, args, cwd) {
  return new Promise((resolve) => {
    let stdout = '';
    let stderr = '';
    let output = '';
    let child;
    try {
      child = spawn(bin, args, { cwd, env: CHILD_ENV, stdio: ['ignore', 'pipe', 'pipe'] });
    } catch (error) {
      const message = String(error?.message || error);
      resolve({ code: null, stdout: '', stderr: message, output: message });
      return;
    }
    child.stdout.setEncoding('utf8');
    child.stderr.setEncoding('utf8');
    child.stdout.on('data', (chunk) => {
      stdout += chunk;
      output += chunk;
      process.stderr.write(chunk);
    });
    child.stderr.on('data', (chunk) => {
      stderr += chunk;
      output += chunk;
      process.stderr.write(chunk);
    });
    child.on('error', (error) => {
      log(`[publish] 启动 ${bin} 失败: ${error?.message || error}`);
      resolve({ code: null, stdout, stderr: `${stderr}\n${error?.message || error}`, output: `${output}\n${error?.message || error}` });
    });
    child.on('close', (code) => resolve({ code, stdout, stderr, output }));
  });
}

const lastLine = (text) => text.trim().split('\n').filter(Boolean).pop() || '';

/**
 * PR/提交标题：链里有 03-build.md（带代码提交）时用 feat(workflow): <01-intent 标题>，
 * 标题以 bug/修复/fix 开头则用 fix(workflow):；只有文档链时保持 docs(sprint): <id> md 链 …。
 */
function prTitle(chainFiles, dir, taskId) {
  if (!chainFiles.includes(BUILD_FILE)) {
    return `docs(sprint): ${taskId.slice(0, 8)} md 链 ${chainFiles.map((f) => String(f).replace(/\.md$/, '')).join(' → ')}`;
  }
  const heading = intentHeading(dir) || `coding workflow ${taskId.slice(0, 8)}`;
  return `${prKindOf(heading)}(workflow): ${heading}`;
}

const escapeRe = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/**
 * 版本碎片（cecelia changes/README.md：PR 不碰版本五件套，改 packages/brain/src 的 PR 带 changes/<分支>.md，
 * 合并后 auto-version 统一 bump）：改了碎片规则覆盖的源码且分支上还没有碎片 → 写一份；返回相对路径或 null。
 * 规则按仓库（repos.json version_fragment { src_re, dir }，C6）；为 null（zenithjoy：auto-version 按提交标题 bump）不写。
 */
async function ensureVersionFragment({ worktree, branch, dir, taskId, sprintRel, rule }) {
  if (!rule) return null;
  const srcRe = new RegExp(rule.src_re);
  const fragmentRe = new RegExp(`^${escapeRe(rule.dir)}/(?!README\\.md$).+\\.md$`, 'i');
  const diff = await runCmd('git', ['-C', worktree, 'diff', '--name-only', `${BASE_REF}...HEAD`]);
  if (diff.code !== 0) {
    log(`[publish] 取相对 ${BASE_REF} 的改动失败，不写版本碎片`);
    return null;
  }
  const files = diff.stdout.split('\n').filter(Boolean);
  if (!files.some((f) => srcRe.test(f)) || files.some((f) => fragmentRe.test(f))) return null;
  const rel = `${rule.dir}/${branch}.md`;
  const heading = intentHeading(dir) || `coding workflow ${taskId.slice(0, 8)}`;
  fs.mkdirSync(path.join(worktree, rule.dir), { recursive: true });
  fs.writeFileSync(path.join(worktree, rel), `## Brain {VERSION} — ${heading}\n\n- coding workflow 任务 ${taskId.slice(0, 8)}：需求、合同与验收记录见 ${sprintRel}/。\n`);
  return rel;
}

/**
 * PR 正文的验收摘要：verify 通过后上下文里有 evidence_file 与 verified_ids（全部 PASS 才会走到 publish），
 * 逐条列出 I-n 的 verdict；没有则返回空串（只有 01/02 的旧链）。
 */
function acceptanceSummary({ evidence_file: evidenceFile, verified_ids: ids }, sprintRel) {
  if (typeof evidenceFile !== 'string' || !Array.isArray(ids) || ids.length === 0) return '';
  const lines = ids.filter((id) => typeof id === 'string').map((id) => `- ${id}：PASS`);
  return [`## 验收摘要（${sprintRel}/${evidenceFile}）`, ...lines].join('\n');
}

/**
 * PR 正文的合同对抗小节：上下文有 review_file 时写轮数、结论与走势（gan 摘要）、最终评分、末轮每条问题（严重度 + 首行）；
 * 强制通过时醒目标出仍开着的问题。没有 review_file 或文件读不到返回空串（不出现小节，也不让 publish 失败）。
 */
function reviewSummary({ review_file: reviewFile, review_rounds: rounds, gan }, dir, sprintRel) {
  if (typeof reviewFile !== 'string' || reviewFile === '') return '';
  let text;
  try {
    text = fs.readFileSync(path.join(dir, reviewFile), 'utf8');
  } catch {
    return '';
  }
  const { scores, issues } = parseReview(text);
  const g = gan && typeof gan === 'object' ? gan : {};
  const scoreText = RUBRIC_DIMS.filter((d) => d in scores).map((d) => `${d} ${scores[d]}`).join(' / ');
  const lines = [
    `## 合同对抗（${sprintRel}/${reviewFile}）`,
    `- 轮数：${Number.isInteger(rounds) && rounds > 0 ? rounds : '未知'}`,
    `- 结论：${g.verdict ?? '未知'}（走势 ${g.trend ?? '未知'}，花费 $${g.cost_usd ?? '未知'}）`,
  ];
  if (scoreText) lines.push(`- 最终评分：${scoreText}`);
  if (g.verdict === 'FORCED') {
    const open = (g.open_issues ?? []).map((i) => `${i.id}［${i.severity}］`).join('、') || '无';
    lines.push(`- ⚠️ 强制通过（走势 ${g.trend}），仍开着：${open}`);
  }
  for (const { id, severity, targets, body } of issues) {
    lines.push(`- ${id}［${severity || '未标'}］（针对 ${targets.join('、')}）：${body.split('\n')[0]}`);
  }
  return lines.join('\n');
}

/** 审计 #10：02 的「未覆盖真实链路」原样转呈 PR 正文；读不到或没有这一段返回空串。 */
function uncoveredSummary(dir, sprintRel) {
  let text;
  try {
    text = fs.readFileSync(path.join(dir, SPEC_FILE), 'utf8');
  } catch {
    return '';
  }
  const body = uncoveredSection(text);
  return body ? `## 未覆盖真实链路（${sprintRel}/${SPEC_FILE}）\n${body}` : '';
}

await runActivity(async (input) => {
  const { worktree, sprint_dir: sprintDir, chain_files: chainFiles } = input;
  const { dir } = validateBase(input);
  const taskId = input.task_id;
  const gpAnchor = input.gp_anchor;
  // 缺失沿用旧行为，交仓库 CI 判定；有值必须是一行，不能借锚点注入额外声明。
  // 格式及业务归属由目标仓库的 GP lint 校验，publish 不替任务造豁免。
  if (gpAnchor !== undefined && (typeof gpAnchor !== 'string' || !gpAnchor.trim()
      || /[\u0000-\u001f\u007f-\u009f\u2028\u2029]/u.test(gpAnchor))) {
    return fail('fatal', 'gp_anchor_invalid');
  }
  if (!Array.isArray(chainFiles) || chainFiles.length === 0) return fail('fatal', 'chain_files_missing');

  const branchRes = await runCmd('git', ['-C', worktree, 'rev-parse', '--abbrev-ref', 'HEAD']);
  const branch = branchRes.stdout.trim();
  if (branchRes.code !== 0 || !BRANCH_RE.test(branch)) return fail('fatal', 'branch_invalid');

  const title = prTitle(chainFiles, dir, taskId);
  const sprintRel = sprintDir.replace(/[\\/]+$/, '');

  const fragment = await ensureVersionFragment({ worktree, branch, dir, taskId, sprintRel, rule: profileOf(input.repo_profile).version_fragment ?? null });
  const records = fs.readdirSync(dir).map(name => `${sprintRel}/${name}`);
  const registration = provenanceRequired(worktree) ? beginRecordRegistration({ worktree, taskId,
    sprintDir: sprintRel, stage: 'publish', controller: controllerIdentity(import.meta.url) }, records) : null;
  const sourceFiles = registerRecordSources(worktree, { taskId, sprintDir: sprintRel, stage: 'publish' }, records);
  if (registration) observeRecordRegistration(registration, sourceFiles);
  const paths = [sprintRel, ...(fragment ? [fragment] : []), ...sourceFiles];
  const add = await runCmd('git', [...GIT_PATHSPEC, '-C', worktree, 'add', '--', ...paths]);
  if (add.code !== 0) return fail('fatal', 'git_add_failed');

  // diff --cached --quiet：有暂存改动退出 1，无改动退出 0
  const staged = await runCmd('git', [...GIT_PATHSPEC, '-C', worktree, 'diff', '--cached', '--quiet', '--', ...paths]);
  if (staged.code === 1) {
    const commit = await runCmd('git', [...GIT_PATHSPEC, '-C', worktree, 'commit', '-m', title, '--', ...paths]);
    if (commit.code !== 0) {
      const stderrTail = commit.stderr.trim().split('\n').slice(-STDERR_TAIL_LINES);
      return fail('fatal', 'git_commit_failed', { evidence: [{ stderr_tail: stderrTail }] });
    }
  } else if (staged.code !== 0) {
    return fail('fatal', 'git_diff_failed');
  }

  // commit 已发生而凭证未完成时必须停在这里；不能推送后补造来源历史。
  if (registration) finalizeRecordRegistration(registration);
  const push = await runCmd('git', ['-C', worktree, 'push', '-u', 'origin', branch]);
  if (push.code !== 0) return fail('retryable', 'push_failed');

  const gh = process.env.CODING_WF_GH_BIN || 'gh';
  const ghFail = (res) => (GH_AUTH_RE.test(res.output) ? fail('needs_human', 'gh_auth') : fail('retryable', 'gh_failed'));

  const list = await runCmd(gh, ['pr', 'list', '--head', branch, '--json', 'url', '-q', '.[0].url'], worktree);
  if (list.code !== 0) return ghFail(list);
  let prUrl = lastLine(list.stdout);

  if (!prUrl) {
    const body = [
      gpAnchor === undefined ? '' : `GP-Anchor: ${gpAnchor}`,
      chainFiles.map((f) => `- ${sprintRel}/${f}`).join('\n'),
      reviewSummary(input, dir, sprintRel),
      uncoveredSummary(dir, sprintRel),
      acceptanceSummary(input, sprintRel),
    ]
      .filter(Boolean)
      .join('\n\n');
    const create = await runCmd(
      gh,
      ['pr', 'create', '--draft', '--head', branch, '--title', title, '--body', body],
      worktree,
    );
    if (create.code !== 0) return ghFail(create);
    prUrl = lastLine(create.stdout);
    if (!prUrl) return fail('retryable', 'gh_failed');
  }

  return {
    status: 'completed',
    outputs: { pr_url: prUrl, branch },
    evidence: [`PR ${prUrl}（分支 ${branch}）`],
  };
}, { stage: 'publish', entry: import.meta.url });

// spec_review 活动（合同对抗 v2）：QA 立场评审 ⇄ 开发逐条采纳/驳回并改规格，循环到代码判通过。
// 主理人决策（02d8e749，记忆 harness-gan-design）：不设轮数上限；靠走势收敛——发散/震荡强制通过 + P1 + 升级给 coding commander；
// 只有「真坏掉」才中止：评审连续 3 次格式不合格、累计花费超上限、claude 失败、越界写、01 被改。
// 每轮产物：02-review-rN.md（QA）、02-response-rN.md（开发对每个问题的采纳/驳回）；结束时最终一轮另存为 02-review.md 供链校验与 PR。
import fs from 'node:fs';
import path from 'node:path';
import { runActivity, validateBase, fail, log } from '../lib/protocol.mjs';
import { intentIdsError } from '../lib/intent.mjs';
import {
  loadPrompt, claudeTimeoutMs, runClaude, claudeFailure, snapshotChanges, outOfScopeChanges,
} from '../lib/claude.mjs';
import { sha256File, chainTamperFailure } from '../lib/guards.mjs';
