import { sealStageEvidence } from '../lib/record-provenance.mjs';

const REVIEW_FILE = '02-review.md';
const TIMEOUT = { envVar: 'CODING_WF_SPEC_REVIEW_TIMEOUT_MS', defaultMs: 900000 };
const BUDGET_RESERVE_MS = 15000;
const MAX_BAD_REVIEW_STREAK = 3; // 不是轮数上限：拿到合格评审就清零
const DEFAULT_BUDGET_USD = 20;
const PROMPTS = { spec_review: 'spec-review', spec_revise: 'spec-revise' };
const ARGS = ['--permission-mode', 'acceptEdits', '--disallowedTools', 'Bash', '--output-format', 'stream-json', '--verbose'];

const reviewName = (n) => `02-review-r${n}.md`;
const responseName = (n) => `02-response-r${n}.md`;
const money = (x) => x === null ? null : Math.round(x * 10000) / 10000;
const brief = (issues) => issues.map(({ id, severity, targets }) => ({ id, severity, targets }));

function budgetUsd() {
  const v = Number(process.env.CODING_WF_GAN_BUDGET_USD);
  return Number.isFinite(v) && v > 0 ? v : DEFAULT_BUDGET_USD;
}

/** 本会话超时：默认/覆盖值，再与 budget 剩余时间取小（下限 1000ms）。 */
function sessionTimeoutMs(budget, startedAt) {
  const ms = claudeTimeoutMs(budget, TIMEOUT);
  const budgetS = budget?.max_duration_s;
  if (!Number.isFinite(budgetS) || budgetS <= 0) return ms;
  return Math.min(ms, Math.max(1000, budgetS * 1000 - BUDGET_RESERVE_MS - (Date.now() - startedAt)));
}

const DEFAULT_BRAIN_URL = 'http://localhost:5221';
const BRAIN_TIMEOUT_MS = 15000;

async function brainJson(url, init = {}) {
  const res = await fetch(url, { ...init, signal: AbortSignal.timeout(BRAIN_TIMEOUT_MS) });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

/**
 * 判定点写库并回读自证（审计 #14，旧 reviewer 9.4/9.6：a85e0582 登记表被静默漏写）：
 * topic `判定点[<task 前 8 位>#n]: <名称>` 作去重键（重跑不重复写）；写完回读同前缀条数作为 judgments_written。
 */
async function writeJudgments(brainUrl, taskId, points) {
  const base = String(brainUrl || DEFAULT_BRAIN_URL).replace(/\/+$/, '');
  const prefix = `判定点[${String(taskId).slice(0, 8)}#`;
  const list = async () => {
    const r = await brainJson(`${base}/api/brain/strategic-decisions?category=judgment&limit=1000`);
    return new Set((r?.data ?? []).map((d) => d.topic).filter((t) => typeof t === 'string' && t.startsWith(prefix)));
  };
  const existing = await list();
  for (const [i, j] of points.entries()) {
    const topic = `${prefix}${i + 1}]: ${j.name}`;
    if (existing.has(topic)) continue;
    await brainJson(`${base}/api/brain/strategic-decisions`, {
      method: 'POST', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        category: 'judgment', topic, decision: `所选方法: ${j.chosen}｜候选: ${j.candidates}`,
        reason: `依据: ${j.basis}｜误判后果: ${j.consequence}｜来源: coding workflow 合同对抗`,
        made_by: 'system', author: 'coding-workflow', source_ref: `coding-workflow:${taskId}`,
      }),
    });
  }
  return (await list()).size;
}

/** 起一个全新会话（评审或改写）；返回 { failure } 或 { cost }。会话后查：claude 失败 → 越界写 → 01 哈希。 */
async function runSession(ctx, role, vars) {
  const { input, worktree, sprintDir, dir } = ctx;
  const before = await snapshotChanges(worktree);
  const prompt = loadPrompt(PROMPTS[role], vars);
  const run = await runClaude({ args: ['-p', prompt, ...ARGS], cwd: worktree, timeoutMs: sessionTimeoutMs(input.budget, ctx.startedAt), tag: role, isolateRemote: true });
  const failure = claudeFailure(run, { streamJson: true });
  if (failure) return { failure };
  const stray = await outOfScopeChanges(worktree, sprintDir, before, role);
  if (stray.length > 0) return { failure: fail('fatal', 'spec_review_out_of_scope_write', { evidence: [{ out_of_scope_changes: stray }] }) };
  const tampered = chainTamperFailure(dir, { intent_sha256: input.intent_sha256 });
  if (tampered) return { failure: tampered };
  return { cost: run.cost_usd === undefined ? sessionCostUsd(run.stdout) : run.cost_usd };
}

/** 读并解析本轮评审；格式问题返回 { errors }，否则 { review }。 */
function readReview(file, { taskId, ids, intentIds, prevOpen, usedIds, requirePivot, untracked = [] }) {
  if (!fs.existsSync(file)) return { errors: ['review_missing'] };
  const text = fs.readFileSync(file, 'utf8');
  // 问题可针对 S-n / I-n / QA 场景 Q-n（evaluator 的测试计划）
  const qaIds = qaScenarios(fs.readFileSync(path.join(path.dirname(file), SPEC_FILE), 'utf8')).map((q) => q.id);
  const review = parseReview(text, { specIds: [...ids, ...qaIds], intentIds, priorIds: prevOpen.map((i) => i.id), usedIds });
  const errors = [...reportErrors(text, { taskId, step: 'spec_review', coversFile: SPEC_FILE, ids }), ...review.errors];
  // 原地打转时评审必须给出换思路（审计 #27）
  if (requirePivot && !/^## 换思路\s*$/m.test(text)) errors.push('pivot_missing');
  // 「后续再做」却没登记任务的驳回（审计 #16）：QA 不能关掉
  for (const p of review.prior) if (p.status === '关闭' && untracked.includes(p.id)) errors.push(`deferral_closed_without_task:${p.id}`);
  return errors.length > 0 ? { errors } : { review };
}

await runActivity(async (input) => {
  const { worktree, sprint_dir: sprintDir, intent_ids: intentIds, task_id: taskId } = input;
  const { dir } = validateBase(input);
  const idsError = intentIdsError(intentIds);
  if (idsError) return fail('fatal', idsError);
  const tamperedBefore = chainTamperFailure(dir, { intent_sha256: input.intent_sha256 });
  if (tamperedBefore) return tamperedBefore;
  const specPath = path.join(dir, SPEC_FILE);
  if (!fs.existsSync(specPath)) return fail('fatal', 'spec_missing');

  const ctx = { input, worktree, sprintDir, dir, startedAt: Date.now() };
  const base = {
    TASK_ID: taskId, INTENT_PATH: path.join(dir, INTENT_FILE), SPEC_PATH: specPath, INTENT_IDS: intentIds.join(','), INVARIANTS_PATH: path.join(dir, INVARIANTS_FILE),
  };
  const invariantIds = loadInvariantIds(dir);
  const budget = budgetUsd();
  const history = [];
  let prevOpen = [];
  const usedIds = [];
  let cost = 0;
  let badStreak = 0;
  let reviewErrors = [];
  let untracked = [];
  // 重试必须带新信息（审计 #33）：每个会话都拿到当前 02 的程序校验问题（活动被重试时，上次改写可能把规格改坏了）
  const specErrorsNow = () => explainSpecErrors(specErrors(fs.readFileSync(specPath, 'utf8'), taskId, intentIds, { invariantIds }));

  const overBudget = () => cost > budget
    && fail('fatal', 'gan_budget_exceeded', { evidence: [{ cost_usd: money(cost), budget_usd: budget, rounds: history.length, open_issues: brief(prevOpen) }] });

  const finish = async (verdict, round, trend, open) => {
    fs.copyFileSync(path.join(dir, reviewName(round)), path.join(dir, REVIEW_FILE));
    const gan = { verdict, rounds: round, trend, open_issues: brief(open), cost_usd: money(cost), scores: history.at(-1).scores };
    const outputs = { review_file: REVIEW_FILE, review_rounds: round, spec_sha256: sha256File(specPath), gan };
    const escalations = [];
    if (verdict === 'FORCED') {
      log(`[coding-gan][P1] 合同对抗走势 ${trend}，第 ${round} 轮强制通过，仍开着 ${open.map((i) => i.id).join(',') || '无'}，升级给 coding commander`);
      escalations.push({ type: 'gan_forced', trend, round, open_issues: brief(open) });
    }
    // 判定点写库（审计 #14）：写不进去不挡合同，但升级、不静默
    const points = judgmentPoints(fs.readFileSync(specPath, 'utf8'));
    gan.judgments_written = 0;
    if (points.length > 0) {
      try {
        gan.judgments_written = await writeJudgments(input.brain_url, taskId, points);
      } catch (error) {
        log(`[coding-gan][P1] 判定点 ${points.length} 条写入 Brain 失败：${error?.message || error}，升级给 coding commander`);
        escalations.push({ type: 'judgments_write_failed', count: points.length, error: String(error?.message || error) });
      }
    }
    if (escalations.length > 0) outputs.escalations = escalations;
    return { status: 'completed', outputs, metrics: { cost_usd: money(cost) }, evidence: [`合同对抗 ${verdict}：${round} 轮，走势 ${trend}，花费 ${costText(money(cost))}`] };
  };

  for (;;) {
    const round = history.length + 1;
    const reviewPath = path.join(dir, reviewName(round));
    fs.rmSync(reviewPath, { force: true });
    const ids = specIds(fs.readFileSync(specPath, 'utf8'));
    const stuck = stalled(history);
    const reviewed = await runSession(ctx, 'spec_review', {
      ...base,
      REVIEW_PATH: reviewPath,
      SPEC_IDS: ids.join(','),
      ROUND: String(round),
      PRIOR_OPEN: prevOpen.map((i) => i.id).join(',') || '无',
      PREV_REVIEW_PATH: round > 1 ? path.join(dir, reviewName(round - 1)) : '无',
      PREV_RESPONSE_PATH: round > 1 ? path.join(dir, responseName(round - 1)) : '无',
      USED_IDS: usedIds.join(',') || '无',
      SPEC_ERRORS: specErrorsNow(),
      PREV_REVIEW_ERRORS: reviewErrors.join(' ') || '无',
      STUCK: stuck ? '是' : '否',
      UNTRACKED_DEFERRALS: untracked.join(',') || '无',
    });
    if (reviewed.failure) return reviewed.failure;
    cost = sumCostUsd(cost, reviewed.cost);
    const blown = overBudget();
    if (blown) return blown;

    const { review, errors } = readReview(reviewPath, { taskId, ids, intentIds, prevOpen, usedIds, requirePivot: stuck, untracked });
    if (errors) {
      badStreak += 1;
      reviewErrors = errors;
      log(`[spec_review] 第 ${round} 轮评审格式不合格（连续 ${badStreak} 次）：${errors.join(' ')}`);
      if (badStreak >= MAX_BAD_REVIEW_STREAK) return fail('fatal', 'review_invalid', { evidence: [{ review_errors: errors }] });
      continue;
    }
    badStreak = 0;
    reviewErrors = [];
    sealStageEvidence({ files: [`${sprintDir}/${reviewName(round)}`], round,
      result: { status: 'completed' }, producer: 'model' });
    usedIds.push(...review.issues.map((i) => i.id));
    const open = openIssuesAfter(prevOpen, review);
    history.push({ scores: review.scores, specLines: fs.readFileSync(specPath, 'utf8').split('\n').length });

    const decision = decide({ scores: review.scores, openIssues: open });
    if (decision.approved) return finish('APPROVED', round, detectTrend(history), open);
    const trend = detectTrend(history);
    if (trend === 'diverging' || trend === 'oscillating') return finish('FORCED', round, trend, open);
    log(`[spec_review] 第 ${round} 轮未通过：${decision.reasons.join(' ')}；走势 ${trend}，继续对抗`);

    const responsePath = path.join(dir, responseName(round));
    fs.rmSync(responsePath, { force: true });
    const revised = await runSession(ctx, 'spec_revise', {
      ...base, REVIEW_PATH: reviewPath, RESPONSE_PATH: responsePath, OPEN_ISSUES: open.map((i) => i.id).join(',') || '无',
      SPEC_ERRORS: specErrorsNow(), STUCK: stalled(history) ? '是' : '否',
    });
    if (revised.failure) return revised.failure;
    cost = sumCostUsd(cost, revised.cost);
    prevOpen = open;
    const blownAfterRevise = overBudget();
    if (blownAfterRevise) return blownAfterRevise;
    if (!fs.existsSync(specPath)) return fail('fatal', 'spec_missing');
    const specErr = specErrors(fs.readFileSync(specPath, 'utf8'), taskId, intentIds, { invariantIds });
    if (specErr.length > 0) return fail('retryable', 'spec_invalid', { evidence: [{ spec_errors: specErr }] });
    if (!fs.existsSync(responsePath)) return fail('retryable', 'response_missing', { evidence: [{ round }] });
    sealStageEvidence({ files: [`${sprintDir}/${responseName(round)}`, `${sprintDir}/${SPEC_FILE}`], round,
      result: { status: 'completed' }, producer: 'model' });
    untracked = untrackedDeferrals(fs.readFileSync(responsePath, 'utf8')).filter((id) => open.some((i) => i.id === id));
  }
}, { stage: 'spec_review', entry: import.meta.url });

// spec 活动：用 claude CLI + 薄 prompt 根据 01-intent.md 生成 <sprint_dir>/02-spec.md。
// 生成后自检 02（frontmatter、upstream 覆盖全部 I-n、至少一条 S-n）；跨文件整链校验仍由 chain_check 做。
import fs from 'node:fs';
import path from 'node:path';
import { runActivity, validateBase, fail } from '../lib/protocol.mjs';
import { intentIdsError } from '../lib/intent.mjs';
import {
  loadPrompt, claudeTimeoutMs, runClaude, claudeFailure, snapshotChanges, outOfScopeChanges,
} from '../lib/claude.mjs';
import { sha256File, chainTamperFailure } from '../lib/guards.mjs';
import { SPEC_FILE, INTENT_FILE, specErrors, explainSpecErrors } from '../lib/spec-check.mjs';
import { INVARIANTS_FILE, loadInvariantIds } from '../lib/invariants.mjs';
import { qaMode, repoRules } from '../lib/repo-profile.mjs';

// 默认低于契约 budget（900s），这样超时由本活动先报明确的 claude_timeout，而不是执行器笼统的 activity_timeout
const TIMEOUT = { envVar: 'CODING_WF_SPEC_TIMEOUT_MS', defaultMs: 870000 };
// QA 模式 local 的仓库（zenithjoy 第一阶段）验不了 UI / 真机：spec 判不支持就写这一行，本活动上交（C6）
const QA_UNSUPPORTED_RE = /^QA_UNSUPPORTED:\s*(.+)$/m;

await runActivity(async (input) => {
  const { worktree, sprint_dir: sprintDir, intent_ids: intentIds } = input;

  const { dir } = validateBase(input);
  const idsError = intentIdsError(intentIds);
  if (idsError) return fail('fatal', idsError);

  const specPath = path.join(dir, SPEC_FILE);
  const invariantIds = loadInvariantIds(dir);
  // 重试必须带新信息（审计 #33）：上次写出的 02 还在 = 上次没通过，把它的校验问题交给这次
  const prevErrors = fs.existsSync(specPath)
    ? specErrors(fs.readFileSync(specPath, 'utf8'), input.task_id, intentIds, { invariantIds })
    : [];
  const prompt = loadPrompt('spec', {
    TASK_ID: input.task_id,
    INTENT_PATH: path.join(dir, INTENT_FILE),
    SPEC_PATH: specPath,
    INTENT_IDS: intentIds.join(','),
    INVARIANTS_PATH: path.join(dir, INVARIANTS_FILE),
    PREV_ERRORS: explainSpecErrors(prevErrors),
    REPO_RULES: repoRules(input.repo_profile),
  });

  // 重试/重跑时旧产物会被当成新产物，先删
  fs.rmSync(specPath, { force: true });
  const before = await snapshotChanges(worktree);

  const args = ['-p', prompt, '--permission-mode', 'acceptEdits', '--disallowedTools', 'Bash'];
  const run = await runClaude({ args, cwd: worktree, timeoutMs: claudeTimeoutMs(input.budget, TIMEOUT), tag: 'spec' });
  // 会话花费进 metrics（审计 #35），失败也计——重试同样花钱
  const priced = (r) => ({ ...r, metrics: { ...(r.metrics ?? {}), cost_usd: run.cost_usd === undefined ? 0 : run.cost_usd } });
  // 超时/被取消/非 0 直接返回：产物可能写了一半，不检查、不做越界检查
  const failure = claudeFailure(run);
  if (failure) return priced(failure);

  const stray = await outOfScopeChanges(worktree, sprintDir, before, 'spec');
  if (stray.length > 0) {
    return priced(fail('fatal', 'spec_out_of_scope_write', { evidence: [{ out_of_scope_changes: stray }] }));
  }
  const tampered = chainTamperFailure(dir, { intent_sha256: input.intent_sha256 });
  if (tampered) return priced(tampered);
  if (!fs.existsSync(specPath)) return priced(fail('fatal', 'spec_missing'));

  // 本仓 QA 模式验不了这个任务（UI / 真机）：不进 build，上交主理人（不是规格不合格，不重试）
  const unsupported = qaMode(input.repo_profile) === 'local' ? QA_UNSUPPORTED_RE.exec(fs.readFileSync(specPath, 'utf8')) : null;
  if (unsupported) return priced(fail('needs_human', 'qa_mode_unsupported', { evidence: [{ qa_mode: 'local', reason: unsupported[1].trim() }] }));

  // 02 不合格当场拦（重试一次让 claude 重写），不留给 build 报 spec_ids_missing（c2afa8ba 实测）
  const errors = specErrors(fs.readFileSync(specPath, 'utf8'), input.task_id, intentIds, { invariantIds });
  if (errors.length > 0) return priced(fail('retryable', 'spec_invalid', { evidence: [{ spec_errors: errors }] }));

  return priced({
    status: 'completed',
    outputs: { spec_file: SPEC_FILE, spec_sha256: sha256File(specPath) },
    evidence: [`${SPEC_FILE} 已生成`],
  });
}, { stage: 'spec', entry: import.meta.url });

import { sumCostUsd } from '../lib/transcript.mjs';
// verify 活动：全新 claude 会话只拿 01-intent.md 与 worktree，对每条 I-n 真实运行命令取证，写 <sprint_dir>/04-evidence.md。
// 判分由程序做：04 的格式与覆盖（lib/evidence）、每条证据须在 stream-json 执行记录里有据（lib/transcript）、再看 verdict。
// 运行期间 03-build.md 暂移出 sprint 目录（不受干活方自述影响），结束后无论成败都放回。
import fs from 'node:fs';
import path from 'node:path';
import { runActivity, validateBase, fail, log } from '../lib/protocol.mjs';
import { intentIdsError } from '../lib/intent.mjs';
import { parseEvidence, judgeEvidence } from '../lib/evidence.mjs';
import { bashExecutions, unverifiedItems } from '../lib/transcript.mjs';
import {
  loadPrompt, claudeTimeoutMs, runClaude, claudeFailure, headSha, snapshotChanges, outOfScopeChanges,
} from '../lib/claude.mjs';
import { chainTamperFailure, remoteChangeFailure, remoteSnapshot, hideFile, recoverHidden } from '../lib/guards.mjs';

const spend = { usd: 0 };

const INTENT_FILE = '01-intent.md';
const BUILD_FILE = '03-build.md';
const EVIDENCE_FILE = '04-evidence.md';
// 默认 = budget 1200s - 90s：超时由本活动先报 claude_timeout，并给 claude 退出后的检查阶段（含最长 60s 的 ls-remote）留余量
const TIMEOUT = { envVar: 'CODING_WF_VERIFY_TIMEOUT_MS', defaultMs: 1110000, reserveMs: 75000 };
// stream-json 对话记录用于核对证据；只读用户级设置，build 提交进仓库的项目级 .claude 配置不影响本会话
const SESSION_FLAGS = ['--output-format', 'stream-json', '--verbose', '--setting-sources', 'user'];
// 允许 Bash 真跑命令取证；不许提交、改历史、切分支、推送、开 PR
const DENIED = [
  'Bash(git push:*)', 'Bash(git commit:*)', 'Bash(git reset:*)', 'Bash(git checkout:*)', 'Bash(git rebase:*)', 'Bash(gh:*)',
];

/** 验收不通过：outputs.verification 供 report 回写 Brain（执行器对 failed 结果同样合并 outputs 进上下文）。 */
function rejected(reason, evidence, { failed = [], ...extra } = {}) {
  return fail('fatal', reason, {
    outputs: { verification: { status: 'failed', reason_code: reason, failed, ...extra } },
    evidence: [evidence],
  });
}

/** 运行后检查：HEAD、远端、md 链、sprint 目录外改动。有问题返回 fail，否则 null。 */
async function guardFailure({ worktree, dir, sprintDir, input, before }) {
  const headAfter = await headSha(worktree);
  if (before.head && headAfter !== before.head) {
    return fail('fatal', 'verify_head_moved', { evidence: [{ head_before: before.head, head_after: headAfter }] });
  }
  const guard = (await remoteChangeFailure(worktree, before.remote)) ?? chainTamperFailure(dir, input);
  if (guard) return guard;
  const stray = await outOfScopeChanges(worktree, sprintDir, before.changes, 'verify');
  if (stray.length > 0) return fail('fatal', 'verify_out_of_scope_write', { evidence: [{ out_of_scope_changes: stray }] });
  return null;
}

/** 判分：格式/覆盖 → 执行记录核对 → verdict。 */
function judge(text, intentIds, transcript, worktree) {
  const parsed = parseEvidence(text);
  const judged = judgeEvidence(parsed, intentIds);
  if (judged.reason === 'evidence_invalid') return rejected(judged.reason, { errors: judged.errors }, { errors: judged.errors });
  if (judged.reason === 'evidence_incomplete') return rejected(judged.reason, { missing: judged.missing }, { missing: judged.missing });
  // worktree 的原路径与真实路径都算（macOS 上 /var 与 /private/var 指向同一处）
  const roots = [worktree, fs.realpathSync(worktree)];
  const unverified = unverifiedItems(parsed.items, bashExecutions(transcript), { worktree: roots });
  if (unverified.length > 0) return rejected('evidence_unverified', { unverified }, { unverified });
  if (judged.reason === 'verification_failed') {
    const failed = judged.failed.map(({ id, covers, command, output }) => ({ id, covers, command, output_tail: output }));
    return rejected(judged.reason, { failed: judged.failed, verdicts: judged.summary }, { failed });
  }
  return {
    status: 'completed',
    outputs: { evidence_file: EVIDENCE_FILE, verified_ids: judged.verifiedIds },
    evidence: [`${EVIDENCE_FILE}：${judged.verifiedIds.length} 条验收全部 PASS`],
  };
}

async function main(input) {
  const { worktree, sprint_dir: sprintDir, intent_ids: intentIds } = input;
  const { dir } = validateBase(input);
  const idsError = intentIdsError(intentIds);
  if (idsError) return fail('fatal', idsError);
  const tamperedBefore = chainTamperFailure(dir, input);
  if (tamperedBefore) return tamperedBefore;

  const evidencePath = path.join(dir, EVIDENCE_FILE);
  const buildPath = path.join(dir, BUILD_FILE);
  // 上次运行被硬杀时 03 可能还留在 git 目录下：先放回
  if (await recoverHidden(worktree, buildPath)) log('[verify] 已放回上次残留的 03-build.md');
  const prompt = loadPrompt('verify', {
    TASK_ID: input.task_id,
    INTENT_PATH: path.join(dir, INTENT_FILE),
    EVIDENCE_PATH: evidencePath,
    INTENT_IDS: intentIds.join(','),
    SPRINT_DIR: dir,
  });

  // 旧产物会被当成新产物，先删
  fs.rmSync(evidencePath, { force: true });
  const before = { head: await headSha(worktree), remote: await remoteSnapshot(worktree), changes: await snapshotChanges(worktree) };
  // 运行前就查不到远端，事后无从比对：不启动 claude
  if (before.remote === null) return fail('retryable', 'remote_check_failed', { evidence: [{ remote_before: null }] });
  const args = [
    '-p', prompt, '--permission-mode', 'acceptEdits', ...SESSION_FLAGS,
    // 权限规则里 `//` 开头才是绝对路径（单 `/` 相对项目根）
    '--allowedTools', 'Bash', '--disallowedTools', ...DENIED, `Read(/${buildPath})`,
  ];

  // 从隐藏 03 之前到放回之后都接管 SIGTERM：收到即放回。claude 运行中由 runClaude 收割进程组后正常返回；
  // claude 退出后的检查阶段（可能卡在 ls-remote）没有别的处理者，放回后直接退出
  const state = { hidden: null, claudeRunning: false };
  const onSigterm = () => {
    state.hidden?.restore();
    if (!state.claudeRunning) process.exit(2);
  };
  process.on('SIGTERM', onSigterm);
  let result;
  try {
    state.hidden = await hideFile(worktree, buildPath);
    const timeoutMs = claudeTimeoutMs(input.budget, TIMEOUT);
    state.claudeRunning = true;
    const run = await runClaude({ args, cwd: worktree, timeoutMs, tag: 'verify', isolateRemote: true });
    spend.usd = sumCostUsd(spend.usd, run.cost_usd);
    state.claudeRunning = false;
    result = claudeFailure(run, { streamJson: true }) ?? (await guardFailure({ worktree, dir, sprintDir, input, before }));
    if (!result && !fs.existsSync(evidencePath)) result = fail('fatal', 'evidence_missing');
    result ??= judge(fs.readFileSync(evidencePath, 'utf8'), intentIds, run.stdout, worktree);
  } finally {
    process.off('SIGTERM', onSigterm);
    if (state.hidden && !state.hidden.restore()) {
      result = fail('fatal', 'build_report_restore_failed', { evidence: [{ hidden_path: state.hidden.hiddenPath }] });
    }
  }
  return result;
}

// 会话花费进 metrics（审计 #35）：本活动所有 claude 会话累加，成功失败都计
await runActivity(async (input) => {
  const result = await main(input);
  return { ...result, metrics: { ...(result?.metrics ?? {}), cost_usd: spend.usd } };
}, { stage: 'verify', entry: import.meta.url });

