// 仅可信活动入口选择阶段；任务 JSON 不得选择证据根、controller 身份或跳过封存。
import fs from 'node:fs';
import path from 'node:path';
import { withRecordProvenance, controllerIdentity, provenanceRequired, sealStageEvidence } from './record-provenance.mjs';

const FIXED_REPORTS = {
  intent: ['01-intent.md', '01-invariants.md'],
  spec: ['02-spec.md'],
  build: ['03-build.md'],
  verify: ['04-evidence.md'],
  spec_review: ['02-review.md'],
};

function stageFiles(input, stage) {
  const { worktree, sprint_dir: sprint } = input;
  if (stage !== 'evaluate') return (FIXED_REPORTS[stage] ?? []).map(file => `${sprint}/${file}`);
  const files = [`${sprint}/05-qa-report-r${input.round}.md`];
  const shots = `${sprint}/qa-r${input.round}`;
  const walk = (rel) => {
    const full = path.join(worktree, rel);
    let stat;
    try { stat = fs.lstatSync(full); } catch (error) { if (error.code === 'ENOENT') return; throw error; }
    if (stat.isSymbolicLink()) throw new Error('provenance_path_symlink');
    if (stat.isFile()) files.push(rel);
    else if (stat.isDirectory()) for (const name of fs.readdirSync(full)) walk(`${rel}/${name}`);
    else throw new Error('provenance_file_invalid');
  };
  walk(shots);
  return files;
}

export async function runRecordedActivity(input, options, handler) {
  const { stage, entry, root } = options;
  if (!provenanceRequired(input.worktree)) return handler(input);
  // 与 evaluate 的既有默认口径一致，身份与文件名必须使用同一个实际轮次。
  if (stage === 'evaluate') input = { ...input,
    round: Number.isInteger(Number(input.round)) && Number(input.round) > 0 ? Number(input.round) : 1 };
  const controller = controllerIdentity(entry, [import.meta.url, new URL('./claude.mjs', import.meta.url)]);
  return withRecordProvenance({ worktree: input.worktree, taskId: input.task_id,
    sprintDir: input.sprint_dir, stage, round: input.round ?? 0, controller, ...(root ? { root } : {}) }, async () => {
    const result = await handler(input);
    if (result?.status === 'completed' && stage !== 'publish') {
      const sealed = sealStageEvidence({ files: stageFiles(input, stage), result,
        producer: stage === 'intent' ? 'controller' : 'model',
        ...(stage === 'intent' ? { controllerInput: { task_id: input.task_id, result } } : {}) });
      if (stage === 'evaluate') return { ...result, outputs: { ...result.outputs, source_stage_event_id: sealed.id } };
    }
    return result;
  });
}

// claude CLI 子进程公共逻辑：spec / build / verify 共用。
// 进程组收割、超时 SIGTERM→SIGKILL、执行器取消、退出宽限、env 剥离、鉴权判定、越界写快照都在这里。
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawn, execFile } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { fail, childEnv, log } from './protocol.mjs';
import { claudeOwnErrorText, sessionCostUsd } from './transcript.mjs';
import { prepareCodexSession } from './codex-session.mjs';
import { captureNativeExecution } from './record-provenance.mjs';

const PROMPTS_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), '../prompts');
// 只认 claude CLI 自身的鉴权/额度报错措辞；裸 login、/login 路由等业务输出不算
const AUTH_RE = /\bauthenticat|please run \/login|invalid api key|quota|rate limit|usage limit|not logged in|login required/i;
const KILL_GRACE_MS = 5000; // 超时 SIGTERM 之后到 SIGKILL 的宽限
const TIMEOUT_MARGIN_MS = 10000; // 钳制超时时给收尾留的余量
const EXIT_GRACE_MS = 1500; // claude 退出后等输出管道关闭的宽限，过了就整组 SIGKILL
const CANCEL_GRACE_MS = 2500; // 收到执行器 SIGTERM 后到整组 SIGKILL 的宽限（必须短于执行器 cleanup_grace_s 默认 5s）
const GROUP_KILL = process.platform !== 'win32';
const GIT_TIMEOUT_MS = 60000; // ls-remote 等网络操作卡住时按失败处理

const GH_TOKEN_KEYS = ['GH_TOKEN', 'GITHUB_TOKEN', 'GH_ENTERPRISE_TOKEN'];

/**
 * 子 claude / git 的环境：不继承 CLAUDECODE / CLAUDE_CODE_*（避免被当成嵌套会话）与钩子遗留的 GIT_*；凭据提示一律关掉。
 * 也不继承 runner 配置 CODING_WF_*：会话里跑的 runner 测试会被它污染（ea2feb66 实测）。
 */
function claudeEnv() {
  const env = { ...childEnv(process.env, { stripClaude: true }), GIT_TERMINAL_PROMPT: '0' };
  for (const key of Object.keys(env)) if (key.startsWith('CODING_WF_')) delete env[key];
  return env;
}

/**
 * 防误操作的远端闸：剥离 GH 令牌、GH_CONFIG_DIR 指向空目录（gh 读不到登录态）。
 * 不是安全边界：SSH agent 等其他凭据途径仍在，真正兜底的是活动前后的 ls-remote 比对。
 */
function remoteIsolatedEnv(ghConfigDir) {
  const env = claudeEnv();
  for (const key of GH_TOKEN_KEYS) delete env[key];
  // 编排凭据不属于开发/QA/裁判；Codex 必须使用选定账号的订阅登录。
  for (const key of ['DEPLOY_TOKEN', 'CECELIA_INTERNAL_TOKEN', 'TOAPIS_API_KEY', 'OPENAI_API_KEY', 'CODEX_API_KEY', 'CODEX_ACCESS_TOKEN', 'OPENAI_ACCESS_TOKEN', 'ANTHROPIC_API_KEY', 'CLAUDE_CODE_OAUTH_TOKEN', 'BARK_TOKEN', 'OP_SERVICE_ACCOUNT_TOKEN']) delete env[key];
  env.GH_CONFIG_DIR = ghConfigDir;
  return env;
}

// coding 链 claude 会话用 opus 别名（永远指向最新 Opus）：不显式指定时实测落到 sonnet
const DEFAULT_MODEL = 'opus';

/** 调用方没给 --model 时在末尾追加（CODING_WF_CLAUDE_MODEL 覆盖默认）。 */
function withModel(args) {
  if (args.includes('--model')) return args;
  return [...args, '--model', process.env.CODING_WF_CLAUDE_MODEL || DEFAULT_MODEL];
}

/** 把模板里的 `{{KEY}}` 换成 vars[KEY]（值按字面量插入，不解释 `$&` 等替换序列）。 */
export function renderPrompt(template, vars) {
  return Object.entries(vars).reduce((text, [key, value]) => text.replaceAll(`{{${key}}}`, () => value), template);
}

/** 读 prompts/<name>.md 并渲染。 */
export function loadPrompt(name, vars) {
  return renderPrompt(fs.readFileSync(path.join(PROMPTS_DIR, `${name}.md`), 'utf8'), vars);
}

/**
 * claude 的超时毫秒数：env[envVar] 为正整数时采用，否则回退 defaultMs；
 * 再钳到 budget.max_duration_s*1000 - KILL_GRACE_MS - TIMEOUT_MARGIN_MS - reserveMs 之内
 * （超过 budget 执行器会先杀活动，claude 就成了孤儿；reserveMs 留给 claude 退出后的检查阶段），最低 1000ms。
 * 无 budget 时只用默认/覆盖值。
 */
export function claudeTimeoutMs(budget, { envVar, defaultMs, reserveMs = 0, env = process.env }) {
  const raw = env[envVar];
  const wanted = /^[1-9][0-9]*$/.test(raw ?? '') && Number.isSafeInteger(Number(raw)) ? Number(raw) : defaultMs;
  const budgetS = budget?.max_duration_s;
  if (!Number.isFinite(budgetS) || budgetS <= 0) return wanted;
  const clamp = Math.max(1000, budgetS * 1000 - KILL_GRACE_MS - TIMEOUT_MARGIN_MS - reserveMs);
  return Math.min(wanted, clamp);
}

/**
 * runClaude 结果的失败映射：超时 → retryable claude_timeout；被取消 → retryable claude_failed（evidence 标 terminated）；
 * 非 0 且像鉴权/额度问题 → needs_human claude_auth；其余非 0 → retryable claude_failed。退出 0 返回 null。
 * streamJson（stdout 是 stream-json 对话记录，含工具输出）时只看 claude 自身的错误事件与 stderr，
 * 不扫描 tool_result 里的业务输出；否则扫描全部输出。
 */
export function claudeFailure({ code, output, stdout = '', stderr = '', timedOut, terminated, provider, configurationError }, { streamJson = false } = {}) {
  const detail = provider ? { evidence: [{ provider }] } : {};
  if (configurationError) return fail('needs_human', 'codex_configuration', { evidence: [{ provider, error: configurationError }] });
  if (timedOut) return fail('retryable', 'claude_timeout', detail);
  if (terminated) return fail('retryable', 'claude_failed', { evidence: [{ terminated: true, ...(provider ? { provider } : {}) }] });
  if (code === 0) return null;
  const authText = streamJson || provider === 'codex' ? `${claudeOwnErrorText(stdout)}\n${stderr}` : output;
  if (AUTH_RE.test(authText)) return fail('needs_human', provider === 'codex' ? 'codex_auth' : 'claude_auth', detail);
  return fail('retryable', 'claude_failed', detail);
}

/** 向 claude 所在进程组发信号（Windows 退化为只杀直接子进程）；进程已不存在（ESRCH）忽略。 */
function signalGroup(child, signal, tag) {
  try {
    if (GROUP_KILL) process.kill(-child.pid, signal);
    else child.kill(signal);
  } catch (error) {
    if (error.code !== 'ESRCH') log(`[${tag}] 向 claude 发送 ${signal} 失败: ${error?.message || error}`);
  }
}

/**
 * 运行 claude（CODING_WF_CLAUDE_BIN 覆盖可执行文件），输出全部转写到本进程 stderr——给了 transcriptPath 时改为边跑边追加进该文件、
 * 不进 stderr（runner 进程内的 ci-fix/qa-fix/commander 会话：stderr 就是 runner 主日志）；activity 不给，stderr 由执行器重定向进 <task>.log；
 * 返回 { code, output, stdout, stderr, timedOut, terminated }（output 为两者合并，stdout/stderr 各一份供解析与判定），
 * spawn 失败时 code 为 null。isolateRemote 时套 remoteIsolatedEnv，临时 GH_CONFIG_DIR 结束后删除。
 * - claude 自成进程组（detached，但仍等待它、不 unref），结束时整组收掉，不留孙进程。
 * - 超过 timeoutMs 先 SIGTERM，KILL_GRACE_MS 后仍未退出再 SIGKILL，timedOut: true。
 * - 本进程收到 SIGTERM（执行器取消/超时/心跳失败）：对 claude 组发 SIGTERM，CANCEL_GRACE_MS 后组 SIGKILL，terminated: true。
 * - 正常退出后若输出管道被后代占着，EXIT_GRACE_MS 后整组 SIGKILL 并销毁管道，不等 close。
 */
// 每个会话都要能计费（审计 #35）：没指定输出格式就用 json（末尾一个 result 事件带 total_cost_usd，与 stream-json 同形）
const withCostOutput = (args) => (args.includes('--output-format') ? args : [...args, '--output-format', 'json']);

/** 起 claude 会话；返回值另带 cost_usd（result 事件的 total_cost_usd，Claude 兼容缺失值 0；Codex 订阅美元未知为 null）。 */
export async function runClaude({ args: callerArgs, cwd, timeoutMs, tag, isolateRemote = false, transcriptPath, provider: selectedProvider, nativeOptions, codexEnv = {} }) {
  const provider = selectedProvider ?? process.env.CODING_WF_PROVIDER ?? 'claude';
  if (!['claude', 'codex'].includes(provider)) return { code: null, stdout: '', stderr: 'provider_unsupported', output: 'provider_unsupported', configurationError: 'provider_unsupported', provider, cost_usd: null };
  let native;
  try { if (provider === 'codex') native = prepareCodexSession({ args: callerArgs, cwd, env: { ...process.env, ...codexEnv }, nativeOptions }); }
  catch (error) { return { code: null, stdout: '', stderr: error.message, output: error.message, configurationError: error.message, provider, cost_usd: null }; }
  const args = native?.args ?? withModel(withCostOutput(callerArgs));
  const priced = (run) => {
    const result = { ...run, provider, model: provider === 'codex' ? codexEnv.CODING_WF_CODEX_MODEL || process.env.CODING_WF_CODEX_MODEL || null : process.env.CODING_WF_CLAUDE_MODEL || DEFAULT_MODEL, cost_usd: provider === 'codex' ? null : sessionCostUsd(run.stdout ?? ''), ...(transcriptPath ? { transcriptPath } : {}) };
    // 直接采集进程管道返回值；不回读模型可以改写的 transcriptPath/logDir。
    captureNativeExecution({ ...result, tag });
    return result;
  };
  if (!isolateRemote && provider === 'claude') return priced(await spawnClaude({ args, cwd, timeoutMs, tag, env: claudeEnv(), transcriptPath }));
  const ghConfigDir = fs.mkdtempSync(path.join(os.tmpdir(), 'coding-wf-gh-'));
  try {
    return priced(await spawnClaude({ args, bin: native?.bin, stdin: native?.stdin, cwd, timeoutMs, tag, env: { ...remoteIsolatedEnv(ghConfigDir), ...native?.env }, transcriptPath }));
  } finally {
    fs.rmSync(ghConfigDir, { recursive: true, force: true });
  }
}

/** 会话输出去向：给了 transcriptPath 就追加进该文件（目录自动建）；打不开退回 stderr 并记一行。 */
function openSink(transcriptPath, tag) {
  const toStderr = { write: (chunk) => process.stderr.write(chunk), close: () => {} };
  if (!transcriptPath) return toStderr;
  try {
    fs.mkdirSync(path.dirname(transcriptPath), { recursive: true });
    let fd = fs.openSync(transcriptPath, 'a');
    // 收尾后管道里迟到的数据直接丢（fd 已关，写会 EBADF）
    return {
      write: (chunk) => { if (fd !== null) fs.writeSync(fd, chunk); },
      close: () => { if (fd !== null) fs.closeSync(fd); fd = null; },
    };
  } catch (error) {
    log(`[${tag}] 会话文件 ${transcriptPath} 打不开（${error?.message || error}），会话输出改写 stderr`);
    return toStderr;
  }
}

function spawnClaude({ args, cwd, timeoutMs, tag, env, transcriptPath, stdin, bin = process.env.CODING_WF_CLAUDE_BIN || 'claude' }) {
  const sink = openSink(transcriptPath, tag);
  return new Promise((resolve) => {
    let output = '';
    let stdout = '';
    let stderr = '';
    let timedOut = false;
    let terminated = false;
    let finished = false;
    let killTimer;
    let graceTimer;
    let child;
    try {
      child = spawn(bin, args, { cwd, env, stdio: [stdin === undefined ? 'ignore' : 'pipe', 'pipe', 'pipe'], detached: GROUP_KILL });
      if (stdin !== undefined) {
        // 大规格/完整 diff 可超过系统 argv 上限。提前退出的子进程由 error/close 统一判失败。
        child.stdin.on('error', () => {});
        child.stdin.end(stdin);
      }
    } catch (error) {
      const message = String(error?.message || error);
      sink.write(`${message}\n`);
      sink.close();
      resolve({ code: null, output: message, stdout: '', stderr: message, timedOut: false, terminated: false });
      return;
    }
    const forward = (chunk) => {
      output += chunk;
      sink.write(chunk);
    };
    child.stdout.setEncoding('utf8');
    child.stderr.setEncoding('utf8');
    child.stdout.on('data', (chunk) => {
      stdout += chunk;
      forward(chunk);
    });
    child.stderr.on('data', (chunk) => {
      stderr += chunk;
      forward(chunk);
    });

    const timer = setTimeout(() => {
      timedOut = true;
      log(`[${tag}] ${bin} 超过 ${timeoutMs}ms，发送 SIGTERM`);
      signalGroup(child, 'SIGTERM', tag);
      killTimer = setTimeout(() => signalGroup(child, 'SIGKILL', tag), KILL_GRACE_MS);
    }, timeoutMs);
    const onSigterm = () => {
      if (finished || terminated) return;
      terminated = true;
      log(`[${tag}] 收到 SIGTERM，清理 claude 进程组`);
      signalGroup(child, 'SIGTERM', tag);
      clearTimeout(killTimer);
      killTimer = setTimeout(() => signalGroup(child, 'SIGKILL', tag), CANCEL_GRACE_MS);
    };
    process.once('SIGTERM', onSigterm);

    // 统一收尾：停计时器、整组 SIGKILL 收掉存活的后代、销毁管道（后代可能还握着），再返回
    const finish = (result) => {
      if (finished) return;
      finished = true;
      clearTimeout(timer);
      clearTimeout(killTimer);
      clearTimeout(graceTimer);
      process.off('SIGTERM', onSigterm);
      signalGroup(child, 'SIGKILL', tag);
      child.stdout.destroy();
      child.stderr.destroy();
      sink.close();
      resolve({ output, stdout, stderr, timedOut, terminated, ...result });
      // 取消路径要保证本进程能在执行器的 SIGKILL 之前自行收尾
      if (terminated) setTimeout(() => process.exit(2), 1000).unref();
    };
    child.on('error', (error) => {
      log(`[${tag}] 启动 ${bin} 失败: ${error?.message || error}`);
      finish({ code: null, output: `${output}\n${error?.message || error}`, timedOut: false, terminated: false });
    });
    child.on('exit', (code) => {
      // 超时/取消后以 exit 为准；正常退出则给输出管道一个短宽限，仍不关就强收
      if (timedOut || terminated) finish({ code });
      else graceTimer = setTimeout(() => finish({ code }), EXIT_GRACE_MS);
    });
    child.on('close', (code) => finish({ code }));
  });
}

/** 在 worktree 里运行 git（不经 shell、禁用 pathspec 魔法、不弹凭据提示、60s 超时），返回 stdout；失败返回 null。 */
export async function gitOut(worktree, args) {
  const { code, stdout } = await gitRun(worktree, args);
  return code === 0 ? stdout : null;
}

/** 同 gitOut，但返回 { code, stdout }：code 为退出码，启动失败/超时为 null（用于区分"答案是否"与"执行失败"）。 */
export function gitRun(worktree, args) {
  return new Promise((resolve) => {
    execFile(
      'git',
      ['--literal-pathspecs', '-C', worktree, ...args],
      { env: claudeEnv(), encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, timeout: GIT_TIMEOUT_MS },
      (error, stdout) => resolve({ code: error ? (typeof error.code === 'number' && !error.killed ? error.code : null) : 0, stdout }),
    );
  });
}

/** 当前 HEAD 的 SHA；不是仓库或没有提交返回 null。 */
export async function headSha(worktree) {
  return (await gitOut(worktree, ['rev-parse', '--verify', 'HEAD']))?.trim() || null;
}

/**
 * 工作区当前所有改动条目（{ key: `XY path`, path }，路径相对仓库根，未跟踪文件逐个列出）。
 * 不是仓库或命令失败返回 null。重命名条目只记新路径。
 */
export async function snapshotChanges(worktree) {
  const out = await gitOut(worktree, ['status', '--porcelain', '-z', '-uall']);
  if (out === null) return null;
  const parts = out.split('\0').filter(Boolean);
  const entries = [];
  for (let i = 0; i < parts.length; i += 1) {
    const xy = parts[i].slice(0, 2);
    entries.push({ key: parts[i], path: parts[i].slice(3) });
    if (xy.includes('R') || xy.includes('C')) i += 1; // 后随一个原路径条目
  }
  return entries;
}

/**
 * 相对 before 快照新增的改动，按是否位于 sprint 目录分成 { scope, inside, outside }（路径相对仓库根，
 * scope 为 sprint 目录前缀）；无法用 git status 判定时返回 null。
 */
async function newChanges(worktree, sprintDir, before) {
  const after = await snapshotChanges(worktree);
  const prefix = await gitOut(worktree, ['rev-parse', '--show-prefix']);
  if (before === null || after === null || prefix === null) return null;
  const known = new Set(before.map((e) => e.key));
  const sprintRel = path.posix.normalize(sprintDir.replace(/\\/g, '/')).replace(/\/+$/, '');
  const scope = `${prefix.trim()}${sprintRel}/`;
  const fresh = after.filter((e) => !known.has(e.key)).map((e) => e.path);
  return { scope, inside: fresh.filter((p) => p.startsWith(scope)), outside: fresh.filter((p) => !p.startsWith(scope)) };
}

/** 相对 before 快照新增的、位于 sprint 目录之外的改动路径；无法判定时返回 []。 */
export async function outOfScopeChanges(worktree, sprintDir, before, tag = 'claude') {
  const changes = await newChanges(worktree, sprintDir, before);
  if (changes === null) log(`[${tag}] 无法用 git status 检查越界写，跳过`);
  return changes?.outside ?? [];
}

/** 相对 before 快照新增的、sprint 目录内除 allowed（文件名）以外的改动路径；无法判定时返回 []。 */
export async function sprintChangesExcept(worktree, sprintDir, before, allowed, tag = 'claude') {
  const changes = await newChanges(worktree, sprintDir, before);
  if (changes === null) log(`[${tag}] 无法用 git status 检查 sprint 目录，跳过`);
  return changes?.inside.filter((p) => p !== `${changes.scope}${allowed}`) ?? [];
}

// 独立裁判只消费控制器提供的冻结输入；空目录、无工具、只读、无网络、无历史会话。
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { runClaude, claudeFailure } from './claude.mjs';

export async function callCodexJudge({ system, user }, { model, codexHome, codexBin, transcriptPath, timeoutMs = 600000 }) {
  if (!codexHome || !model) throw new Error('judge_codex_config_missing');
  const cwd = fs.mkdtempSync(path.join(os.tmpdir(), 'coding-wf-judge-'));
  const lastMessage = path.join(cwd, 'last-message.txt');
  try {
    const run = await runClaude({
      provider: 'codex', cwd, timeoutMs, tag: 'judge', transcriptPath, isolateRemote: true,
      nativeOptions: { access: 'judge', outputLastMessage: lastMessage },
      codexEnv: { CODING_WF_CODEX_HOME: codexHome, CODING_WF_CODEX_MODEL: model, CODING_WF_CODEX_BIN: codexBin || 'codex' },
      args: ['-p', `${system}\n\n${user}`, '--permission-mode', 'acceptEdits', '--disallowedTools', 'Bash'],
    });
    const rows = run.stdout.split('\n').flatMap((line) => { try { return [JSON.parse(line)]; } catch { return []; } });
    const failed = rows.some((r) => r.type === 'turn.failed' || r.type === 'error');
    const failure = claudeFailure({ ...run, code: failed && run.code === 0 ? 1 : run.code }, { streamJson: true });
    if (failure) throw new Error(failure.reason_code === 'codex_auth' ? 'judge_codex_auth' : failure.reason_code === 'codex_configuration' ? 'judge_codex_configuration' : run.timedOut ? 'judge_codex_timeout' : 'judge_codex_failed');
    if (rows.some((r) => /^item\./.test(r.type ?? '') && !['agent_message', 'reasoning'].includes(r.item?.type))) throw new Error('judge_codex_tool_used');
    const completed = rows.filter((r) => r.type === 'turn.completed');
    if (completed.length !== 1) throw new Error('judge_codex_incomplete');
    // 工具输出、推理及中间 commentary 不能冒充裁判最终答复。
    const messages = rows.filter((r) => r.type === 'item.completed' && r.item?.type === 'agent_message');
    const content = fs.existsSync(lastMessage) ? fs.readFileSync(lastMessage, 'utf8') : '';
    if (typeof content !== 'string' || !content.trim()) throw new Error('judge_empty');
    if (!messages.some((r) => r.item.text?.trim() === content.trim())) throw new Error('judge_codex_output_unverified');
    const input_sha256 = createHash('sha256').update(JSON.stringify({ system, user })).digest('hex');
    return { content, usage: completed[0].usage ?? null, provider: 'codex', model, cost_usd: null, transcriptPath, input_sha256 };
  } finally { fs.rmSync(cwd, { recursive: true, force: true }); }
}

// 04-evidence.md 的解析与判定（纯函数）。
// 每条 `### E-n` 下：`对应: I-n[, I-m]`、`verdict: PASS|FAIL`、```command 代码块、```output 代码块（非空）。
import { parseFrontmatter } from './md-chain.mjs';
import { INTENT_ID_RE } from './intent.mjs';

export const OUTPUT_SUMMARY_MAX = 2000;
// 条目标题 `### <前缀>-n`（04 用 E-n 对应 I-n；QA 报告用 T-n 对应 Q-n、X-n 对应 I-n/Q-n）
const itemRe = (prefix) => new RegExp(`^### (${prefix}-\\d+)(?:[\\s:：].*)?$`);
const SECTION_END_RE = /^#{1,3} /;
const FENCE_RE = /^(`{3,}|~{3,})\s*([A-Za-z]*)\s*$/;
const COVERS_RE = /^对应\s*[:：]\s*(.*)$/;
const VERDICT_RE = /^verdict\s*[:：]\s*(\S*)\s*$/;
const REASON_RE = /^原因\s*[:：]\s*(.*?)\s*$/;
const DEFAULT_VERDICTS = ['PASS', 'FAIL'];
const LIST_MARK_RE = /^\s*(?:[-*]\s+)?/;

/** 尾部摘要：超过 OUTPUT_SUMMARY_MAX 时保留末尾并以 … 开头。 */
function tail(text) {
  return text.length > OUTPUT_SUMMARY_MAX ? `…${text.slice(-OUTPUT_SUMMARY_MAX)}` : text;
}

/** 行匹配结果 f 是否闭合以 fence 开启的代码块（同字符、不短于开启、不带语言）。 */
function closes(f, fence) {
  return Boolean(f) && f[1][0] === fence[0] && f[1].length >= fence.length && f[2] === '';
}

/** 按行切出 `### E-n` 段；代码块内的标题行不算结构。返回 [{ id, lines }]。 */
function sections(lines, ITEM_RE) {
  const out = [];
  let current = null;
  let fence = null;
  for (const line of lines) {
    if (fence === null) {
      const item = ITEM_RE.exec(line);
      if (item) {
        current = { id: item[1], lines: [] };
        out.push(current);
        continue;
      }
      if (SECTION_END_RE.test(line)) {
        current = null;
        continue;
      }
    }
    const f = FENCE_RE.exec(line);
    if (f && (fence === null || closes(f, fence))) {
      fence = fence === null ? f[1] : null;
    }
    current?.lines.push(line);
  }
  return out;
}

/** 解析一段：字段行在代码块外，command/output 取第一个同名代码块。 */
function parseSection({ id, lines }, coversRe, verdicts) {
  const errors = [];
  const blocks = {};
  let covers = null;
  let verdict = null;
  let reason = '';
  let open = null;
  for (const line of lines) {
    if (open) {
      const f = FENCE_RE.exec(line);
      if (closes(f, open.fence)) {
        if (!(open.lang in blocks)) blocks[open.lang] = open.body.join('\n');
        open = null;
      } else {
        open.body.push(line);
      }
      continue;
    }
    const f = FENCE_RE.exec(line);
    if (f) {
      open = { fence: f[1], lang: f[2], body: [] };
      continue;
    }
    // 字段行去列表符号与 markdown 加粗（`**verdict**: PASS`）
    const field = line.replace(LIST_MARK_RE, '').replace(/\*\*|__/g, '').trim();
    const c = COVERS_RE.exec(field);
    if (c && covers === null) covers = c[1].split(/[,，、\s]+/).filter(Boolean);
    const v = VERDICT_RE.exec(field);
    if (v && verdict === null) verdict = v[1].toUpperCase();
    const r = REASON_RE.exec(field);
    if (r && !reason) reason = r[1];
  }
  // 文末仍开着的代码块按闭合到文末处理（真实 claude 会漏写最后的闭合 ```，2c34f677）。
  // 文中未闭合的块会吞掉后面的 E-n，那些 I-n 照样判未覆盖，不因此放宽。
  if (open && !(open.lang in blocks)) blocks[open.lang] = open.body.join('\n').replace(/\n+$/, '');

  if (!covers || covers.length === 0) errors.push(`${id}:covers_missing`);
  else for (const c of covers.filter((x) => !coversRe.test(x))) errors.push(`${id}:covers_invalid:${c}`);
  if (verdict === null) errors.push(`${id}:verdict_missing`);
  else if (!verdicts.includes(verdict)) errors.push(`${id}:verdict_invalid`);
  for (const lang of ['command', 'output']) {
    if (!(lang in blocks)) errors.push(`${id}:${lang}_missing`);
    else if (blocks[lang].trim() === '') errors.push(`${id}:${lang}_empty`);
  }
  return { item: { id, covers: covers ?? [], verdict, ...(reason ? { reason } : {}), command: blocks.command ?? '', output: blocks.output ?? '' }, errors };
}

/**
 * 解析证据文本 → { items: [{id, covers, verdict, command, output}], errors }。有无 frontmatter 均可。
 * 缺省按 04-evidence.md（E-n 对应 I-n）；QA 报告传 { prefix: 'T', coversRe: /^Q-\d+$/ } 等。
 * verdicts：允许的结论，缺省 PASS/FAIL；QA 报告另允许 CANNOT_VERIFY（验不了，配 `原因:` 字段，记在 item.reason）。
 */
export function parseEvidence(text, { prefix = 'E', coversRe = INTENT_ID_RE, verdicts = DEFAULT_VERDICTS } = {}) {
  if (typeof text !== 'string') return { items: [], errors: ['evidence_not_text'] };
  const body = parseFrontmatter(text)?.body ?? text;
  const items = [];
  const errors = [];
  const seen = new Set();
  for (const section of sections(body.split(/\r?\n/), itemRe(prefix))) {
    if (seen.has(section.id)) {
      errors.push(`${section.id}:duplicate`);
      continue;
    }
    seen.add(section.id);
    const parsed = parseSection(section, coversRe, verdicts);
    items.push(parsed.item);
    errors.push(...parsed.errors);
  }
  return { items, errors };
}

/**
 * 按 intentIds 判定解析结果。依次：格式错误或引用未知 I-n → evidence_invalid（errors）；
 * 有 I-n 未覆盖 → evidence_incomplete（missing）；任一 FAIL → verification_failed（failed 带尾部摘要）；
 * 否则 reason null。覆盖完整时附 summary（每条 I-n 的 verdict，被任一 FAIL 条目覆盖即 FAIL）与 verifiedIds。
 */
export function judgeEvidence({ items, errors }, intentIds) {
  const known = new Set(intentIds);
  const invalid = [...errors];
  for (const item of items) {
    for (const c of item.covers.filter((x) => INTENT_ID_RE.test(x) && !known.has(x))) invalid.push(`${item.id}:covers_unknown:${c}`);
  }
  if (invalid.length > 0) return { reason: 'evidence_invalid', errors: invalid };

  const missing = intentIds.filter((id) => !items.some((item) => item.covers.includes(id)));
  if (missing.length > 0) return { reason: 'evidence_incomplete', missing };

  const failedItems = items.filter((item) => item.verdict === 'FAIL');
  const summary = intentIds.map((id) => ({
    intent: id,
    verdict: failedItems.some((item) => item.covers.includes(id)) ? 'FAIL' : 'PASS',
  }));
  if (failedItems.length > 0) {
    const failed = failedItems.map(({ id, covers, command, output }) => ({ id, covers, command: tail(command), output: tail(output) }));
    return { reason: 'verification_failed', failed, summary };
  }
  return { reason: null, verifiedIds: [...intentIds], summary };
}

// 独立裁判（决策 02d8e749 的 ②d）：真人 QA PASS 后、合并前，用不同于开发/QA 的模型复核
// 「需求 01 + 合同 02 + QA 报告 05 + PR 改动」，逐条判 I-n 是否真被满足。
// 问题三类：product（代码没做到）/ qa_gap（QA 没真验到）/ contract_gap（合同没覆盖需求）。
// 规格条款对裁判有约束力，裁判看得到前几轮裁决；推翻前轮结论的问题（reverses）判 ruling_conflict 交 coding commander，
// 不让开发跟着来回改（金丝雀 4 PR #6232 第 8/9 轮翻转，跑了 10 轮）。
// 裁决由程序判（不信模型自报 verdict）：每条 I-n 都满足且没有阻断/重要问题才 PASS。
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { loadPrompt } from './claude.mjs';
import { BLOCKING } from './review.mjs';
import { callCodexJudge } from './codex-judge.mjs';

// 与 Brain 现役裁判（src/harness-judge.js）同一默认：裁判不能比被审的角色弱
export const DEFAULT_JUDGE_MODEL = 'gpt-5.6-sol';
const DEFAULT_API = 'https://toapis.com/v1';
const DEFAULT_TIMEOUT_MS = 10 * 60 * 1000;
const SEVERITIES = new Set(['阻断', '重要', '建议']);
// 问题类型 → 失败类别；顺序即优先级（产品问题先修，其次补验，最后回到需求层面）
const TYPE_CLASS = [['product', 'product_failure'], ['qa_gap', 'qa_insufficient'], ['contract_gap', 'contract_gap']];
const REVERSES_RE = /^r\d+:J-\d+$/;
const TYPES = new Set(TYPE_CLASS.map(([t]) => t));
// 裁判必须看到完整改动（审计 #43）：超过 JUDGE_DIFF_LIMIT 由调用方升级（runner/lib/judge-gate.mjs），这里的截断只是兜底
export const JUDGE_DIFF_LIMIT = 150000;
const CAPS = { intent: 20000, spec: 40000, qaReport: 40000, diff: JUDGE_DIFF_LIMIT, ruling: 12000, rulings: 30000 };
const I_RE = /^I-\d+$/;

export const judgeFileName = (round) => `06-judge-r${round}.md`;

const cap = (text, n) => {
  const s = String(text ?? '');
  return s.length > n ? `${s.slice(0, n)}\n…（已截断，原文 ${s.length} 字符）` : s;
};

/** 前几轮裁决原文：从最近的往前收，单份与总量封顶；更早的注明略去。 */
function priorRulingsText(rulings = []) {
  const kept = [];
  let total = 0;
  for (const r of [...rulings].sort((a, b) => b.round - a.round)) {
    const text = cap(r.text, CAPS.ruling);
    if (kept.length > 0 && total + text.length > CAPS.rulings) break;
    kept.unshift(`### 第 ${r.round} 轮\n${text}`);
    total += text.length;
  }
  if (kept.length === 0) return '（无，本轮是首次裁决）';
  const dropped = rulings.length - kept.length;
  return `${dropped > 0 ? `（更早的 ${dropped} 轮裁决略）\n\n` : ''}${kept.join('\n\n')}`;
}

/** → { system, user }；priorRulings：[{ round, text }] 前几轮裁决原文。 */
export function buildJudgePrompt({ intent, spec, qaReport, qaReportFile = '05-qa-report.md', diff, intentIds, round = 1, priorRulings = [] }) {
  return {
    system: '你是严格的独立验收裁判，只输出合法 JSON。输出使用简体中文。',
    user: loadPrompt('judge', {
      ROUND: String(round),
      INTENT_IDS: intentIds.join(','),
      QA_REPORT_FILE: qaReportFile,
      INTENT: cap(intent, CAPS.intent),
      SPEC: cap(spec, CAPS.spec),
      QA_REPORT: cap(qaReport, CAPS.qaReport),
      PRIOR_RULINGS: priorRulingsText(priorRulings),
      DIFF: cap(diff, CAPS.diff) || '（无代码改动）',
    }),
  };
}

function checkIssue(raw, intentIds, errors) {
  const id = typeof raw?.id === 'string' && /^J-\d+$/.test(raw.id) ? raw.id : `J-?${errors.length}`;
  const covers = Array.isArray(raw?.covers) ? raw.covers.map(String) : [];
  if (!TYPES.has(raw?.type)) errors.push(`${id}:type_invalid`);
  if (!SEVERITIES.has(raw?.severity)) errors.push(`${id}:severity_invalid`);
  if (covers.length === 0 || covers.some((c) => !intentIds.includes(c))) errors.push(`${id}:covers_invalid`);
  if (!String(raw?.detail ?? '').trim()) errors.push(`${id}:detail_missing`);
  const reverses = Array.isArray(raw?.reverses) ? raw.reverses.map(String) : [];
  if (reverses.some((r) => !REVERSES_RE.test(r))) errors.push(`${id}:reverses_invalid`);
  return { id, type: raw?.type, severity: raw?.severity, covers, detail: String(raw?.detail ?? ''), where: String(raw?.where ?? ''), reverses };
}

/** 解析模型输出 → { coverage, issues, summary, errors }。 */
export function parseJudge(content, { intentIds }) {
  const m = /\{[\s\S]*\}/.exec(String(content ?? ''));
  if (!m) return { coverage: [], issues: [], summary: '', errors: ['json_missing'] };
  let obj;
  try {
    obj = JSON.parse(m[0]);
  } catch {
    return { coverage: [], issues: [], summary: '', errors: ['json_invalid'] };
  }
  const errors = [];
  const coverage = [];
  for (const c of Array.isArray(obj.coverage) ? obj.coverage : []) {
    const intent = String(c?.intent ?? '');
    if (!I_RE.test(intent) || !intentIds.includes(intent)) {
      errors.push(`${intent || '?'}:coverage_unknown`);
      continue;
    }
    if (typeof c.satisfied !== 'boolean') errors.push(`${intent}:satisfied_invalid`);
    if (!String(c.evidence ?? '').trim()) errors.push(`${intent}:evidence_missing`);
    coverage.push({ intent, satisfied: c.satisfied === true, evidence: String(c.evidence ?? '') });
  }
  for (const id of intentIds) if (!coverage.some((c) => c.intent === id)) errors.push(`${id}:coverage_missing`);
  const issues = (Array.isArray(obj.issues) ? obj.issues : []).map((i) => checkIssue(i, intentIds, errors));
  // satisfied 非布尔已报错，不再重复追究原因
  const explicitNo = new Set((Array.isArray(obj.coverage) ? obj.coverage : []).filter((c) => c?.satisfied === false).map((c) => c.intent));
  for (const c of coverage.filter((x) => explicitNo.has(x.intent))) {
    if (!issues.some((i) => BLOCKING.has(i.severity) && i.covers.includes(c.intent))) errors.push(`${c.intent}:unsatisfied_without_issue`);
  }
  return { coverage, issues, summary: String(obj.summary ?? ''), errors };
}

/** 程序裁决：→ { verdict, failure_class, blocking, unsatisfied }。 */
export function decideJudge({ coverage, issues }) {
  const blocking = issues.filter((i) => BLOCKING.has(i.severity));
  const unsatisfied = coverage.filter((c) => !c.satisfied).map((c) => c.intent);
  if (blocking.length === 0 && unsatisfied.length === 0) return { verdict: 'PASS', failure_class: null, blocking: [], unsatisfied: [] };
  // 推翻前轮裁决：开发照哪轮改都是错，交 coding commander 按规格裁（优先于其他类别）
  if (blocking.some((i) => i.reverses?.length > 0)) return { verdict: 'FAIL', failure_class: 'ruling_conflict', blocking, unsatisfied };
  const failureClass = TYPE_CLASS.find(([t]) => blocking.some((i) => i.type === t))?.[1] ?? 'product_failure';
  return { verdict: 'FAIL', failure_class: failureClass, blocking, unsatisfied };
}

/** 06-judge-r<round>.md */
export function renderJudgeReport({ round, model, parsed, decision, qaReport }) {
  const lines = [
    `# 独立裁判（第 ${round} 轮）`,
    '',
    `- 裁决：**${decision.verdict}**${decision.failure_class ? `（${decision.failure_class}）` : ''}`,
    `- 模型：${model}`,
    `- 复核的 QA 报告：${qaReport}`,
    `- 总评：${parsed.summary || '（无）'}`,
    '',
    '## 需求覆盖',
  ];
  for (const c of parsed.coverage) lines.push('', `### ${c.intent}`, `- ${c.satisfied ? '满足' : '未满足'}`, `- 依据：${c.evidence}`);
  lines.push('', '## 问题');
  if (parsed.issues.length === 0) lines.push('', '（无）');
  for (const i of parsed.issues) {
    lines.push('', `### ${i.id}`, `- 类型：${i.type}`, `- 严重度：${i.severity}`, `- 对应：${i.covers.join('、')}`, `- 位置：${i.where || '（未给）'}`, `- 说明：${i.detail}`);
    if (i.reverses?.length > 0) lines.push(`- 推翻前轮：${i.reverses.join('、')}`);
  }
  return `${lines.join('\n')}\n`;
}

function readCreds(file) {
  try {
    const out = {};
    for (const line of fs.readFileSync(file, 'utf8').split(/\r?\n/)) {
      const m = /^\s*(?:export\s+)?(TOAPIS_API_KEY|TOAPIS_BASE_URL)\s*=\s*(\S+)\s*$/.exec(line);
      if (m) out[m[1]] = m[2];
    }
    return out;
  } catch {
    return {};
  }
}

/** 裁判连接配置：环境变量优先，否则读 ToAPIs 凭据文件（运行时读，不进代码/plist）。 */
export function resolveJudgeConfig(env = process.env) {
  const provider = env.CODING_WF_JUDGE_PROVIDER || 'api';
  if (!['api', 'codex'].includes(provider)) throw new Error('judge_provider_unsupported');
  if (provider === 'codex') return {
    provider,
    model: env.CODING_WF_JUDGE_MODEL || 'gpt-6-astra',
    codexHome: env.CODING_WF_CODEX_HOME || null,
    codexBin: env.CODING_WF_CODEX_BIN || 'codex',
  };
  const creds = readCreds(env.CODING_WF_JUDGE_CREDS || path.join(env.HOME || os.homedir(), '.credentials/toapis.env'));
  return {
    api: env.CODING_WF_JUDGE_API || env.TOAPIS_BASE_URL || creds.TOAPIS_BASE_URL || DEFAULT_API,
    key: env.TOAPIS_API_KEY || creds.TOAPIS_API_KEY || null,
    model: env.CODING_WF_JUDGE_MODEL || env.TOAPIS_JUDGE_MODEL || DEFAULT_JUDGE_MODEL,
  };
}

/** OpenAI 兼容 chat/completions → { content, usage }；失败抛 Error(judge_*)。 */
export async function callJudge({ system, user }, config) {
  if (config.provider === 'codex') return callCodexJudge({ system, user }, config);
  if (config.provider && config.provider !== 'api') throw new Error('judge_provider_unsupported');
  const { api, key, model, timeoutMs = DEFAULT_TIMEOUT_MS, fetchFn = fetch } = config;
  if (!key) throw new Error('judge_key_missing');
  let res;
  try {
    res = await fetchFn(`${String(api).replace(/\/+$/, '')}/chat/completions`, {
      method: 'POST',
      headers: { authorization: `Bearer ${key}`, 'content-type': 'application/json' },
      body: JSON.stringify({ model, temperature: 0, messages: [{ role: 'system', content: system }, { role: 'user', content: user }] }),
      signal: AbortSignal.timeout(timeoutMs),
    });
  } catch (error) {
    throw new Error(`judge_network: ${error?.message || error}`);
  }
  if (!res.ok) throw new Error(`judge_http_${res.status}`);
  const data = await res.json();
  const content = data?.choices?.[0]?.message?.content ?? '';
  if (!String(content).trim()) throw new Error('judge_empty');
  return { content, usage: data?.usage ?? null };
}

import fs from 'node:fs';
import path from 'node:path';

const OUTPUT_KEY_RE = /^[A-Za-z_][A-Za-z0-9_]*$/;
const STATUSES = new Set(['completed', 'partial', 'failed']);
const FAILURE_CLASSES = new Set(['retryable', 'needs_human', 'fatal']);

/** 日志一律走 stderr，stdout 只留给结果 JSON。 */
export function log(...args) {
  console.error(...args);
}

const GIT_ENV_KEYS = ['GIT_DIR', 'GIT_WORK_TREE', 'GIT_INDEX_FILE'];

/**
 * 子进程环境：复制 base，剥离从 git 钩子继承来的 GIT_DIR/GIT_WORK_TREE/GIT_INDEX_FILE
 * （否则 git 命令会指向错误仓库）。stripClaude 时再剥离 CLAUDECODE 与 CLAUDE_CODE_*，
 * 避免子 claude 误判自己嵌套在另一个会话里。不修改 base。
 */
export function childEnv(base = process.env, { stripClaude = false } = {}) {
  const env = { ...base };
  for (const key of GIT_ENV_KEYS) delete env[key];
  if (stripClaude) {
    for (const key of Object.keys(env)) {
      if (key === 'CLAUDECODE' || key.startsWith('CLAUDE_CODE_')) delete env[key];
    }
  }
  return env;
}

/**
 * 把 sprintDir 解析到 worktree 下的绝对路径。
 * worktree 非绝对路径字符串、sprintDir 为绝对路径或含 `..` 段时抛 Error('sprint_dir_invalid')。
 */
export function resolveSprintDir(worktree, sprintDir) {
  if (typeof worktree !== 'string' || !path.isAbsolute(worktree)) {
    throw new Error('sprint_dir_invalid');
  }
  if (typeof sprintDir !== 'string' || sprintDir === '' || path.isAbsolute(sprintDir)) {
    throw new Error('sprint_dir_invalid');
  }
  if (sprintDir.split(/[\\/]+/).includes('..')) {
    throw new Error('sprint_dir_invalid');
  }
  const resolved = path.join(worktree, sprintDir);
  // '.'、'./' 等解析后就是 worktree 本身：会让"只处理 sprint 目录"扩大成整个工作区
  if (path.relative(worktree, resolved) === '') {
    throw new Error('sprint_dir_invalid');
  }
  return resolved;
}

/**
 * 活动入口的公共输入校验：先 task_id，再 worktree/sprint_dir。
 * 失败 throw Error(reason_code)，由 runActivity 转成 failed/fatal；成功返回 { dir }（sprint 目录绝对路径）。
 */
export function validateBase(input) {
  const taskId = input?.task_id;
  if (typeof taskId !== 'string' || taskId === '') throw new Error('task_id_missing');
  return { dir: resolveSprintDir(input.worktree, input.sprint_dir) };
}

/** 生成活动失败结果；extra（如 evidence）并入。 */
export function fail(failureClass, reasonCode, extra = {}) {
  return { status: 'failed', failure_class: failureClass, reason_code: reasonCode, ...extra };
}

function readStdin() {
  return fs.readFileSync(0, 'utf8');
}

function isPlainObject(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function degrade(result, reasonCode) {
  return {
    ...result,
    status: 'failed',
    failure_class: 'fatal',
    outputs: {},
    metrics: {},
    evidence: [],
    reason_code: reasonCode,
  };
}

/**
 * 把 handler 返回值规整成协议结果。纯函数。
 * outputs/metrics 必须是 plain object，evidence 必须是数组，否则降级 failed/fatal。
 */
export function buildResult(input, res) {
  const status = STATUSES.has(res?.status) ? res.status : 'failed';
  let failureClass = null;
  if (status !== 'completed') {
    failureClass = FAILURE_CLASSES.has(res?.failure_class) ? res.failure_class : 'fatal';
  }
  const result = {
    schema_version: 1,
    run_tag: input?.run_tag ?? null,
    status,
    failure_class: failureClass,
    outputs: res?.outputs === undefined ? {} : res.outputs,
    metrics: res?.metrics === undefined ? {} : res.metrics,
    evidence: res?.evidence === undefined ? [] : res.evidence,
  };
  if (res?.reason_code) result.reason_code = res.reason_code;

  if (!isPlainObject(result.outputs) || !isPlainObject(result.metrics) || !Array.isArray(result.evidence)) {
    return degrade(result, 'result_payload_invalid');
  }
  const badKey = Object.keys(result.outputs).find((k) => !OUTPUT_KEY_RE.test(k));
  if (badKey !== undefined) {
    return degrade(result, `outputs_key_invalid:${badKey}`);
  }
  return result;
}

/**
 * json-stdio-v1 活动入口：读 stdin JSON → 调 handler → stdout 写一次结果 JSON。
 * completed 退出码 0，其余 2；handler 抛错 → failed/fatal，reason_code=error.message。
 */
export async function runActivity(handler, provenance) {
  // stdout 只留给结果 JSON：依赖或 handler 里的 console.log 一律改道 stderr
  console.log = log;
  console.info = log;
  console.debug = log;

  let input = null;
  let result;
  try {
    input = JSON.parse(readStdin());
    if (provenance) {
      validateBase(input);
      const { runRecordedActivity } = await import('./activity-provenance.mjs');
      result = await runRecordedActivity(input, provenance, async (current) => buildResult(current, await handler(current)));
    } else result = buildResult(input, await handler(input));
  } catch (error) {
    log(error?.stack || String(error));
    result = buildResult(input, {
      status: 'failed',
      failure_class: 'fatal',
      reason_code: error?.message || 'handler_error',
    });
  }
  process.stdout.write(`${JSON.stringify(result)}\n`);
  process.exitCode = result.status === 'completed' ? 0 : 2;
}

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

export function provenanceRoot(home = os.homedir()) {
  return path.resolve(home, '.cecelia', 'coding-workflow-provenance');
}

// Resolve existing ancestors too: a not-yet-created destination can cross a symlink.
// Reject traversal before normalization, which would otherwise erase alias/../ semantics.
export function canonicalPath(file) {
  if (typeof file !== 'string' || !file || file.includes('\0') || file.split(path.sep).includes('..')) {
    throw new Error('provenance_path_invalid');
  }
  let cursor = path.resolve(file);
  const tail = [];
  for (;;) {
    try {
      fs.lstatSync(cursor);
      return path.join(fs.realpathSync(cursor), ...tail);
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
      // A dangling symlink is not an absent ancestor with a trustworthy destination.
      try { if (fs.lstatSync(cursor).isSymbolicLink()) throw new Error('provenance_path_dangling_symlink'); } catch (inner) {
        if (inner.code !== 'ENOENT') throw inner;
      }
      const parent = path.dirname(cursor);
      if (parent === cursor) throw error;
      tail.unshift(path.basename(cursor));
      cursor = parent;
    }
  }
}

function contains(parent, child) {
  const relative = path.relative(parent, child);
  return relative === '' || (relative !== '..' && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative));
}

export function assertProvenanceSeparation(root, paths) {
  const realRoot = canonicalPath(root);
  for (const file of paths) {
    const real = canonicalPath(file);
    for (const [a, b] of [[path.resolve(root), path.resolve(file)], [realRoot, real]]) {
      if (contains(a, b) || contains(b, a)) throw new Error('provenance_path_overlap');
    }
  }
  return realRoot;
}

// 可信父控制器的临时工作区隐藏/恢复；不声称封锁 Git 历史，也不替代产品 QA。
import fs from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { hash, fail, gitText, gitBytes, gitMode, noLinks, workingBytes, workingMode, taskDir, writeEvent, UUID, SHA } from './record-provenance-store.mjs';

const POLICY = 'evaluate_workspace_reports_v1';
const FILES = ['03-build.md', '04-evidence.md'];
const HEX = /^[a-f0-9]{64}$/;
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const exists = file => { try { fs.lstatSync(file);return true; } catch (e) { if (e.code === 'ENOENT') return false;throw e; } };
const identity = c => hash(JSON.stringify([fs.realpathSync(c.worktree), gitText(c.worktree, 'rev-parse', '--absolute-git-dir')]));
const exactKeys = (o, keys) => o && typeof o === 'object' && !Array.isArray(o) && same(Object.keys(o).sort(), [...keys].sort());
const check = (value, code) => { if (!value) fail(`isolation_${code}`); };

