const BASE_KEYS = ['schema_version', 'repo', 'task_id', 'id', 'digest', 'kind', 'producer', 'policy', 'sprint_dir', 'run_id', 'stage', 'round', 'head', 'controller', 'worktree_id', 'files', 'phase', 'observed_at'];
