// coding commander（决策 c167d6e3，018e4e84「Commander 是 workflow 的陪跑/兜底」）：runner 自己开的 cw PR 在 QA 门或
// CI 修复升级后，下一轮起 Opus 会话按规格逐条裁决并动手——维持/修订规格（只许在 02-spec.md 末尾追加裁决节）、
// TDD 修代码、给 CI 修复追加额度——程序核对后推送，写 07-commander-rN.md 裁决记录，解除升级，记 Brain
// result.commander_overrides 与 commander span。改需求/改写规格/削弱测试/输出不合格/会话失败/裁决上交/
// 本 PR 介入满 cfg.commanderMax 次/基础设施类升级 → Bark 主理人（同一个升级只通知一次）。
// qa_smoke_missing（API 类 PR 一条回归 smoke 都没固化，决策 4fe863c3）：裁决「放行」（必须写理由）且没改代码 → 直接批准
// 裁决记录推送后的 head；否则只解除升级，head 已变，QA 门下一轮按新 head 重跑。
// 状态：<logDir>[/<仓库命名空间>]/commander-<pr>.json { interventions: [...], human }。
import fs from 'node:fs';
import path from 'node:path';
import { git } from './proc.mjs';
import { removeWorktree } from './worktree.mjs';
import { listOwnPrs } from './cifix-scan.mjs';
import { intentOf, preparePrWorktree, checkFixCommits, pushPrHead, headOf, smokeDirOf } from './pr-branch.mjs';
import { gateSpan, postSpans } from './spans.mjs';
import { runClaude, loadPrompt } from '../../lib/claude.mjs';
import { repoRules } from '../../lib/repo-profile.mjs';
import { sessionLogPath, sessionSummary } from './session-log.mjs';
import { prFile, prLabel } from './repos.mjs';
import { notifyBark } from './bark.mjs';

// commander 能处理的升级；其余（预览环境、裁判不可用/关闭、改动超限、评估会话坏、sprint 丢失……）是基础设施或要人定，直接通知主理人
const SOURCE_CONTROLLER = controllerIdentity(import.meta.url, ['../../lib/record-sources.mjs', '../../lib/claude.mjs', './source-provenance.mjs'].map(p => new URL(p, import.meta.url)));
export const HANDLED = new Set(['judge_contract_gap', 'judge_ruling_conflict', 'qa_fix_failed', 'qa_stalled', 'qa_cannot_verify', 'qa_smoke_missing', 'ci_fix_exhausted']);
const CLAUDE_TOOLS = ['--allowedTools', 'Bash', '--disallowedTools', 'Bash(git push:*)', 'Bash(gh:*)'];
const RUNNER_ID = ['-c', 'user.name=coding-workflow-runner', '-c', 'user.email=coding-workflow-runner@cecelia.local'];
const VERDICTS = new Set(['维持规格', '采纳', '追加额度', '放行', '上交']);

const file = (cfg, name) => prFile(cfg, name);
const readJson = (p, fallback) => {
  try {
    return JSON.parse(fs.readFileSync(p, 'utf8'));
  } catch {
    return fallback;
  }
};
const writeJson = (p, v) => {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, `${JSON.stringify(v, null, 2)}\n`);
};
const readCmd = (cfg, pr) => ({ interventions: [], human: null, ...readJson(file(cfg, `commander-${pr}.json`), {}) });

/** 这个 PR 当前的升级：QA 门优先，其次 CI 修复。 */
function escalationOf(cfg, pr) {
  const qa = readJson(file(cfg, `qa-${pr}.json`), null);
  if (qa?.escalated) return { kind: 'qa', detail: qa.escalated, qa };
  const ci = readJson(file(cfg, `cifix-${pr}.json`), null);
  if (ci?.escalated) return { kind: 'cifix', detail: ci.escalated, ci };
  return null;
}

/** 裁决 JSON 校验 → { ruling } 或 { error }。 */
export function parseRuling(text) {
  let r;
  try {
    r = JSON.parse(text);
  } catch {
    return { error: 'json_invalid' };
  }
  if (!['resume', 'human'].includes(r?.action)) return { error: 'action_invalid' };
  if (!Array.isArray(r.rulings) || r.rulings.length === 0) return { error: 'rulings_missing' };
  for (const x of r.rulings) {
    if (![x?.issue, x?.reason].every((v) => typeof v === 'string' && v.trim()) || !VERDICTS.has(x?.verdict)) return { error: 'ruling_item_invalid' };
  }
  if (typeof r.summary !== 'string' || !r.summary.trim()) return { error: 'summary_missing' };
  if (r.action === 'human' && !(typeof r.human_reason === 'string' && r.human_reason.trim())) return { error: 'human_reason_missing' };
  return { ruling: { ...r, reset_ci_budget: r.reset_ci_budget === true } };
}

/** 07-commander-r<n>.md */
export function renderRuling({ n, escalation, ruling, commits }) {
  const lines = [`# coding commander 裁决（第 ${n} 次）`, '', `- 升级：${escalation.type}`, `- 处理：${ruling.action === 'human' ? '上交主理人' : '解除升级，继续自动流程'}`,
    `- 总结：${ruling.summary}`, ...(ruling.reset_ci_budget ? ['- CI 修复额度：重置'] : []), ...(commits.length ? [`- 提交：${commits.map((c) => c.slice(0, 9)).join('、')}`] : []), '', '## 逐条裁决'];
  for (const x of ruling.rulings) lines.push('', `### ${x.issue}`, `- 裁决：${x.verdict}`, `- 理由：${x.reason}`);
  return `${lines.join('\n')}\n`;
}

/** 通知主理人（Bark）；记 commander 状态与 Brain，同一个升级只通知一次。 */
async function toHuman(ctx, pr, cs, esc, reason, detail, taskId = null) {
  const title = `coding commander 上交：${prLabel(ctx.cfg, pr.number)}`;
  const body = `${esc?.detail?.type ?? '未知升级'}｜${reason}${detail ? `：${detail}` : ''}`;
  const notified = await notifyBark(ctx.cfg, title, body);
  cs.human = { reason, detail: detail ?? null, escalation_at: esc?.detail?.at ?? null, at: new Date().toISOString(), notified };
  writeJson(file(ctx.cfg, `commander-${pr.number}.json`), cs);
  ctx.log(`[coding-commander][P1] PR #${pr.number} 上交主理人：${body}${notified ? '' : '（Bark 未送达）'}`);
  if (taskId) await ctx.brain.patch(taskId, { result: { commander_human: cs.human } });
}

/** qa_smoke_missing 裁决放行（且没改代码）：批准裁决记录推送后的 head，理由记进 smoke_waived 与 smoke_note。 */
function waiveSmoke(s, esc, ruling, { n, head, commits }) {
  const waived = ruling.rulings.filter((x) => x.verdict === '放行');
  if (esc.detail.type !== 'qa_smoke_missing' || waived.length === 0 || commits.length > 0) return;
  const reason = waived.map((x) => `${x.issue}：${x.reason}`).join('；');
  const at = new Date().toISOString();
  s.passed = true;
  s.approved = { head, round: s.rounds?.at(-1)?.round ?? esc.detail.round ?? null, at, by: 'coding-commander' };
  s.smoke_waived = { n, reason, at };
  delete s.smoke_missing;
  s.smoke_note = `${s.smoke_note ? `${s.smoke_note}；` : ''}commander 第 ${n} 次裁决放行：${reason}`;
}

/** 解除升级：QA 门 / CI 修复状态。 */
function release(cfg, pr, esc, ruling, done) {
  if (esc.kind === 'qa') {
    const s = readJson(file(cfg, `qa-${pr}.json`), {});
    delete s.escalated;
    delete s.mirrored;
    if (esc.detail.type === 'qa_stalled') s.stall_floor = (s.rounds ?? []).length;
    waiveSmoke(s, esc, ruling, done);
    writeJson(file(cfg, `qa-${pr}.json`), s);
    return;
  }
  const s = readJson(file(cfg, `cifix-${pr}.json`), {});
  delete s.escalated;
  delete s.mirrored;
  if (ruling.reset_ci_budget) {
    s.archived_attempts = [...(s.archived_attempts ?? []), ...(s.attempts ?? [])];
    s.attempts = [];
  }
  writeJson(file(cfg, `cifix-${pr}.json`), s);
}

/** 核对 commander 的提交：同修复会话的核对（受保护路径、削弱测试），另许改规格但只许纯追加。失败抛 Error(reason)。 */
async function checkCommits(cfg, worktree, before, specRel) {
  const { commits } = await checkFixCommits(worktree, before, { allow: [specRel], smokeDir: smokeDirOf(cfg) });
  const old = await git(worktree, ['show', `${before}:${specRel}`]);
  const now = fs.readFileSync(path.join(worktree, specRel), 'utf8');
  if (old.code === 0 && now !== old.stdout && (!now.startsWith(old.stdout) || !now.slice(old.stdout.length).includes('commander 裁决'))) {
    throw new Error('spec_not_append');
  }
  return commits;
}

async function intervene(ctx, pr, esc, cs, signal) {
  const { cfg } = ctx;
  const n = cs.interventions.length + 1;
  const worktree = path.join(cfg.worktreeBase, `commander-${pr.number}-${n}`);
  fs.mkdirSync(cfg.worktreeBase, { recursive: true });
  if (fs.existsSync(worktree)) await removeWorktree(cfg, worktree, null);
  fs.rmSync(worktree, { recursive: true, force: true });
  const startedAt = Date.now();
  let taskId = null;
  let costUsd;
  let rulingDir;
  const fail = async (reason, detail) => {
    await toHuman(ctx, pr, cs, esc, reason, detail, taskId);
    if (taskId) await postSpans(ctx, [gateSpan({ taskId, key: 'commander', startedAt, endedAt: Date.now(), ok: false, costUsd, occurrence: `${pr.number}:c${n}`, evidence: { escalation: esc.detail.type, reason } })]);
  };
  try {
    await preparePrWorktree(cfg, pr, worktree, signal);
    const intent = intentOf(worktree, pr.headRefName);
    if (!intent?.taskId) return await fail('commander_sprint_missing');
    taskId = intent.taskId;
    const provenance = sourceContext(cfg, worktree, intent, 'commander', n, SOURCE_CONTROLLER);
    const execute = async () => {
      const before = await headOf(worktree);
      verifySourceHead(cfg, worktree, intent, before);
      const specRel = `${intent.sprintDir}/02-spec.md`;
      const contextPath = file(cfg, `commander-${pr.number}-${n}-context.json`);
      const rulingPath = file(cfg, `commander-${pr.number}-${n}-ruling.json`);
      writeJson(contextPath, { pr: pr.number, branch: pr.headRefName, escalation: esc.detail, qa_state: readJson(file(cfg, `qa-${pr.number}.json`), null),
        ci_fix_state: readJson(file(cfg, `cifix-${pr.number}.json`), null), previous: cs.interventions });
      fs.rmSync(rulingPath, { force: true });
      rulingDir = fs.mkdtempSync(path.join(cfg.logDir, `commander-${pr.number}-${n}-ruling-`));
      const sessionRuling = path.join(rulingDir, 'ruling.json');
      const prompt = loadPrompt('commander', {
        ROUND: String(n), MAX: String(cfg.commanderMax), PR_NUMBER: `#${pr.number}`, BRANCH: pr.headRefName,
        ESCALATION_TYPE: esc.detail.type, ESCALATION_JSON: JSON.stringify(esc.detail), CONTEXT_PATH: contextPath,
        SPRINT_DIR: path.join(worktree, intent.sprintDir), INTENT_PATH: path.join(worktree, intent.sprintDir, '01-intent.md'),
        SPEC_PATH: path.join(worktree, specRel), RULING_PATH: sessionRuling, REPO_RULES: repoRules(cfg.repoProfile),
      });
      ctx.log(`coding commander PR #${pr.number} 第 ${n} 次介入（${esc.detail.type}）`);
      // 模型只可写本次裁决目录；QA/合并状态与历史日志不在额外写权限内。
      const run = await runClaude({ args: ['-p', prompt, '--permission-mode', 'acceptEdits', '--add-dir', rulingDir, ...CLAUDE_TOOLS], cwd: worktree, timeoutMs: cfg.commanderTimeoutMs, tag: 'commander', isolateRemote: true,
        transcriptPath: sessionLogPath(cfg, 'commander', pr.number, n) });
      costUsd = run.cost_usd;
      ctx.log(sessionSummary('commander', pr.number, run));
      if (run.timedOut || run.terminated || run.code !== 0) return await fail('commander_session_failed', run.timedOut ? 'timeout' : `exit ${run.code}`);
      const parsed = parseRuling(fs.existsSync(sessionRuling) ? fs.readFileSync(sessionRuling, 'utf8') : '');
      if (parsed.error) return await fail('commander_output_invalid', parsed.error);
      const { ruling } = parsed;
      writeJson(rulingPath, ruling);
      if (ruling.action === 'human') return await fail('commander_human', ruling.human_reason);
      let commits = [];
      if ((await headOf(worktree)) !== before) {
        try {
          commits = await checkCommits(cfg, worktree, before, specRel);
        } catch (error) {
          return await fail(`commander_${error?.message || 'commit_check_failed'}`);
        }
      } else if ((await git(worktree, ['status', '--porcelain'])).stdout.trim()) {
        return await fail('commander_uncommitted');
      }
      const changedSpec = (await git(worktree, ['diff', '--name-only', before, 'HEAD', '--', specRel])).stdout.trim() !== '';
      if (provenance && changedSpec) sealStageEvidence({ files: [specRel], producer: 'model', result: { status: 'completed', outputs: { commander_spec_append: true } } });
      const record = `${intent.sprintDir}/07-commander-r${n}.md`;
      fs.writeFileSync(path.join(worktree, record), renderRuling({ n, escalation: esc.detail, ruling, commits }));
      if (provenance) sealStageEvidence({ files: [record], producer: 'controller_render', result: { status: 'completed', outputs: { action: ruling.action } }, controllerInput: { n, escalation: esc.detail, ruling, commits } });
      const registration = provenance ? beginRecordRegistration(provenance, [...(changedSpec ? [specRel] : []), record]) : null;
      const sourceFiles = registerRecordSources(worktree, { ...intent, stage: 'commander', round: n }, [record]);
      if (registration) observeRecordRegistration(registration, sourceFiles);
      if ((await git(worktree, ['add', '--', record, ...sourceFiles])).code !== 0
        || (await git(worktree, [...RUNNER_ID, 'commit', '-q', '-m', `docs(commander): 第 ${n} 次 coding commander 裁决（${esc.detail.type}）`])).code !== 0) {
        return await fail('commander_record_commit_failed');
      }
      if (registration) finalizeRecordRegistration(registration);
      verifySourceHead(cfg, worktree, intent, await headOf(worktree));
      await pushPrHead(cfg, worktree, pr);
      const head = await headOf(worktree);
      release(cfg, pr.number, esc, ruling, { n, head, commits });
      const entry = { n, at: new Date().toISOString(), kind: esc.kind, escalation: esc.detail, action: 'resume', rulings: ruling.rulings, summary: ruling.summary,
        reset_ci_budget: ruling.reset_ci_budget, commits, record, head, cost_usd: costUsd ?? null };
      cs.interventions.push(entry);
      writeJson(file(cfg, `commander-${pr.number}.json`), cs);
      const task = await ctx.brain.getTask(taskId);
      const prev = task.ok ? task.body?.result?.commander_overrides ?? [] : [];
      const r = await ctx.brain.patch(taskId, { result: { commander_overrides: [...(Array.isArray(prev) ? prev : []), { ...entry, by: 'coding-commander' }] } });
      if (!r.ok) ctx.log(`coding commander 回写 Brain 任务 ${taskId} 失败（HTTP ${r.status}）`);
      await postSpans(ctx, [gateSpan({ taskId, key: 'commander', startedAt, endedAt: Date.now(), ok: true, costUsd, occurrence: `${pr.number}:c${n}`, evidence: { escalation: esc.detail.type, commits: commits.length } })]);
      ctx.log(`coding commander PR #${pr.number} 第 ${n} 次裁决：${ruling.summary}（解除 ${esc.detail.type}）`);
      return true;
    };
    return provenance ? await withRecordProvenance(provenance, execute) : await execute();
  } catch (error) {
    // 会话期间 PR 被关：不推送、不 Bark，升级原样保留，交给外部关闭收尾（pr-closure.mjs）
    if (error?.message === 'pr_closed') {
      ctx.log(`coding commander PR #${pr.number} 已关闭，裁决不推送，交给关闭收尾`);
      return true;
    }
    return await fail('commander_error', String(error?.message || error).slice(0, 300));
  } finally {
    if (rulingDir) fs.rmSync(rulingDir, { recursive: true, force: true });
    await removeWorktree(cfg, worktree, pr.headRefName);
    fs.rmSync(worktree, { recursive: true, force: true });
  }
}

/** 本轮至多处理一个升级了的 PR（介入或通知主理人都算处理）；处理了返回 true。不抛错。 */
export async function runCommander(ctx, signal) {
  const { cfg } = ctx;
  try {
    const prs = await listOwnPrs(cfg);
    for (const pr of prs ?? []) {
      const esc = escalationOf(cfg, pr.number);
      if (!esc) continue;
      const cs = readCmd(cfg, pr.number);
      // 已为这个升级通知过主理人：等人处理（人清掉升级后再升级的是新的一次）
      if (cs.human && cs.human.escalation_at === (esc.detail.at ?? null)) continue;
      if (!HANDLED.has(esc.detail.type)) {
        await toHuman(ctx, pr, cs, esc, 'infra_escalation', esc.detail.type);
        return true;
      }
      if (cs.interventions.length >= cfg.commanderMax) {
        await toHuman(ctx, pr, cs, esc, 'commander_limit', `本 PR 已介入 ${cs.interventions.length} 次`);
        return true;
      }
      await intervene(ctx, pr, esc, cs, signal);
      return true;
    }
  } catch (error) {
    ctx.log(`coding commander 出错：${error?.message || error}`);
  }
  return false;
}

// QA 验不了（CANNOT_VERIFY）的项是否已被 coding commander 裁过接受（金丝雀 6 #6291：
// 已裁「维持规格」的项下一轮 QA 又报同一项，不认前裁就会循环升级到介入上限上交人）。
import fs from 'node:fs';
import { prFile } from './repos.mjs';

const ACCEPT = new Set(['维持规格', '采纳']);

/** 已接受的键：按 Q 项（covers）认，条目没有 covers 时按条目 id 认。读不到记录返回空集。 */
export function acceptedKeys(cfg, prNumber) {
  let cs;
  try {
    cs = JSON.parse(fs.readFileSync(prFile(cfg, `commander-${prNumber}.json`), 'utf8'));
  } catch {
    return new Set();
  }
  const keys = new Set();
  for (const iv of cs?.interventions ?? []) {
    if (iv?.action !== 'resume' || iv.escalation?.type !== 'qa_cannot_verify') continue;
    for (const r of iv.rulings ?? []) {
      if (!ACCEPT.has(r?.verdict)) continue;
      const item = (iv.escalation.cannot_verify ?? []).find((x) => x?.id === r.issue);
      for (const k of item?.covers?.length ? item.covers : [r.issue]) keys.add(k);
    }
  }
  return keys;
}

/** 本轮验不了的项全部已被接受 → 条目 id 列表；有任一未接受（或没有条目）→ null。 */
export function cannotVerifyAccepted(cfg, prNumber, items) {
  if (!Array.isArray(items) || items.length === 0) return null;
  const keys = acceptedKeys(cfg, prNumber);
  const ok = items.every((x) => (x?.covers?.length ? x.covers.every((q) => keys.has(q)) : keys.has(x?.id)));
  return ok ? items.map((x) => x.id) : null;
}

import { controllerIdentity, withRecordProvenance, sealStageEvidence } from '../../lib/record-provenance.mjs';
import { sourceContext, judgeSourceFacts } from './source-provenance.mjs';
// 独立裁判步（决策 02d8e749 ②d）：QA 门里真人 QA PASS 之后、开自动合并之前，在 PR worktree 里
// 读需求 01、合同 02、QA 报告 05 与 PR 代码改动（相对 main，不含 sprints/），交给不同模型（lib/judge.mjs）复核，
// 裁决写 <sprint>/06-judge-r<round>.md（由 QA 门提交进 PR）。
import fs from 'node:fs';
import path from 'node:path';
import { git } from './proc.mjs';
import { buildJudgePrompt, parseJudge, decideJudge, renderJudgeReport, callJudge, judgeFileName, JUDGE_DIFF_LIMIT } from '../../lib/judge.mjs';

const SOURCE_CONTROLLER = controllerIdentity(import.meta.url, ['../../lib/judge.mjs', '../../lib/codex-judge.mjs', './source-provenance.mjs'].map(p => new URL(p, import.meta.url)));

/** 本轮之前已提交的裁决：[{ round, rel }]（sprint 内 06-judge-r<k>.md，k < round，按轮次升序）。 */
export function priorJudgeFiles(worktree, sprintDir, round) {
  const out = [];
  for (let k = 1; k < round; k += 1) {
    const rel = `${sprintDir}/${judgeFileName(k)}`;
    if (fs.existsSync(path.join(worktree, rel))) out.push({ round: k, rel });
  }
  return out;
}

/** PR 相对 main 的代码改动（三点 diff，排除 sprints/ 验收记录）。 */
async function prDiff(worktree) {
  const r = await git(worktree, ['diff', 'origin/main...HEAD', '--', '.', ':(exclude)sprints']);
  if (r.code !== 0) throw new Error('judge_diff_failed');
  return r.stdout;
}

/**
 * 跑一次裁判。成功 → { verdict, failure_class, blocking, unsatisfied, file, model, usage }（已写 06 文件）；
 * 调用失败/输出不合格 → { error, errors? }（模型原始输出记到 logDir）。不抛错。
 */
export async function runJudge(cfg, worktree, intent, options) {
  const context = sourceContext(cfg, worktree, intent, 'judge', options.round, SOURCE_CONTROLLER);
  const run = () => runJudgeObserved(cfg, worktree, intent, options);
  return context ? withRecordProvenance(context, run) : run();
}

async function runJudgeObserved(cfg, worktree, intent, { round, reportRel, log, qaStageEventId, sourceMode = 'pending', testedHead }) {
  const read = (rel) => fs.readFileSync(path.join(worktree, rel), 'utf8');
  let texts;
  try {
    texts = { intent: read(`${intent.sprintDir}/01-intent.md`), spec: read(`${intent.sprintDir}/02-spec.md`), qaReport: read(reportRel) };
  } catch {
    return { error: 'judge_input_missing' };
  }
  let reply, facts;
  try {
    const exact = await git(worktree, ['rev-parse', 'HEAD']);
    if (exact.code !== 0) throw new Error('judge_head_missing');
    facts = judgeSourceFacts(cfg, worktree, intent, exact.stdout.trim(), reportRel,
      { mode: sourceMode, stageEventId: qaStageEventId, testedHead, round });
    const diff = await prDiff(worktree);
    // 裁判必须看到完整改动（审计 #43）：超限不截断照判，交 coding commander
    if (diff.length > JUDGE_DIFF_LIMIT) return { error: 'judge_input_truncated', escalate: true, diff_chars: diff.length };
    // 前几轮裁决（金丝雀 4 翻转）：裁判知道开发方已经照哪些结论改过
    const priorRulings = priorJudgeFiles(worktree, intent.sprintDir, round).map((f) => ({ round: f.round, text: read(f.rel) }));
    const prompt = buildJudgePrompt({ ...texts, diff, qaReportFile: path.basename(reportRel), intentIds: intent.intentIds, round, priorRulings });
    if (facts) prompt.user = `受信控制器来源事实（阶段接收/登记及current_qa.isolation所列本轮控制器临时隐藏与原样恢复；仅解释精确03/04工作区暂移，不证明Git历史保密、不豁免产品范围或命令语义；sealed_not_registered不是已登记）：\n${JSON.stringify(facts)}\n\n${prompt.user}`;
    const transcriptPath = path.join(cfg.logDir, `judge-${intent.taskId || path.basename(intent.sprintDir)}-r${round}-${Date.now()}.jsonl`);
    reply = await callJudge(prompt, { ...cfg.judgeConn, timeoutMs: cfg.judgeTimeoutMs, transcriptPath });
  } catch (error) {
    const reason = String(error?.message || error).split(':')[0];
    return { error: reason, ...(/^judge_codex_(auth|configuration|config_missing)$/.test(reason) ? { escalate: true } : {}) };
  }
  const parsed = parseJudge(reply.content, { intentIds: intent.intentIds });
  if (parsed.errors.length > 0) {
    fs.mkdirSync(cfg.logDir, { recursive: true });
    fs.writeFileSync(path.join(cfg.logDir, `judge-invalid-${Date.now()}.txt`), String(reply.content));
    log?.(`独立裁判输出不合格：${parsed.errors.join(', ')}`);
    return { error: 'judge_output_invalid', errors: parsed.errors };
  }
  const decision = decideJudge(parsed);
  const file = judgeFileName(round);
  const model = cfg.judgeConn.model;
  fs.writeFileSync(path.join(worktree, intent.sprintDir, file), renderJudgeReport({ round, model, parsed, decision, qaReport: path.basename(reportRel) }));
  try {
    sealStageEvidence({ files: [`${intent.sprintDir}/${file}`], producer: 'controller_render',
      result: { status: 'completed', outputs: { judge_verdict: decision.verdict } },
      controllerInput: { round, reportRel, parsed, decision, input_sha256: reply.input_sha256 ?? null,
        ...(facts ? { qa_stage_event_id: facts.current_qa.records.find(r => r.path === reportRel)?.stage_event_id,
          tested_head: facts.current_qa.records.find(r => r.path === reportRel)?.stage_input_head } : {}) } });
  } catch (error) { return { error: error.message }; }
  // 建议级问题不阻断，但要可见（审计 #41）
  const concerns = parsed.issues.filter((i) => i.severity === '建议').map(({ id, severity, covers, detail, where }) => ({ id, severity, covers, detail, where }));
  return { ...decision, concerns, file, model, usage: reply.usage, ...(reply.provider ? { provider: reply.provider, cost_usd: reply.cost_usd, transcript_path: reply.transcriptPath, input_sha256: reply.input_sha256 } : {}) };
}

// runner 自己开的 cw PR 分支上的共用操作（CI 修复与 QA 门共用）：检出 PR 分支 worktree、读 sprint 链信息、核对修复提交、推送。
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { git, gh } from './proc.mjs';
import { writeDevFiles, ensureIgnored, installDeps } from './worktree.mjs';
import { consumeSourceMerge } from './source-merge.mjs';
import { QA_SMOKE_DIR } from '../../lib/qa-smoke.mjs';
import { qaSmokeOf } from '../../lib/repo-profile.mjs';

const FETCH_TIMEOUT_MS = 5 * 60 * 1000;
const PUSH_TIMEOUT_MS = 5 * 60 * 1000;
const GH_TIMEOUT_MS = 60 * 1000;
// 修复提交不许碰：sprint 目录（需求与验收记录）、agent 配置
const PROTECTED_RE = /^(sprints\/|\.claude\/|CLAUDE\.md$|AGENTS\.md$|\.implementation-source-relations\.json$)/;
const escapeRe = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/**
 * 修复提交不许碰的路径。runner 生成的 QA 回归 smoke 只由 runner 固化（金丝雀 4：修复会话改它，与下次固化互相覆盖）：
 * 它在哪个目录按仓库（repos.json qa_smoke.dir，C6）；不传 = 默认仓目录；null = 本仓不固化，不保护。
 */
export function protectedPath(file, smokeDir = QA_SMOKE_DIR) {
  if (PROTECTED_RE.test(file)) return true;
  return Boolean(smokeDir) && new RegExp(`^${escapeRe(smokeDir)}/cw-[0-9a-f]{8}-qa-smoke\\.sh$`).test(file);
}

/** cfg（某仓库视图）的 QA 回归 smoke 目录；cfg 没带 repoProfile = 默认仓；本仓不固化 = null。 */
export function smokeDirOf(cfg) {
  return qaSmokeOf(cfg?.repoProfile)?.dir ?? null;
}
const INTENT_ANCHOR_RE = /^### (I-\d+)(?:[\s:：].*)?$/gm;

const stop = (code) => new Error(code);

/** PR 分支对应的 sprint 目录名（sprints/<stamp>-cw-<id8>）；找不到返回 null。 */
export function sprintDirOf(worktree, branch) {
  const short = branch.slice(-8);
  const sprints = path.join(worktree, 'sprints');
  return fs.existsSync(sprints) ? fs.readdirSync(sprints).find((d) => d.endsWith(`-cw-${short}`)) ?? null : null;
}

/** sprint 的 01-intent.md：{ taskId, intentIds, intentSha256 }；读不到返回 null。 */
export function intentOf(worktree, branch) {
  const dir = sprintDirOf(worktree, branch);
  if (!dir) return null;
  try {
    const text = fs.readFileSync(path.join(worktree, 'sprints', dir, '01-intent.md'), 'utf8');
    return {
      sprintDir: `sprints/${dir}`,
      taskId: /^task_id:\s*(\S+)/m.exec(text)?.[1] ?? null,
      intentIds: [...text.matchAll(INTENT_ANCHOR_RE)].map((m) => m[1]),
      intentSha256: crypto.createHash('sha256').update(text).digest('hex'),
    };
  } catch {
    return null;
  }
}

/** PR 分支 sprint 目录 01-intent.md 里的 task_id；找不到返回 null。 */
export function taskIdOf(worktree, branch) {
  return intentOf(worktree, branch)?.taskId ?? null;
}

/** ref 上 sprints/<stamp>-cw-<id8>/01-intent.md 的 task_id；拿不到返回 null。 */
async function taskIdAtRef(cfg, ref, id8) {
  const ls = await git(cfg.repo, ['ls-tree', '--name-only', ref, 'sprints/']);
  const dir = ls.stdout.split('\n').find((d) => d.endsWith(`-cw-${id8}`));
  if (!dir) return null;
  const show = await git(cfg.repo, ['show', `${ref}:${dir}/01-intent.md`]);
  return show.code === 0 ? /^task_id:\s*(\S+)/m.exec(show.stdout)?.[1] ?? null : null;
}

/** 不检出 worktree，直接从远端 PR 分支读 sprint 01-intent.md 的 task_id；拿不到返回 null。 */
export async function remoteTaskId(cfg, branch) {
  const fetch = await git(cfg.repo, ['fetch', 'origin', `+refs/heads/${branch}:refs/remotes/origin/${branch}`], { timeoutMs: FETCH_TIMEOUT_MS });
  if (fetch.code !== 0) return null;
  return taskIdAtRef(cfg, `origin/${branch}`, branch.slice(-8));
}

/** 分支已删（关 PR 时连带删分支）：从 GitHub 保留的 refs/pull/<n>/head 读 task_id；拿不到返回 null。 */
export async function remoteTaskIdByPr(cfg, number, branch) {
  const ref = `refs/remotes/origin/pr-${number}`;
  const fetch = await git(cfg.repo, ['fetch', 'origin', `+refs/pull/${number}/head:${ref}`], { timeoutMs: FETCH_TIMEOUT_MS });
  if (fetch.code !== 0) return null;
  return taskIdAtRef(cfg, ref, branch.slice(-8));
}

/** 建 PR 分支的 worktree（本地分支同名，提交钩子按 .dev-mode.<branch> 认会话）。失败抛 Error(reason_code)。 */
export async function preparePrWorktree(cfg, pr, worktree, signal) {
  const branch = pr.headRefName;
  const fetch = await git(cfg.repo, ['fetch', 'origin', `+refs/heads/${branch}:refs/remotes/origin/${branch}`], { timeoutMs: FETCH_TIMEOUT_MS });
  if (fetch.code !== 0) throw stop('git_fetch_failed');
  const add = await git(cfg.repo, ['worktree', 'add', '-B', branch, worktree, `origin/${branch}`]);
  if (add.code !== 0) throw stop('worktree_add_failed');
  writeDevFiles(worktree, branch, { id: taskIdOf(worktree, branch) ?? 'unknown', payload: {} }, cfg.repoKey ?? 'cecelia');
  await ensureIgnored(worktree, branch);
  await installDeps(cfg, worktree, signal);
}

// 修复环节不得靠削弱测试变绿（审计 #31，对应旧 generator「CONTRACT IS LAW」）
const TEST_FILE_RE = /(^|\/)(__tests__|tests?)\/|\.(test|spec)\.[cm]?[jt]sx?$/;
const SKIP_RE = /\b(?:it|test|describe)\.(?:skip|only|todo)\s*\(|\bx(?:it|describe)\s*\(/;
const ASSERT_RE = /\bexpect\s*\(|\bassert(?:\.\w+)?\s*\(/g;

const assertCount = (text) => (text.match(ASSERT_RE) ?? []).length;

/**
 * before..head 是否削弱了 main 上已有的测试（决策 b057089b）：删除、加 skip/only/todo、断言比 main 上的版本少。
 * 只守与 origin/main 合并基点上已存在的测试文件——PR 自己新加的测试允许随代码改删
 * （金丝雀 3/4：按裁决删超范围代码时连带删它的测试被拦；行为由真人 QA + 独立裁判兜底）。
 * 取不到合并基点时退回对照 before（从严）。
 */
async function weakenedTests(worktree, before, head, only = null) {
  // 合并基点要按最新的 main 算（克隆里的 origin/main 可能是旧的）；拉不到就用现有的
  await git(worktree, ['fetch', 'origin', 'main'], { timeoutMs: FETCH_TIMEOUT_MS });
  const mb = await git(worktree, ['merge-base', 'origin/main', head]);
  const base = mb.code === 0 && mb.stdout.trim() ? mb.stdout.trim() : before;
  const atBase = async (file) => (await git(worktree, ['cat-file', '-e', `${base}:${file}`])).code === 0;
  const status = (await git(worktree, ['diff', '--name-status', `${before}..${head}`])).stdout.split('\n').filter(Boolean);
  for (const line of status) {
    const [kind, file] = line.split('\t');
    if (!TEST_FILE_RE.test(file ?? '') || (only && !only.includes(file)) || !(await atBase(file))) continue;
    if (kind === 'D') return true;
    const added = (await git(worktree, ['diff', '-U0', `${before}..${head}`, '--', file])).stdout
      .split('\n').filter((l) => l.startsWith('+') && !l.startsWith('+++'));
    if (added.some((l) => SKIP_RE.test(l))) return true;
    const old = (await git(worktree, ['show', `${base}:${file}`])).stdout;
    const now = (await git(worktree, ['show', `${head}:${file}`])).stdout;
    if (assertCount(now) < assertCount(old)) return true;
  }
  return false;
}

const names = async (worktree, range) => (await git(worktree, ['diff', '--name-only', range])).stdout.split('\n').filter(Boolean);

/**
 * before..HEAD 里 PR 自身的改动：合进了 mainRef 时只算合并后仍与 mainRef 不同的文件
 * （main 带进来的 sprints/、测试等不算本 PR 的改动）；不传 mainRef 即 before..HEAD 全部。
 */
export async function ownChangedFiles(worktree, before, mainRef = null) {
  const changed = await names(worktree, `${before}..HEAD`);
  if (!mainRef) return changed;
  const own = new Set(await names(worktree, `${mainRef}..HEAD`));
  return changed.filter((f) => own.has(f));
}

/**
 * claude 修复后的核对：工作区干净、有新提交、只追加不改写、不碰受保护路径、不削弱测试。通过返回 { commits }，否则抛 Error(reason_code)。
 * mainRef：本次合进了 main（冲突修复），受保护路径与削弱测试只核对 PR 自身的改动。smokeDir：本仓 QA 回归 smoke 目录（smokeDirOf(cfg)）。
 */
export async function checkFixCommits(worktree, before, { mainRef = null, allow = [], smokeDir = QA_SMOKE_DIR, sourceMergeToken } = {}) {
  if ((await git(worktree, ['status', '--porcelain'])).stdout.trim()) throw stop('uncommitted');
  const head = (await git(worktree, ['rev-parse', 'HEAD'])).stdout.trim();
  if (!head || head === before) throw stop('no_commit');
  if ((await git(worktree, ['merge-base', '--is-ancestor', before, head])).code !== 0) throw stop('history_rewritten');
  const changed = await ownChangedFiles(worktree, before, mainRef);
  // allow：调用方单独核对的受保护文件（coding commander 只许纯追加的规格）
  const sourceAllowed = sourceMergeToken ? consumeSourceMerge(sourceMergeToken, worktree, before, mainRef) : null;
  if (changed.some((f) => protectedPath(f, smokeDir) && f !== sourceAllowed && (f === '.implementation-source-relations.json' || !allow.includes(f)))) throw stop('protected_path');
  if (await weakenedTests(worktree, before, head, mainRef ? changed : null)) throw stop('test_weakened');
  const log = await git(worktree, ['rev-list', '--reverse', `${before}..${head}`]);
  return { commits: log.stdout.split('\n').filter(Boolean) };
}

/** PR 当前状态（OPEN/CLOSED/MERGED）；查不到（gh 出错）重试一次，仍查不到返回 null。 */
export async function prState(cfg, number) {
  for (let i = 0; i < 2; i += 1) {
    const r = await gh(cfg, ['pr', 'view', String(number), '--json', 'state'], { timeoutMs: GH_TIMEOUT_MS });
    try {
      const state = JSON.parse(r.stdout)?.state;
      if (state) return state;
    } catch { /* 再试一次 */ }
  }
  return null;
}

/**
 * 把 worktree 的 HEAD 推到 PR 分支（快进）。修复会话动辄几十分钟，推送前再确认 PR 仍开着：
 * 已关闭/已合并抛 Error('pr_closed')（调用方不升级，交给外部关闭收尾 pr-closure.mjs）；查不到状态抛 'pr_state_unknown'；推送失败抛 'push_failed'。
 */
export async function pushPrHead(cfg, worktree, pr) {
  const state = await prState(cfg, pr.number);
  if (!state) throw stop('pr_state_unknown');
  if (state !== 'OPEN') throw stop('pr_closed');
  const push = await git(worktree, ['push', 'origin', `HEAD:refs/heads/${pr.headRefName}`], { timeoutMs: PUSH_TIMEOUT_MS });
  if (push.code !== 0) throw stop('push_failed');
}

export async function headOf(worktree) {
  return (await git(worktree, ['rev-parse', 'HEAD'])).stdout.trim();
}

// 子进程工具：统一剥离 CLAUDECODE / CLAUDE_CODE_* / GIT_DIR 等继承变量，带超时。
import { spawn } from 'node:child_process';
import { childEnv } from '../../lib/protocol.mjs';

/** runner 所有子进程的环境：剥离 git 钩子与 claude 会话变量，禁止 git 交互式凭据提示。 */
export function runnerChildEnv(base = process.env) {
  return { ...childEnv(base, { stripClaude: true }), GIT_TERMINAL_PROMPT: '0' };
}

/**
 * 运行命令（不经 shell）。返回 { code, stdout, stderr, timedOut }；启动失败 code=null。
 * input 非空时写进子进程 stdin（活动协议 json-stdio）；env 追加/覆盖子进程环境变量。超时或 signal 中止时先 SIGTERM，5 秒后 SIGKILL。
 */
export function run(bin, args, { cwd, timeoutMs = 10 * 60 * 1000, signal, input, env } = {}) {
  return new Promise((resolve) => {
    let stdout = '';
    let stderr = '';
    let timedOut = false;
    let child;
    try {
      child = spawn(bin, args, { cwd, env: { ...runnerChildEnv(), ...env }, stdio: [input === undefined ? 'ignore' : 'pipe', 'pipe', 'pipe'] });
    } catch (error) {
      resolve({ code: null, stdout, stderr: String(error?.message || error), timedOut });
      return;
    }
    if (input !== undefined) {
      child.stdin.on('error', () => {});
      child.stdin.end(input);
    }
    const stop = () => {
      child.kill('SIGTERM');
      setTimeout(() => child.kill('SIGKILL'), 5000).unref();
    };
    const timer = setTimeout(() => { timedOut = true; stop(); }, timeoutMs);
    signal?.addEventListener('abort', stop, { once: true });
    child.stdout.setEncoding('utf8');
    child.stderr.setEncoding('utf8');
    child.stdout.on('data', (d) => { stdout += d; });
    child.stderr.on('data', (d) => { stderr += d; });
    child.on('error', (error) => {
      clearTimeout(timer);
      resolve({ code: null, stdout, stderr: `${stderr}${error?.message || error}`, timedOut });
    });
    child.on('close', (code) => {
      clearTimeout(timer);
      signal?.removeEventListener('abort', stop);
      resolve({ code, stdout, stderr, timedOut });
    });
  });
}

/**
 * gh 子命令，作用于 cfg 视图的仓库：cwd = 该仓库 clone，并设 GH_REPO=<owner/repo>（等同 gh -R；gh api 的 {owner}/{repo}
 * 占位符也按它解析），不靠 cwd 推断——多仓库时一个调用不会落到别的仓库。输出同 run。
 */
export function gh(cfg, args, opts = {}) {
  return run(cfg.ghBin, args, { cwd: cfg.repo, ...opts, env: { ...(cfg.repoSlug ? { GH_REPO: cfg.repoSlug } : {}), ...opts.env } });
}

/** git -C <dir> ...；输出同 run。 */
export function git(dir, args, opts = {}) {
  return run('git', ['-C', dir, ...args], opts);
}

