/** 该仓库是否走 Brain PR 预览（repos.json preview.type；cfg 没带时按默认仓 brain_preview）。 */
export const usesBrainPreview = (cfg) => (cfg.previewType ?? 'brain_preview') === 'brain_preview';

export function readState(cfg, pr) {
  try {
    const s = JSON.parse(fs.readFileSync(statePath(cfg, pr), 'utf8'));
    return { bad: 0, ...s, rounds: Array.isArray(s?.rounds) ? s.rounds : [] };
  } catch {
    return { rounds: [], bad: 0 };
  }
}

export function writeState(cfg, pr, s) {
  fs.mkdirSync(stateDir(cfg), { recursive: true });
  fs.writeFileSync(statePath(cfg, pr), `${JSON.stringify(s, null, 2)}\n`);
}

export async function previewCall(cfg, route, body) {
  try {
    const res = await fetch(`${cfg.previewApi.replace(/\/+$/, '')}/api/brain/preview/${route}`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', ...(cfg.deployToken ? { authorization: `Bearer ${cfg.deployToken}` } : {}) },
      body: JSON.stringify(body ?? {}),
      signal: AbortSignal.timeout(30000),
    });
    return { ok: res.ok, status: res.status, body: await res.text().catch(() => '') };
  } catch (error) {
    return { ok: false, status: 0, body: String(error?.message || error) };
  }
}

/** 回写 Brain：result.qa 摘要（+ 升级记录）。拿不到 task_id 只记本地。 */
export async function report(ctx, taskId, s) {
  if (!taskId) return;
  const last = s.rounds.at(-1);
  const result = { qa: {
    verdict: last?.verdict ?? null, judge: last?.judge?.verdict ?? null, rounds: s.rounds.length, passed: Boolean(s.passed), last_report: last?.report ?? null,
    // 「完成但有疑虑」可见（审计 #41）：裁判的建议级问题
    concerns: last?.judge?.concerns ?? [],
    // 回归 smoke 固化说明（决策 b8030661）：哪轮固化 / 本轮为何没固化、保留哪轮版本
    smoke_note: s.smoke_note ?? null,
  } };
  if (s.escalated) result.escalations = [s.escalated];
  const r = await ctx.brain.patch(taskId, { result });
  if (!r.ok) ctx.log(`QA 门回写 Brain 任务 ${taskId} 失败（HTTP ${r.status}）`);
}

/** 升级给 coding commander：记状态、P1 日志、回写 Brain；之后本 PR 不再自动处理。 */
export async function escalate(ctx, pr, s, taskId, detail) {
  s.escalated = { ...detail, pr: pr.number, at: new Date().toISOString() };
  ctx.log(`[coding-qa][P1] PR #${pr.number} QA 门升级给 coding commander：${detail.type} ${JSON.stringify(detail)}`);
  writeState(ctx.cfg, pr.number, s);
  await report(ctx, taskId ?? (await remoteTaskId(ctx.cfg, pr.headRefName)), s);
}

/**
 * QA/裁判通过（已开自动合并）后 PR 又被推了改动（CI 修复）：改了记录以外的文件 → 撤销通过、关自动合并，
 * 新 head 在 CI 绿后重新过 QA 与裁判。返回是否撤销。
 */
export async function revokeQaPass(ctx, pr, files, reason) {
  const s = readState(ctx.cfg, pr.number);
  const changed = files.filter((f) => !isRecordFile(f, pr.headRefName));
  if (!s.passed || changed.length === 0) return false;
  const off = await gh(ctx.cfg, ['pr', 'merge', String(pr.number), '--disable-auto'], { timeoutMs: GH_TIMEOUT_MS });
  s.passed = false;
  s.revoked = [...(s.revoked ?? []), { at: new Date().toISOString(), reason, files: changed, automerge_disabled: off.code === 0 }];
  writeState(ctx.cfg, pr.number, s);
  ctx.log(`QA 门 PR #${pr.number} 已通过后又改了代码（${changed.join('、')}）：撤销通过、关自动合并，新 head 重新 QA`);
  return true;
}

/** 预览环境没就绪：不存在/已停 → 请求启动；容量拒绝超过时限 → 升级。 */
async function ensurePreview(ctx, pr, s, p) {
  if (p.state === 'pending' || p.state === 'error') {
    return waitForPreview(ctx, pr, s, p, { writeState, escalate });
  }
  const r = await previewCall(ctx.cfg, 'start', { pr_number: pr.number, branch_name: pr.headRefName, base_repo: ctx.cfg.previewBaseRepo ?? 'cecelia' });
  const now = Date.now();
  if (r.ok) {
    s.preview = { requested_at: new Date(now).toISOString() };
    ctx.log(`PR #${pr.number} 预览环境已请求启动`);
    writeState(ctx.cfg, pr.number, s);
    return;
  }
  const since = s.preview?.rejected_since ? Date.parse(s.preview.rejected_since) : now;
  s.preview = { ...s.preview, rejected_since: new Date(since).toISOString(), last_error: `HTTP ${r.status} ${r.body.slice(0, 300)}` };
  ctx.log(`PR #${pr.number} 预览环境启动被拒：${s.preview.last_error}`);
  if (now - since >= ctx.cfg.qaPreviewEscalateMs) {
    await escalate(ctx, pr, s, null, { type: 'qa_preview_unavailable', last_error: s.preview.last_error, since: s.preview.rejected_since });
    return;
  }
  writeState(ctx.cfg, pr.number, s);
}

/** 预览还是旧版本：记下从何时起；超过时限（与预览起不来同一阈值）升级。 */
async function previewStale(ctx, pr, s, p) {
  const now = Date.now();
  const since = s.preview?.stale_since && s.preview?.stale_head === pr.headRefOid ? Date.parse(s.preview.stale_since) : now;
  s.preview = { ...s.preview, stale_since: new Date(since).toISOString(), stale_head: pr.headRefOid, stale_sha: p.sha };
  ctx.log(`PR #${pr.number} 预览环境还是 ${p.sha ? p.sha.slice(0, 9) : '未知版本'}，不是 head ${pr.headRefOid.slice(0, 9)}，等重新部署`);
  if (now - since >= ctx.cfg.qaPreviewEscalateMs) {
    return escalate(ctx, pr, s, null, { type: 'qa_preview_stale', preview_sha: p.sha, head: pr.headRefOid, since: s.preview.stale_since });
  }
  return writeState(ctx.cfg, pr.number, s);
}

/** 跑 evaluate 活动（json-stdio），返回解析后的结果对象或 null。 */
async function evaluate(ctx, worktree, input, signal) {
  // evaluate 来自 runner 专用 clone（main），不用 PR 分支里可能被改过的版本（审计 P0 #1）
  const entry = ctx.cfg.evaluateEntry || path.join(ctx.cfg.trustedRepo ?? ctx.cfg.repo, EVALUATE_REL);
  const r = await run(process.execPath, [entry], { cwd: worktree, input: JSON.stringify(input), timeoutMs: EVALUATE_TIMEOUT_MS, signal });
  const line = r.stdout.trim().split('\n').reverse().find((l) => l.startsWith('{'));
  try {
    return line ? JSON.parse(line) : null;
  } catch {
    return null;
  }
}

/** 把本轮验收记录（QA 报告、截图目录、裁决）提交并推到 PR 分支。 */
async function commitRecords(cfg, worktree, pr, paths, message, intent, round, smoke = [], qaStageEventId) {
  const context = sourceContext(cfg, worktree, intent, 'qa', round, SOURCE_CONTROLLER);
  if (context) context.qaStageEventId = qaStageEventId;
  const { registration } = await stageQaRecords(worktree, { ...intent, round }, paths, context);
  if (smoke.length && (await git(worktree, ['add', '--', ...smoke])).code !== 0) throw new Error('qa_smoke_add_failed');
  if ((await git(worktree, [...RUNNER_ID, 'commit', '-q', '-m', message])).code !== 0) throw new Error('qa_report_commit_failed');
  if (registration) finalizeRecordRegistration(registration);
  await pushPrHead(cfg, worktree, pr);
}

const qaIssueLines = (qa) => [...qa.failed, ...qa.blocking]
  .map((i) => `- ${i.id}（对应 ${(i.covers ?? []).join('、')}${i.severity ? `，${i.severity}` : ''}）${i.scene ? `：${i.scene}` : ''}`).join('\n');
const judgeIssueLines = (j) => j.blocking
  .map((i) => `- ${i.id}（对应 ${i.covers.join('、')}，${i.severity}，${i.type}）${i.where ? `［${i.where}］` : ''}：${i.detail}`).join('\n');

/** QA 门累计花费（审计 #35）：evaluate 与 qa-fix 会话，随状态同步进 Brain，合并时汇总。 */
function addCost(s, usd) {
  if (usd === null || (typeof usd === 'number' && usd >= 0)) s.cost_usd = sumCostUsd(s.cost_usd, usd);
}

const RULING_CONFLICT_RE = /RULING_CONFLICT:\s*([^\n"\\]+)/;

/**
 * 修复没推上去（削弱测试被拦、没提交、会话失败等）：head 不变，下一轮 QA 门会按「同 head 已验过」跳过——
 * 必须立刻升级（金丝雀 3 PR #6220 静默挂住），带原因交 coding commander 裁决。
 */
function fixFailed(ctx, pr, s, intent, entry) {
  // 修复期间 PR 被关：不升级（不花 commander 的钱、不 Bark），交给外部关闭收尾（pr-closure.mjs）
  if (entry.fix === 'pr_closed') {
    ctx.log(`QA 门 PR #${pr.number} 已关闭，修复不推送，交给关闭收尾`);
    return writeState(ctx.cfg, pr.number, s);
  }
  return escalate(ctx, pr, s, intent.taskId, { type: 'qa_fix_failed', reason: entry.fix, round: entry.round, ...(entry.fix_detail ? { detail: entry.fix_detail } : {}) });
}

/**
 * 开发按验收记录（QA 报告或裁决）修复（TDD），程序核对后推送；返回 'pushed' 或失败原因。
 * 修复会话判定要修的与规格/前轮裁决矛盾（输出 RULING_CONFLICT 且没提交）→ 'ruling_conflict'，说明记进 entry.fix_detail。
 */
async function qaFix(ctx, pr, s, worktree, intent, entry, { recordFile, issues }) {
  const prior = priorJudgeFiles(worktree, intent.sprintDir, entry.round)
    .filter((f) => path.basename(f.rel) !== recordFile).map((f) => path.join(worktree, f.rel));
  const before = (await git(worktree, ['rev-parse', 'HEAD'])).stdout.trim();
  const prompt = loadPrompt('qa-fix', {
    BRANCH: pr.headRefName,
    QA_REPORT_PATH: path.join(worktree, intent.sprintDir, recordFile),
    INTENT_PATH: path.join(worktree, intent.sprintDir, '01-intent.md'),
    SPEC_PATH: path.join(worktree, intent.sprintDir, '02-spec.md'),
    QA_ISSUES: issues || '（见报告）',
    PRIOR_RULINGS: prior.length > 0 ? prior.join(', ') : '（无）',
  });
  const run = await runClaude({ args: ['-p', prompt, '--permission-mode', 'acceptEdits', ...CLAUDE_TOOLS], cwd: worktree, timeoutMs: ctx.cfg.qaFixTimeoutMs, tag: 'qa-fix', isolateRemote: true,
    transcriptPath: sessionLogPath(ctx.cfg, 'qa-fix', pr.number, Date.now()) });
  addCost(s, run.cost_usd);
  ctx.log(sessionSummary('qa-fix', pr.number, run));
  if (run.timedOut) return 'claude_timeout';
  if (run.terminated || run.code !== 0) return 'claude_failed';
  const conflict = RULING_CONFLICT_RE.exec(run.output ?? '');
  if (conflict && (await headOf(worktree)) === before) {
    entry.fix_detail = conflict[1].trim().slice(0, 500);
    return 'ruling_conflict';
  }
  try {
    await checkFixCommits(worktree, before, { smokeDir: smokeDirOf(ctx.cfg) });
    await pushPrHead(ctx.cfg, worktree, pr);
    return 'pushed';
  } catch (error) {
    return error?.message || 'qa_fix_error';
  }
}

/** 开自动合并，记 passed。 */
/** 批准：绑定验收记录推送后的 head（合并门只合并这个 head，见 merge-gate.mjs）。 */
async function approve(cfg, s, entry, worktree, intent) {
  verifySourceHead(cfg, worktree, intent, await headOf(worktree), entry.round);
  s.passed = true;
  s.approved = { head: await headOf(worktree), round: entry.round, at: new Date().toISOString() };
}

/** 最近 3 轮失败数不降 → 不收敛（coding commander 解除 qa_stalled 后从 stall_floor 之后重新计）。 */
function stalled(s) {
  const last = s.rounds.slice(s.stall_floor ?? 0).slice(-STALL_ROUNDS);
  return last.length === STALL_ROUNDS && last.every((r, i) => i === 0 || r.fails >= last[i - 1].fails) ? last.map((r) => r.fails) : null;
}

/** 跑独立裁判，结果记进 entry.judge 与 s.judge_pending/judge_bad；返回 runJudge 结果。 */
async function judgeStep(ctx, pr, s, worktree, intent, entry, sourceMode = 'pending') {
  const startedAt = Date.now();
  const j = await runJudge(ctx.cfg, worktree, intent, { round: entry.round, reportRel: entry.report, log: ctx.log,
    qaStageEventId: entry.source_stage_event_id, sourceMode, testedHead: entry.head });
  // 执行记录（决策 b34e346a）：裁判出结论记一条；不可用的每次带计数，避免同一轮重试撞幂等键
  const bad = j.error && !j.escalate ? `:e${(s.judge_bad ?? 0) + 1}` : '';
  await postSpans(ctx, [gateSpan({
    taskId: intent.taskId, key: 'judge', startedAt, endedAt: Date.now(), ok: !j.error && j.verdict === 'PASS',
    occurrence: `${pr.number}:r${entry.round}${bad}`, evidence: j.error ? { error: j.error } : { verdict: j.verdict, failure_class: j.failure_class ?? null },
  })]);
  // 需要人处理的（如改动超过裁判上限）：不算裁判坏、不重试，交 afterJudge 升级
  if (j.escalate) {
    entry.judge = { state: 'escalated', reason: j.error };
    return j;
  }
  if (j.error) {
    s.judge_bad = (s.judge_bad ?? 0) + 1;
    s.judge_pending = true;
    entry.judge = { state: 'error', reason: j.error };
    ctx.log(`QA 门 PR #${pr.number} 独立裁判不可用（连续 ${s.judge_bad} 次）：${j.error}`);
    return j;
  }
  s.judge_bad = 0;
  s.judge_pending = false;
  entry.judge = {
    verdict: j.verdict, failure_class: j.failure_class, file: j.file, model: j.model,
    issues: j.blocking.map((i) => i.id), unsatisfied: j.unsatisfied, concerns: j.concerns ?? [], usage: j.usage,
    ...(j.provider ? { provider: j.provider, cost_usd: j.cost_usd, transcript_path: j.transcript_path, input_sha256: j.input_sha256, head: entry.head } : {}),
  };
  ctx.log(`QA 门 PR #${pr.number} 第 ${entry.round} 轮独立裁判 ${j.verdict}${j.failure_class ? `（${j.failure_class}）` : ''}`);
  return j;
}

/** 裁决（已提交）之后：PASS 合并；product 修复；qa_gap 等下轮补验；contract_gap / 不收敛 / 裁判连坏 升级。 */
async function afterJudge(ctx, pr, s, worktree, intent, entry, j) {
  if (j.escalate) return escalate(ctx, pr, s, intent.taskId, { type: j.error, ...(j.diff_chars ? { diff_chars: j.diff_chars } : {}) });
  if (j.error) {
    if (s.judge_bad >= ctx.cfg.qaMaxJudgeBad) return escalate(ctx, pr, s, intent.taskId, { type: 'qa_judge_unavailable', reason: j.error });
  } else if (j.verdict === 'PASS') {
    // API 类 PR 一条回归 smoke 都没固化：不批准，交 commander 裁决（决策 4fe863c3；commander 已放行过的不再拦）
    if (s.smoke_missing && !s.smoke_waived) return escalate(ctx, pr, s, intent.taskId, { type: 'qa_smoke_missing', ...s.smoke_gap, round: entry.round });
    try { await approve(ctx.cfg, s, entry, worktree, intent); } catch (error) {
      return escalate(ctx, pr, s, intent.taskId, { type: 'source_provenance_missing', reason: error.message, head: await headOf(worktree) });
    }
  } else {
    entry.fails = Math.max(1, j.blocking.length);
    if (j.failure_class === 'ruling_conflict') {
      return escalate(ctx, pr, s, intent.taskId, {
        type: 'judge_ruling_conflict', issues: j.blocking.map((i) => i.id), reverses: j.blocking.flatMap((i) => i.reverses ?? []), file: `${intent.sprintDir}/${j.file}`,
      });
    }
    const fails = stalled(s);
    if (fails) return escalate(ctx, pr, s, intent.taskId, { type: 'qa_stalled', fails });
    if (j.failure_class === 'contract_gap') {
      return escalate(ctx, pr, s, intent.taskId, { type: 'judge_contract_gap', issues: j.blocking.map((i) => i.id), file: `${intent.sprintDir}/${j.file}` });
    }
    if (j.failure_class === 'product_failure') {
      entry.fix = await qaFix(ctx, pr, s, worktree, intent, entry, { recordFile: j.file, issues: judgeIssueLines(j) });
      if (entry.fix !== 'pushed') return fixFailed(ctx, pr, s, intent, entry);
    }
  }
  writeState(ctx.cfg, pr.number, s);
  return report(ctx, intent.taskId, s);
}

/** 检出 PR 版本到临时 worktree 跑 fn(worktree, intent)，结束清理；sprint 找不到升级。异常计入连坏。 */
async function inPrWorktree(ctx, pr, s, name, signal, fn) {
  const { cfg } = ctx;
  const worktree = path.join(cfg.worktreeBase, name);
  fs.mkdirSync(cfg.worktreeBase, { recursive: true });
  if (fs.existsSync(worktree)) await removeWorktree(cfg, worktree, null);
  fs.rmSync(worktree, { recursive: true, force: true });
  try {
    await preparePrWorktree(cfg, pr, worktree, signal);
    const intent = intentOf(worktree, pr.headRefName);
    if (!intent?.taskId) return await escalate(ctx, pr, s, null, { type: 'qa_sprint_missing' });
    return await fn(worktree, intent);
  } catch (error) {
    if (error?.message === 'pr_closed') {
      ctx.log(`QA 门 PR #${pr.number} 已关闭，验收记录不推送，交给关闭收尾`);
      return undefined;
    }
    s.bad = (s.bad ?? 0) + 1;
    ctx.log(`QA 门 PR #${pr.number} 出错：${error?.message || error}`);
    writeState(cfg, pr.number, s);
    return undefined;
  } finally {
    await removeWorktree(cfg, worktree, pr.headRefName);
    fs.rmSync(worktree, { recursive: true, force: true });
  }
}

/** 一轮 QA：evaluate → PASS 交独立裁判 / FAIL 修复或升级；验收记录提交进 PR。 */
async function qaRound(ctx, pr, s, signal) {
  const { cfg } = ctx;
  const round = s.rounds.length + 1;
  const prior = s.rounds.at(-1)?.judge;
  return inPrWorktree(ctx, pr, s, `qa-${pr.number}-${round}`, signal, async (worktree, intent) => {
    // 检出的必须正是列表里的 head（列表之后又推了代码 → 本轮不验，下轮按新 head 来，不计坏）
    const checkedOut = await headOf(worktree);
    if (checkedOut !== pr.headRefOid) {
      ctx.log(`QA 门 PR #${pr.number}：检出的 ${checkedOut.slice(0, 9)} 不是列表里的 head ${pr.headRefOid.slice(0, 9)}，下轮再验`);
      return undefined;
    }
    try { verifySourceHead(cfg, worktree, intent, checkedOut); } catch (error) {
      return escalate(ctx, pr, s, intent.taskId, { type: 'source_provenance_missing', reason: error.message, head: checkedOut });
    }
    ctx.log(`QA 门 PR #${pr.number} 第 ${round} 轮AI QA 开始`);
    // QA 会话执行记录落在 runner 日志目录（判越界、证据不实时可复核）
    const transcript = prFile(cfg, `qa-${pr.number}-r${round}.jsonl`);
    const evalStartedAt = Date.now();
    const result = await evaluate(ctx, worktree, {
      run_tag: `qa-${pr.number}-r${round}`, task_id: intent.taskId, worktree, sprint_dir: intent.sprintDir,
      intent_ids: intent.intentIds, intent_sha256: intent.intentSha256, pr_number: pr.number, round, head_sha: pr.headRefOid,
      transcript_path: transcript,
      // 活动层按仓库参数化（C6）：QA 模式（预览 / local）、碰生产口径随本仓 repos.json 条目走
      ...(cfg.repoProfile ? { repo_profile: cfg.repoProfile } : {}),
      ...(prior?.failure_class === 'qa_insufficient' ? { judge_feedback: `${intent.sprintDir}/${prior.file}` } : {}),
      // 重试必须带新信息（审计 #33）：上次评估不合格的原因交给这次
      ...(s.last_eval_error ? { prev_errors: `${s.last_eval_error.reason_code}: ${s.last_eval_error.evidence}` } : {}),
      budget: { max_duration_s: Math.round(EVALUATE_TIMEOUT_MS / 1000) },
    }, signal);
    const qa = result?.status === 'completed' ? result.outputs?.qa : null;
    // 执行记录（决策 b34e346a）：每次评估一条；评估出错按连续次数区分幂等键
    await postSpans(ctx, [gateSpan({
      taskId: intent.taskId, key: 'qa', startedAt: evalStartedAt, endedAt: Date.now(), ok: qa?.verdict === 'PASS', costUsd: qa?.cost_usd,
      occurrence: `${pr.number}:r${round}${qa ? '' : `:e${(s.bad ?? 0) + 1}`}`,
      evidence: qa ? { verdict: qa.verdict, fails: qa.failed.length + qa.blocking.length } : { reason_code: result?.reason_code ?? 'evaluate_crashed' },
    })]);
    if (!qa) {
      s.bad = (s.bad ?? 0) + 1;
      const reason = result?.reason_code ?? 'evaluate_crashed';
      ctx.log(`QA 门 PR #${pr.number} 评估出错（连续 ${s.bad} 次）：${reason} ${JSON.stringify(result?.evidence ?? []).slice(0, 500)}`);
      s.last_eval_error = { reason_code: reason, evidence: JSON.stringify(result?.evidence ?? []).slice(0, 1500) };
      if (result?.failure_class === 'fatal' || result?.failure_class === 'needs_human' || s.bad >= cfg.qaMaxBadStreak) {
        return escalate(ctx, pr, s, intent.taskId, { type: 'qa_evaluator_broken', reason_code: reason, evidence: result?.evidence ?? [], transcript });
      }
      writeState(cfg, pr.number, s);
      return undefined;
    }
    s.bad = 0;
    delete s.last_eval_error;
    const fails = qa.failed.length + qa.blocking.length;
    const report0 = `${intent.sprintDir}/${result.outputs.qa_report_file}`;
    // 验不了的项全部已被 commander 裁过接受且无失败 → 按 PASS 交独立裁判，不再重复升级
    const cvAccepted = qa.verdict === 'CANNOT_VERIFY' && fails === 0 ? cannotVerifyAccepted(cfg, pr.number, qa.cannot_verify) : null;
    const verdict = cvAccepted ? 'PASS' : qa.verdict;
    const label = cvAccepted ? 'CANNOT_VERIFY（commander 已裁接受）' : qa.verdict;
    const entry = { round, head: pr.headRefOid, verdict, fails, report: report0, env_url: qa.env?.url, cost_usd: qa.cost_usd, at: new Date().toISOString(),
      ...(result.outputs.source_stage_event_id ? { source_stage_event_id: result.outputs.source_stage_event_id } : {}),
      ...(cvAccepted ? { qa_verdict: qa.verdict, cv_accepted: cvAccepted } : {}) };
    addCost(s, qa.cost_usd);
    ctx.log(`QA 门 PR #${pr.number} 第 ${round} 轮 ${label}（失败 ${fails}）`);
    const records = [report0, `${intent.sprintDir}/qa-r${round}`];
    // 记录提交成功才算这一轮（提交失败下轮同一 head 重验，裁判计数回滚）
    const commit = async (message, smoke = []) => {
      const snapshot = { judge_bad: s.judge_bad, judge_pending: s.judge_pending };
      try {
        await commitRecords(cfg, worktree, pr, records, message, intent, round, smoke, entry.source_stage_event_id);
      } catch (error) {
        Object.assign(s, snapshot);
        throw error;
      }
      s.rounds.push(entry);
    };
    if (verdict === 'PASS' && cfg.judge) {
      const j = await judgeStep(ctx, pr, s, worktree, intent, entry);
      if (j.file) records.push(`${intent.sprintDir}/${j.file}`);
      const smoke = !j.error && j.verdict === 'PASS' ? await solidifyQa(ctx, pr, s, round, worktree, intent, result.outputs.qa_report_file, qa.env?.url) : [];
      await commit(`docs(qa): 第 ${round} 轮AI QA ${label}，${j.error ? '独立裁判待定' : `独立裁判 ${j.verdict}`}`, smoke);
      return afterJudge(ctx, pr, s, worktree, intent, entry, j);
    }
    await commit(`docs(qa): 第 ${round} 轮AI QA ${label}`);
    if (verdict === 'PASS') {
      // 裁判是合并的必要条件（审计 #32）：关掉裁判时不批准，交人审
      return escalate(ctx, pr, s, intent.taskId, { type: 'judge_disabled', round });
    } else if (qa.verdict === 'CANNOT_VERIFY') {
      // 验不了 ≠ 产品不合格（审计 #38/#19）：进修复环只会无限改代码，交 coding commander 判断（补工具 / 改场景 / 人验）
      return escalate(ctx, pr, s, intent.taskId, { type: 'qa_cannot_verify', round, cannot_verify: qa.cannot_verify ?? [] });
    } else {
      const stall = stalled(s);
      if (stall) return escalate(ctx, pr, s, intent.taskId, { type: 'qa_stalled', fails: stall });
      entry.fix = await qaFix(ctx, pr, s, worktree, intent, entry, { recordFile: result.outputs.qa_report_file, issues: qaIssueLines(qa) });
      if (entry.fix !== 'pushed') return fixFailed(ctx, pr, s, intent, entry);
    }
    writeState(cfg, pr.number, s);
    return report(ctx, intent.taskId, s);
  });
}

/** 上一轮 QA PASS 但裁判没出结果：只重跑裁判（QA 报告已在 PR 分支上）。 */
async function judgeRound(ctx, pr, s, signal) {
  const entry = s.rounds.at(-1);
  return inPrWorktree(ctx, pr, s, `qa-${pr.number}-j${entry.round}`, signal, async (worktree, intent) => {
    const j = await judgeStep(ctx, pr, s, worktree, intent, entry, 'registered');
    const smoke = !j.error && j.verdict === 'PASS' && entry.report
      ? await solidifyQa(ctx, pr, s, entry.round, worktree, intent, path.basename(entry.report), entry.env_url) : [];
    if (j.file) await commitRecords(ctx.cfg, worktree, pr, [`${intent.sprintDir}/${j.file}`], `docs(qa): 第 ${entry.round} 轮独立裁判 ${j.verdict}`, intent, entry.round, smoke, entry.source_stage_event_id);
    return afterJudge(ctx, pr, s, worktree, intent, entry, j);
  });
}

/** 本轮至多验一个 PR；真跑了 QA 或裁判（无论结果）返回 true，没有可验的返回 false。不抛错。 */
export async function runQaGate(ctx, signal) {
  const { cfg } = ctx;
  try {
    const prs = await listOwnPrs(cfg);
    if (!prs) return false;
    for (const pr of prs) {
      const s = readState(cfg, pr.number);
      if (s.escalated || s.passed) continue;
      // 裁判待定：不等 CI、不重跑 QA，只补裁判
      if (s.judge_pending && cfg.judge && s.rounds.at(-1)?.verdict === 'PASS') {
        await judgeRound(ctx, pr, s, signal);
        return true;
      }
      // 同 head 验过就不重验；上一轮修复因 PR 被关没推上去（之后重开）的除外
      if (s.rounds.at(-1)?.head === pr.headRefOid && s.rounds.at(-1)?.fix !== 'pr_closed') continue;
      if ((await requiredState(cfg, pr.number)).state !== 'pass') continue;
      // local 模式（zenithjoy 第一阶段，C6）：不起预览，evaluate 在 PR worktree 里黑盒验
      if (cfg.previewType === 'local') {
        await qaRound(ctx, pr, s, signal);
        return true;
      }
      // 其他未接入的 QA 模式不验，同一 head 只记一行
      if (!usesBrainPreview(cfg)) {
        if (s.qa_unsupported !== pr.headRefOid) {
          ctx.log(`QA 门 ${prLabel(cfg, pr.number)}：本仓 QA 模式 ${cfg.previewType} 尚未接入，不验（不批准、不合并）`);
          writeState(cfg, pr.number, { ...s, qa_unsupported: pr.headRefOid });
        }
        continue;
      }
      // 预览部署的必须正是这个 head（审计 P0 #2）：推送后还没重新部署就等
      const p = await previewOf(pr.number, { api: cfg.previewApi, host: cfg.previewHost, expectSha: pr.headRefOid });
      if (p.state !== 'pending' && p.state !== 'error') clearPreviewWait(ctx, pr, s, writeState);
      if (p.state === 'stale') {
        await previewStale(ctx, pr, s, p);
        continue;
      }
      if (p.state !== 'active') {
        await ensurePreview(ctx, pr, s, p);
        continue;
      }
      await qaRound(ctx, pr, s, signal);
      return true;
    }
  } catch (error) {
    ctx.log(`QA 门出错：${error?.message || error}`);
  }
  return false;
}

// 仓库配置表（C4）：coding-workflow/repos.json 是 runner 多仓库口径的唯一来源。
// 本模块负责：读表校验、仓库名别名归一（短名 / owner/repo / https / ssh URL / 缺省）、CODING_WF_REPOS 开关、
// 每仓库运行时视图（repoView：把 cfg 的 clone / worktree 根 / 状态命名空间换成该仓库的），以及按仓库分命名空间的状态路径。
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
export const REPOS_FILE = path.join(HERE, '../../repos.json');

/** 配置表路径：CODING_WF_REPOS_FILE 覆盖（测试 / 演练用；生产不设）。 */
export function reposFile(env = process.env) {
  return env.CODING_WF_REPOS_FILE || REPOS_FILE;
}
export const REQUIRED_FIELDS = ['key', 'default', 'enabled', 'slug', 'origin', 'aliases', 'clone', 'worktree_base', 'state_ns',
  'required_checks', 'base_fresh_check', 'install', 'qa_smoke', 'version_fragment', 'preview', 'production_re', 'automerge',
